func TestDashboardDetailsThroughService(t *testing.T) {
	service, repo, _, _, _ := newServiceFixture(t)
	if err := os.WriteFile(
		filepath.Join(repo.Dir(), config.DashboardsFilename),
		[]byte("schema_version: 1\ndashboards: []\n"),
		0o600,
	); err != nil {
		t.Fatal(err)
	}
