	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: root, IsRoot: true}}); saveErr != nil {
		t.Fatalf("save workspace sources: %v", saveErr)
	}

	workspaces, err := repo.ListWorkspaces()
	if err != nil {
		t.Fatalf("list workspaces: %v", err)
