internal/session/shutdown_test.go.source:
package session_test

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
)

func TestShutdownJoinsStopAlreadyInProgress(t *testing.T) {
	entered := make(chan struct{}, 1)
	gate := make(chan struct{})
	h := newGateHarness(t, false, func(_ int, d *gateDriver) {
		d.killEntered, d.killGate = entered, gate
	})
	sessionID, err := testLaunch(h.sm, h.card, nil, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	stopDone := make(chan error, 1)
	go func() { stopDone <- h.sm.Kill(sessionID) }()
	waitSignal(t, entered, "stop to enter driver teardown")
	shutdownDone := make(chan int, 2)
	go func() { shutdownDone <- h.sm.Shutdown() }()
	go func() { shutdownDone <- h.sm.Shutdown() }()
	select {
	case <-shutdownDone:
		t.Fatal("shutdown returned before the in-flight stop completed")
	case <-time.After(50 * time.Millisecond):
	}
	close(gate)
	if stopErr := waitErr(t, stopDone, "in-flight stop"); stopErr != nil {
		t.Fatalf("stop: %v", stopErr)
	}
	for range 2 {
		select {
		case <-shutdownDone:
		case <-time.After(2 * time.Second):
			t.Fatal("shutdown caller did not join stop")
		}
	}
}

// persistedStatus reads a session's status straight from its JSON record.
func persistedStatus(t *testing.T, configDir, sid string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(configDir, "sessions", sid+".json"))
	if err != nil {
		t.Fatalf("read record: %v", err)
	}
	var rec struct {
		Status string `json:"status"`
	}
	if err = json.Unmarshal(raw, &rec); err != nil {
		t.Fatalf("parse record: %v", err)
	}
	return rec.Status
}

// TestShutdownStopsWatchersBeforeTheyPersist pins two things about the stop
// channel. (1) Shutdown must not wait for a watcher's next tick: the WaitGroup
// alone would still make it return only after the watcher persisted, so the
// duration is what proves stop works, and what keeps quitting the app quick.
// (2) Nothing writes after Shutdown returns. That is the one place a sleep is
// the point: a leftover watcher only acts on its next tick (watchInterval, 2s,
// unexported), so the test waits past it and checks that the sessions
// directory it deleted does not come back.
func TestShutdownStopsWatchersBeforeTheyPersist(t *testing.T) {
	h := newGateHarness(t, false, nil)
	if _, err := testLaunch(h.sm, h.card, nil, nil, nil); err != nil {
		t.Fatalf("launch: %v", err)
	}

	// Launched right before: the watcher's first tick is about 2s away.
	start := time.Now()
	h.sm.Shutdown()
	if d := time.Since(start); d > time.Second {
		t.Fatalf("Shutdown took %v: watchers are not stopped, it waited for their tick", d)
	}

	sessionsDir := filepath.Join(h.repoDir, "sessions")
	if err := os.RemoveAll(sessionsDir); err != nil {
		t.Fatal(err)
	}
	time.Sleep(2*time.Second + 500*time.Millisecond) // watchInterval + margin

	if _, err := os.Stat(sessionsDir); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a watcher outlived Shutdown and wrote to disk (stat err: %v)", err)
	}
}

// TestActivationAfterShutdownIsRefused: once Shutdown has run, nothing may
// start a process the manager could no longer stop or watch.
func TestActivationAfterShutdownIsRefused(t *testing.T) {
	h := newGateHarness(t, false, nil)
	sid := h.launchTerminated(t)
	spawnsBefore := h.spawns.Load()

	h.sm.Shutdown()

	if _, err := testLaunch(h.sm, h.card, nil, nil, nil); !errors.Is(err, session.ErrManagerClosed) {
		t.Fatalf("Launch: want ErrManagerClosed, got %v", err)
	}
	if err := testRelaunch(h.sm, sid, h.card); !errors.Is(err, session.ErrManagerClosed) {
		t.Fatalf("Relaunch: want ErrManagerClosed, got %v", err)
	}
	if err := testSwitchAgent(h.sm, sid, h.card, nil, nil, nil); !errors.Is(err, session.ErrManagerClosed) {
		t.Fatalf("SwitchAgent: want ErrManagerClosed, got %v", err)
	}
	if got := h.spawns.Load(); got != spawnsBefore {
		t.Fatalf("Spawn was called %d time(s) after Shutdown", got-spawnsBefore)
	}
}

// onceCloser returns a func that closes ch at most once. Registered as a
// cleanup, it opens a gate that a failed assertion left shut, so the cleanup
// Shutdown of the test's manager can finish instead of waiting forever.
func onceCloser(t *testing.T, ch chan struct{}) func() {
	t.Helper()
	var once sync.Once
	closeOnce := func() { once.Do(func() { close(ch) }) }
	t.Cleanup(closeOnce)
	return closeOnce
}

// shutdownAsync runs Shutdown in a goroutine and returns a channel that
// receives once it has returned.
func shutdownAsync(sm *session.Manager) <-chan struct{} {
	returned := make(chan struct{})
	go func() {
		sm.Shutdown()
		close(returned)
	}()
	return returned
}

// assertStillBlocked fails if ch is closed within a short window. The window
// is the point of these tests: "has not returned yet" can only be observed by
// waiting, and a Shutdown that wrongly returns does so at once.
func assertStillBlocked(t *testing.T, ch <-chan struct{}, why string) {
	t.Helper()
	select {
	case <-ch:
		t.Fatalf("Shutdown returned early: %s", why)
	case <-time.After(100 * time.Millisecond):
	}
}

// TestShutdownDuringSpawnKillsTheNewProcess: a Relaunch whose Spawn is still
// in flight when Shutdown runs must not leave the process it spawns behind.
// Shutdown has to wait for the activation to reach its final check and kill
// that process: main returns right after Shutdown, so anything left for the
// activation goroutine to do "later" would never happen.
func TestShutdownDuringSpawnKillsTheNewProcess(t *testing.T) {
	entered, gate := make(chan struct{}, 1), make(chan struct{})
	var second *gateDriver
	h := newGateHarness(t, false, func(n int, d *gateDriver) {
		if n == 1 {
			d.spawnEntered, d.spawnGate = entered, gate
			second = d
		}
	})
	openGate := onceCloser(t, gate) // after the harness: cleanups run last-in-first-out
	sid := h.launchTerminated(t)

	result := make(chan error, 1)
	go func() { result <- testRelaunch(h.sm, sid, h.card) }()
	waitSignal(t, entered, "Relaunch to enter Spawn")

	returned := shutdownAsync(h.sm)
	assertStillBlocked(t, returned, "a Relaunch is still spawning")

	openGate()
	waitSignal(t, returned, "Shutdown to return once the Relaunch finished")
	if err := waitErr(t, result, "Relaunch"); !errors.Is(err, session.ErrManagerClosed) {
		t.Fatalf("Relaunch: want ErrManagerClosed, got %v", err)
	}
	if !second.terminated.Load() {
		t.Fatal("the process spawned during Shutdown was left running")
	}
	snap, _ := h.sm.GetSession(sid)
	if snap.Status != session.StatusTerminated {
		t.Fatalf("session must stay Terminated, got %s", snap.Status)
	}
}

// TestShutdownDuringTmpLaunchRemovesTheCopy: same for a new temporary-workspace
// Launch, whose workspace copy would otherwise stay behind with no record
// pointing at it.
func TestShutdownDuringTmpLaunchRemovesTheCopy(t *testing.T) {
	entered, gate := make(chan struct{}, 1), make(chan struct{})
	var first *gateDriver
	h := newGateHarness(t, true, func(n int, d *gateDriver) {
		if n == 0 {
			d.spawnEntered, d.spawnGate = entered, gate
			first = d
		}
	})
	openGate := onceCloser(t, gate)         // after the harness: cleanups run last-in-first-out
	tmpRoot := os.Getenv("KANKURO_TMP_DIR") // set by newGateHarness for useTmp

	result := make(chan error, 1)
	go func() {
		_, err := testLaunch(h.sm, h.card, nil, nil, nil)
		result <- err
	}()
	waitSignal(t, entered, "Launch to enter Spawn")
	if entries, _ := os.ReadDir(tmpRoot); len(entries) != 1 {
		t.Fatalf("expected one workspace copy while the Launch is in flight, got %d", len(entries))
	}

	returned := shutdownAsync(h.sm)
	assertStillBlocked(t, returned, "a Launch is still spawning")

	openGate()
	waitSignal(t, returned, "Shutdown to return once the Launch finished")
	if err := waitErr(t, result, "Launch"); !errors.Is(err, session.ErrManagerClosed) {
		t.Fatalf("Launch: want ErrManagerClosed, got %v", err)
	}
	if !first.terminated.Load() {
		t.Fatal("the process spawned during Shutdown was left running")
	}
	if entries, _ := os.ReadDir(tmpRoot); len(entries) != 0 {
		t.Fatalf("workspace copy left behind after Shutdown: %d entries in %s", len(entries), tmpRoot)
	}
}

func TestShutdownWaitsForTemporaryWorkspacePreparation(t *testing.T) {
	configDir, tmpRoot, workspace := t.TempDir(), t.TempDir(), t.TempDir()
	t.Setenv("KANKURO_TMP_DIR", tmpRoot)
	repo, setupErr := config.NewFileRepository(configDir)
	if setupErr != nil {
		t.Fatal(setupErr)
	}
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, listErr := repo.ListWorkspaces()
	if listErr != nil || len(workspaces) != 1 {
		t.Fatalf("list workspace: %v", listErr)
	}
	copyEntered, releaseCopy := make(chan struct{}), make(chan struct{})
	manager := newTestManager(t, configDir, repo, session.WithWorkspaceCopier(func(_ context.Context, _, destination string) error {
		close(copyEntered)
		<-releaseCopy
		return os.MkdirAll(destination, 0o700)
	}))
	release := onceCloser(t, releaseCopy)
	card := config.IDCard{ID: "copy-cancel", Name: "copy cancellation", Driver: "cat",
		WorkspaceID: workspaces[0].ID, UseTmpWorkspace: true}
	launchResult := make(chan error, 1)
	go func() {
		_, launchErr := testLaunch(manager, card, nil, nil, nil)
		launchResult <- launchErr
	}()
	waitSignal(t, copyEntered, "temporary workspace copy")
	shutdownReturned := shutdownAsync(manager)
	assertStillBlocked(t, shutdownReturned, "a launch is still preparing its temporary copy")
	release()
	waitSignal(t, shutdownReturned, "shutdown after workspace preparation completes")
	if launchErr := waitErr(t, launchResult, "launch cancelled by shutdown"); !errors.Is(launchErr, session.ErrManagerClosed) {
		t.Fatalf("launch during shutdown = %v, want manager-closed", launchErr)
	}
	entries, readErr := os.ReadDir(tmpRoot)
	if readErr != nil || len(entries) != 0 {
		t.Fatalf("shutdown left a temporary workspace copy: %v (%v)", entries, readErr)
	}
}

func TestShutdownIsIdempotent(t *testing.T) {
	h := newGateHarness(t, false, nil)
	if _, err := testLaunch(h.sm, h.card, nil, nil, nil); err != nil {
		t.Fatalf("launch: %v", err)
	}

	if got := h.sm.Shutdown(); got != 1 {
		t.Fatalf("first Shutdown: want 1 running session, got %d", got)
	}

	done := make(chan int, 1)
	go func() { done <- h.sm.Shutdown() }()
	select {
	case got := <-done:
		if got != 0 {
			t.Fatalf("second Shutdown: nothing was running, got %d", got)
		}
	case <-time.After(time.Second):
		t.Fatal("second Shutdown did not return promptly")
	}
}

// TestShutdownKillsSessionsInParallel: with a graceful stop per agent, killing
// one after another would take N grace periods. Two sessions whose Kill takes
// 300ms must be gone in about one.
func TestShutdownKillsSessionsInParallel(t *testing.T) {
	const killTime = 300 * time.Millisecond
	h := newGateHarness(t, false, func(_ int, d *gateDriver) { d.killDelay = killTime })

	var sids []string
	for range 2 {
		sid, err := testLaunch(h.sm, h.card, nil, nil, nil)
		if err != nil {
			t.Fatalf("launch: %v", err)
		}
		sids = append(sids, sid)
	}

	start := time.Now()
	got := h.sm.Shutdown()
	elapsed := time.Since(start)

	if got != 2 {
		t.Fatalf("Shutdown reported %d running sessions, want 2", got)
	}
	if elapsed >= 500*time.Millisecond {
		t.Fatalf("Shutdown took %v; sessions are being killed one after another", elapsed)
	}
	for _, sid := range sids {
		snap, _ := h.sm.GetSession(sid)
		if snap.Status != session.StatusTerminated {
			t.Fatalf("session %s: want Terminated, got %s", sid, snap.Status)
		}
		if st := persistedStatus(t, h.repoDir, sid); st != "terminated" {
			t.Fatalf("session %s: persisted status %q, want terminated", sid, st)
		}
	}
}

internal/session/startup_boundary_test.g.source:
//nolint:testpackage // Exercises locked activation transitions and stale callbacks.
package session

import (
	"bytes"
	"errors"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/driver"
)

type controlledStartupTimer struct {
	ready   chan time.Time
	stopped chan struct{}
	once    sync.Once
}

func (t *controlledStartupTimer) C() <-chan time.Time { return t.ready }
func (t *controlledStartupTimer) Stop() bool          { t.once.Do(func() { close(t.stopped) }); return true }

type controlledStartupClock struct {
	mu        sync.Mutex
	now       time.Time
	created   chan *controlledStartupTimer
	durations chan time.Duration
}

func (c *controlledStartupClock) Now() time.Time { c.mu.Lock(); defer c.mu.Unlock(); return c.now }
func (c *controlledStartupClock) NewTimer(d time.Duration) StartupTimer {
	timer := &controlledStartupTimer{ready: make(chan time.Time, 1), stopped: make(chan struct{})}
	c.durations <- d
	c.created <- timer
	return timer
}
func (c *controlledStartupClock) advance(d time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(d)
	c.mu.Unlock()
}
func waitStartupSignal(t *testing.T, ch <-chan struct{}) {
	t.Helper()
	select {
	case <-ch:
	case <-time.After(3 * time.Second):
		t.Fatal("timer did not stop")
	}
}
func startControlledTimer(t *testing.T, m *Manager, id string, clock *controlledStartupClock, deadline time.Time) *controlledStartupTimer {
	t.Helper()
	m.mu.Lock()
	m.startupClock = clock
	m.startupDelay = 10 * time.Second
	m.startStartupLocked(m.sessions[id], deadline)
	m.mu.Unlock()
	select {
	case timer := <-clock.created:
		return timer
	case <-time.After(3 * time.Second):
		t.Fatal("timer not created")
		return nil
	}
}
func newControlledStartupClock() *controlledStartupClock {
	return &controlledStartupClock{
		now: time.Unix(100, 0), created: make(chan *controlledStartupTimer, 4),
		durations: make(chan time.Duration, 4),
	}
}

func TestStartupAdmissionAndRegistrationAreIndependent(t *testing.T) {
	m, _, senderToken, recipientID, activation := newReviewMessagingManager(t)
	clock := newControlledStartupClock()
	deadline := clock.Now().Add(10 * time.Second)
	clock.advance(4 * time.Second)
	timer := startControlledTimer(t, m, recipientID, clock, deadline)
	if duration := <-clock.durations; duration != 6*time.Second {
		t.Fatalf("timer duration = %v, want remaining six seconds", duration)
	}
	m.mu.RLock()
	recipientToken := m.sessions[recipientID].ActivationToken
	m.mu.RUnlock()
	result, err := m.RegisterConversation(recipientToken, "native-id", "recipient")
	if err != nil || result.Status != RegistrationRegistered || result.Persistence != RegistrationSaved {
		t.Fatalf("registration = %+v, %v", result, err)
	}
	snap, _ := m.GetSession(recipientID)
	if snap.Phase != "starting" || !snap.ProcessStarted || snap.MessageDeliveryAvailable {
		t.Fatalf("starting snapshot = %+v", snap)
	}
	if admission, admissionErr := m.ReserveMessageAdmission(senderToken, recipientID, activation); admissionErr == nil {
		admission.Release()
		t.Fatal("starting recipient accepted a message")
	} else {
		var failure *MessagingError
		if !errors.As(admissionErr, &failure) || failure.Code != "starting" {
			t.Fatalf("starting rejection = %v", admissionErr)
		}
	}
	timer.ready <- deadline
	waitStartupSignal(t, timer.stopped)
	snap, _ = m.GetSession(recipientID)
	if snap.Phase != "active" || !snap.MessageDeliveryAvailable {
		t.Fatalf("active snapshot = %+v", snap)
	}
	admission, err := m.ReserveMessageAdmission(senderToken, recipientID, activation)
	if err != nil {
		t.Fatal(err)
	}
	admission.Release()
}

func TestStaleStartupCallbackCannotEnableReplacement(t *testing.T) {
	m, _, _, recipientID, _ := newReviewMessagingManager(t)
	clock := newControlledStartupClock()
	first := startControlledTimer(t, m, recipientID, clock, clock.Now().Add(10*time.Second))
	<-clock.durations
	m.mu.Lock()
	item := m.sessions[recipientID]
	first.ready <- clock.Now()
	m.cancelStartupLocked(item)
	item.generation++
	m.startStartupLocked(item, clock.Now().Add(10*time.Second))
	m.mu.Unlock()
	second := <-clock.created
	<-clock.durations
	waitStartupSignal(t, first.stopped)
	snap, _ := m.GetSession(recipientID)
	if snap.Phase != "starting" || snap.MessageDeliveryAvailable {
		t.Fatalf("stale timer enabled replacement: %+v", snap)
	}
	second.ready <- clock.Now()
	waitStartupSignal(t, second.stopped)
	snap, _ = m.GetSession(recipientID)
	if snap.Phase != "active" || !snap.MessageDeliveryAvailable {
		t.Fatalf("replacement did not become active: %+v", snap)
	}
}

func TestStartupTimerStopsOnKillAndShutdown(t *testing.T) {
	for _, shutdown := range []bool{false, true} {
		t.Run(map[bool]string{false: "kill", true: "shutdown"}[shutdown], func(t *testing.T) {
			m, _, _, id, _ := newReviewMessagingManager(t)
			clock := newControlledStartupClock()
			timer := startControlledTimer(t, m, id, clock, clock.Now().Add(10*time.Second))
			<-clock.durations
			if shutdown {
				m.Shutdown()
			} else if err := m.Kill(id); err != nil {
				t.Fatal(err)
			}
			waitStartupSignal(t, timer.stopped)
			snap, _ := m.GetSession(id)
			if snap.ProcessStarted || snap.MessageDeliveryAvailable || snap.Phase != "terminated" {
				t.Fatalf("terminated snapshot = %+v", snap)
			}
		})
	}
}

func TestStartupNaturalExitRevokesCredentialAndStopsTimer(t *testing.T) {
	m, _, _, id, _ := newReviewMessagingManager(t)
	clock := newControlledStartupClock()
	timer := startControlledTimer(t, m, id, clock, clock.Now().Add(10*time.Second))
	<-clock.durations
	m.mu.RLock()
	item := m.sessions[id]
	token, d := item.ActivationToken, item.Driver
	m.mu.RUnlock()
	if err := d.Kill(); err != nil {
		t.Fatal(err)
	}
	waitStartupSignal(t, timer.stopped)
	deadline := time.After(3 * time.Second)
	for {
		snap, _ := m.GetSession(id)
		if snap.Status == StatusTerminated {
			if snap.ProcessStarted || snap.MessageDeliveryAvailable || m.HasActivationCredential(token) {
				t.Fatalf("exit left live activation: %+v", snap)
			}
			break
		}
		select {
		case <-deadline:
			t.Fatalf("natural exit not observed: %+v", snap)
		default:
			time.Sleep(time.Millisecond)
		}
	}
}

func TestStartupInvalidationPreventsIntentPublication(t *testing.T) {
	m, _, senderToken, id, activation := newReviewMessagingManager(t)
	admission, err := m.ReserveMessageAdmission(senderToken, id, activation)
	if err != nil {
		t.Fatal(err)
	}
	defer admission.Release()
	if err = m.Kill(id); err != nil {
		t.Fatal(err)
	}
	published := false
	err = m.PublishMessageAdmission(admission, func() error { published = true; return nil })
	if err == nil || published {
		t.Fatalf("invalidated admission published: %v", err)
	}
}

func TestStartupOutputUsesNormalBoundedStream(t *testing.T) {
	m, _, _, id, _ := newReviewMessagingManager(t)
	clock := newControlledStartupClock()
	timer := startControlledTimer(t, m, id, clock, clock.Now().Add(10*time.Second))
	<-clock.durations
	output := make(chan []byte, 2)
	subscription, err := m.SubscribeOutput(id)
	if err != nil {
		t.Fatal(err)
	}
	defer m.UnsubscribeOutput(id, subscription)
	m.mu.RLock()
	generation := m.sessions[id].generation
	subscribers := m.sessions[id].Subscribers
	m.mu.RUnlock()
	done := make(chan struct{})
	go func() { defer close(done); m.trackOutput(id, generation, output, subscribers) }()
	payload := []byte("startup-marker\n")
	output <- payload
	select {
	case got := <-subscription:
		if string(got) != string(payload) {
			t.Fatalf("subscriber output = %q", got)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("startup output not broadcast")
	}
	if got := string(m.GetScrollback(id)); !strings.Contains(got, string(payload)) {
		t.Fatalf("startup output absent from scrollback: %q", got)
	}
	output <- bytes.Repeat([]byte("x"), ScrollbackLimit+10)
	close(output)
	waitStartupSignal(t, done)
	if got := m.GetScrollback(id); len(got) != ScrollbackLimit {
		t.Fatalf("scrollback length = %d", len(got))
	}
	timer.ready <- clock.Now()
	waitStartupSignal(t, timer.stopped)
}

type drainBlockingDriver struct {
	driver.AgentDriver

	drained <-chan struct{}
}

func (d *drainBlockingDriver) Kill() error { <-d.drained; return nil }
func TestUnpublishedTeardownDrainsAndJoins(t *testing.T) {
	output := make(chan []byte)
	drained := make(chan struct{})
	go func() { output <- []byte("blocked output"); close(drained) }()
	done := make(chan error, 1)
	go func() { done <- teardownUnpublished(&drainBlockingDriver{drained: drained}, output) }()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("teardown failed to drain output")
	}
}

internal/session/startup_integration_tes.source:
package session_test

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/google/uuid"
)

type startupDriver struct {
	*driver.GenericCLIDriver

	prepared chan string
}

func (d *startupDriver) PrepareWorkspace(ctx context.Context, path string) error {
	d.prepared <- path
	return ctx.Err()
}
func (d *startupDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	select {
	case path := <-d.prepared:
		if path != cfg.WorkingDir {
			return nil, errors.New("wrong workspace")
		}
	default:
		return nil, errors.New("spawn before trust preparation")
	}
	return d.GenericCLIDriver.Spawn(cfg)
}

type testStartupTimer struct{ ready chan time.Time }

func (t *testStartupTimer) C() <-chan time.Time { return t.ready }
func (*testStartupTimer) Stop() bool            { return true }

type testStartupClock struct {
	timer   *testStartupTimer
	entered chan struct{}
}

func (*testStartupClock) Now() time.Time { return time.Unix(100, 0) }
func (c *testStartupClock) NewTimer(_ time.Duration) session.StartupTimer {
	close(c.entered)
	return c.timer
}

func TestActivationPublishedBeforeStartupDelay(t *testing.T) {
	repo, workspaceID := workspaceValidationRepository(t)
	registry := driver.NewRegistry()
	registry.Register("cat", func() driver.AgentDriver { return &startupDriver{driver.NewGenericCLIDriver(), make(chan string, 1)} })
	clock := &testStartupClock{timer: &testStartupTimer{ready: make(chan time.Time, 1)}, entered: make(chan struct{})}
	manager := newTestManager(
		t,
		repo.Dir(),
		repo,
		session.WithDriverRegistry(registry),
		session.WithStartupClock(clock),
		session.WithStartupDelay(10*time.Second),
	)
	id := uuid.NewString()
	_, err := testLaunchWithIDContext(manager,
		context.Background(),
		id,
		config.IDCard{ID: "a", Name: "a", Driver: "cat", WorkspaceID: workspaceID, UseTmpWorkspace: true},
		nil,
		nil,
		nil,
	)
	if err != nil {
		t.Fatal(err)
	}
	<-clock.entered
	snap, ok := manager.GetSession(id)
	if !ok || !snap.UseTmpWorkspace || !snap.ProcessStarted || snap.Phase != "starting" || snap.MessageDeliveryAvailable {
		t.Fatalf("unexpected startup snapshot: %+v", snap)
	}
	if handle, attachErr := testAttach(manager, id); attachErr != nil {
		t.Fatal(attachErr)
	} else {
		handle.Close()
	}
	clock.timer.ready <- time.Unix(110, 0)
	deadline := time.After(2 * time.Second)
	for {
		snap, _ = manager.GetSession(id)
		if snap.Phase == "active" {
			break
		}
		select {
		case <-deadline:
			t.Fatalf("startup transition did not complete: %+v", snap)
		default:
			time.Sleep(time.Millisecond)
		}
	}
	if snap.MessageDeliveryAvailable {
		t.Fatal("MCP-disabled activation accepted delivery")
	}
}

//nolint:gocognit // The table checks publication, disk persistence, and cleanup together.
func TestCreationNameIsSavedAtPublication(t *testing.T) {
	repo, workspaceID := workspaceValidationRepository(t)
	registry := driver.NewRegistry()
	registry.Register("cat", func() driver.AgentDriver { return &startupDriver{driver.NewGenericCLIDriver(), make(chan string, 1)} })
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
	card := config.IDCard{ID: "card", Name: "default", Driver: "cat", WorkspaceID: workspaceID}
	for _, tc := range []struct {
		label string
		name  *string
		want  string
	}{
		{label: "omitted", want: "default"},
		{label: "unicode", name: new("  仕事  "), want: "仕事"},
		{label: "empty", name: new("  ")},
	} {
		t.Run(tc.label, func(t *testing.T) {
			id := uuid.NewString()
			if _, err := testLaunchWithIDContext(manager, context.Background(), id, card, nil, nil, nil, tc.name); err != nil {
				t.Fatal(err)
			}
			want := tc.want
			if tc.name != nil && want == "" {
				want = id
			}
			snapshot, ok := manager.GetSession(id)
			if !ok || snapshot.Name != want {
				t.Fatalf("snapshot: %+v, want %q", snapshot, want)
			}
			raw, err := os.ReadFile(filepath.Join(repo.Dir(), "sessions", id+".json"))
			if err != nil {
				t.Fatal(err)
			}
			var record struct {
				Name string `json:"name"`
			}
			if decodeErr := json.Unmarshal(raw, &record); decodeErr != nil {
				t.Fatal(decodeErr)
			}
			if record.Name != want {
				t.Fatalf("saved name = %q, want %q", record.Name, want)
			}
			if killErr := manager.Kill(id); killErr != nil {
				t.Fatal(killErr)
			}
		})
	}
	if card.Name != "default" {
		t.Fatalf("card was modified: %+v", card)
	}
}

internal/session/startup_replacement_tes.source:
//nolint:testpackage // The fixture reads the activation credential and message store under their locks.
package session

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/google/uuid"
)

type replacementFixture struct {
	manager     *Manager
	clock       *controlledStartupClock
	senderToken string
	id          string
	original    config.IDCard
	replacement config.IDCard
}

func newReplacementFixture(t *testing.T) replacementFixture {
	t.Helper()
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v, %v", workspaces, err)
	}
	manager := NewManager(repo.Dir(), repo, WithStartupDelay(0))
	manager.SetMCPEndpoint("http://127.0.0.1:12345/mcp")
	t.Cleanup(func() { manager.Shutdown() })
	sender := config.IDCard{ID: "sender", Name: "sender", Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardControl: true}
	senderID, err := testLaunch(manager, sender, nil, nil, config.BuiltinMCPs())
	if err != nil {
		t.Fatal(err)
	}
	manager.mu.RLock()
	senderToken := manager.sessions[senderID].ActivationToken
	manager.mu.RUnlock()
	clock := newControlledStartupClock()
	manager.mu.Lock()
	manager.startupClock, manager.startupDelay = clock, 10*time.Second
	manager.mu.Unlock()
	return replacementFixture{manager: manager, clock: clock, senderToken: senderToken, id: uuid.NewString(),
		original:    config.IDCard{ID: "original", Name: "original card", Driver: "cat", WorkspaceID: workspaces[0].ID},
		replacement: config.IDCard{ID: "other-card", Name: "other card", Driver: "cat", WorkspaceID: workspaces[0].ID}}
}

func nextReplacementTimer(t *testing.T, clock *controlledStartupClock) *controlledStartupTimer {
	t.Helper()
	select {
	case timer := <-clock.created:
		if delay := <-clock.durations; delay != 10*time.Second {
			t.Fatalf("startup timer delay = %v", delay)
		}
		return timer
	case <-time.After(5 * time.Second):
		t.Fatal("startup timer not created")
		return nil
	}
}

func runReplacement(t *testing.T, operation func() error) {
	t.Helper()
	finished := make(chan error, 1)
	go func() { finished <- operation() }()
	select {
	case err := <-finished:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("lifecycle operation did not return while startup timer was held")
	}
}

func requireStartingAdmissionRejected(t *testing.T, f replacementFixture, activation string) {
	t.Helper()
	f.manager.messages.mu.Lock()
	before := len(f.manager.messages.data.Messages)
	f.manager.messages.mu.Unlock()
	admission, err := f.manager.ReserveMessageAdmission(f.senderToken, f.id, activation)
	if err == nil {
		admission.Release()
		t.Fatal("starting activation admitted a prompt")
	}
	var failure *MessagingError
	if !errors.As(err, &failure) || failure.Code != "starting" {
		t.Fatalf("starting rejection = %v", err)
	}
	f.manager.messages.mu.Lock()
	after := len(f.manager.messages.data.Messages)
	f.manager.messages.mu.Unlock()
	if after != before {
		t.Fatalf("starting rejection changed message history: %d -> %d", before, after)
	}
}

func requireAttachmentOutput(t *testing.T, f replacementFixture, marker string) {
	t.Helper()
	handle, err := testAttach(f.manager, f.id)
	if err != nil {
		t.Fatalf("attach while starting: %v", err)
	}
	defer handle.Close()
	if _, err = handle.Input.Write([]byte(marker + "\n")); err != nil {
		t.Fatalf("write attached input: %v", err)
	}
	var received []byte
	deadline := time.After(5 * time.Second)
	for !bytes.Contains(received, []byte(marker)) {
		select {
		case chunk, ok := <-handle.Output:
			if !ok {
				t.Fatal("attachment closed before startup output")
			}
			received = append(received, chunk...)
		case <-deadline:
			t.Fatalf("attachment never received %q; output %q", marker, received)
		}
	}
	if !bytes.Contains(f.manager.GetScrollback(f.id), []byte(marker)) {
		t.Fatalf("scrollback missing %q", marker)
	}
}

func assertReplacement(
	t *testing.T, f replacementFixture, old Snapshot, oldTimer, currentTimer *controlledStartupTimer,
	cardID, marker string,
) Snapshot {
	t.Helper()
	current, ok := f.manager.GetSession(f.id)
	if !ok || current.ActivationID == "" || current.ActivationID == old.ActivationID || current.CardID != cardID ||
		current.Name != "custom session" || current.Phase != "starting" || !current.ProcessStarted || current.MessageDeliveryAvailable {
		t.Fatalf("replacement snapshot = %+v; previous = %+v", current, old)
	}
	requireStartingAdmissionRejected(t, f, current.ActivationID)
	requireAttachmentOutput(t, f, marker)
	oldTimer.ready <- f.clock.Now()
	current, _ = f.manager.GetSession(f.id)
	if current.Phase != "starting" || current.MessageDeliveryAvailable {
		t.Fatalf("stale timer changed replacement: %+v", current)
	}
	currentTimer.ready <- f.clock.Now().Add(10 * time.Second)
	waitStartupSignal(t, currentTimer.stopped)
	current, _ = f.manager.GetSession(f.id)
	if current.Phase != "active" || !current.ProcessStarted || !current.MessageDeliveryAvailable {
		t.Fatalf("timer did not enable replacement: %+v", current)
	}
	admission, err := f.manager.ReserveMessageAdmission(f.senderToken, f.id, current.ActivationID)
	if err != nil {
		t.Fatalf("active replacement admission: %v", err)
	}
	admission.Release()
	if stale, staleErr := f.manager.ReserveMessageAdmission(f.senderToken, f.id, old.ActivationID); staleErr == nil {
		stale.Release()
		t.Fatal("old activation accepted after replacement")
	}
	return current
}

func TestRelaunchAndDistinctCardSwitchGateMessageDelivery(t *testing.T) {
	f := newReplacementFixture(t)
	name := "custom session"
	runReplacement(t, func() error {
		_, err := testLaunchWithIDContext(f.manager, context.Background(), f.id, f.original, nil, nil, config.BuiltinMCPs(), &name)
		return err
	})
	firstTimer := nextReplacementTimer(t, f.clock)
	first, _ := f.manager.GetSession(f.id)
	requireStartingAdmissionRejected(t, f, first.ActivationID)
	f.clock.advance(9 * time.Second)
	if err := f.manager.Kill(f.id); err != nil {
		t.Fatal(err)
	}
	waitStartupSignal(t, firstTimer.stopped)
	runReplacement(t, func() error { return testRelaunch(f.manager, f.id, f.original) })
	secondTimer := nextReplacementTimer(t, f.clock)
	assertReplacement(t, f, first, firstTimer, secondTimer, f.original.ID, "relaunch output marker")

	if err := f.manager.Kill(f.id); err != nil {
		t.Fatal(err)
	}
	runReplacement(t, func() error { return testRelaunch(f.manager, f.id, f.original) })
	thirdTimer := nextReplacementTimer(t, f.clock)
	third, _ := f.manager.GetSession(f.id)
	requireStartingAdmissionRejected(t, f, third.ActivationID)
	f.clock.advance(9 * time.Second)
	if err := f.manager.Kill(f.id); err != nil {
		t.Fatal(err)
	}
	waitStartupSignal(t, thirdTimer.stopped)
	runReplacement(t, func() error { return testSwitchAgent(f.manager, f.id, f.replacement, nil, nil, config.BuiltinMCPs()) })
	fourthTimer := nextReplacementTimer(t, f.clock)
	fourth := assertReplacement(t, f, third, thirdTimer, fourthTimer, f.replacement.ID, "switch output marker")
	if fourth.ActivationID == first.ActivationID {
		t.Fatal(fmt.Errorf("switch reused original activation %s", first.ActivationID))
	}
}

