	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	if err := testRelaunch(manager, sessionID, card); err != nil {
		t.Fatalf("relaunch after persisted manager reload: %v", err)
	}
	reloadedToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(reloadedToken); err != nil {
		t.Fatalf("persisted deployed grant was not preserved across reload: %v", err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if manager.Shutdown() != 0 {
		t.Fatal("manager shutdown reported running sessions")
	}
	// A pre-grant-era record has no dashboard_control field; its zero value must
	// remain registration-only even when the Kankuro server was deployed.
	recordPath := filepath.Join(repo.Dir(), "sessions", sessionID+".json")
	recordData, err := os.ReadFile(recordPath)
	if err != nil {
		t.Fatal(err)
	}
	var legacyRecord map[string]json.RawMessage
	if err := json.Unmarshal(recordData, &legacyRecord); err != nil {
		t.Fatal(err)
	}
	delete(legacyRecord, "dashboard_control")
	recordData, err = json.Marshal(legacyRecord)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(recordPath, recordData, 0o600); err != nil {
		t.Fatal(err)
	}
	manager = newTestManager(t, repo.Dir(), repo)
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	if err := testRelaunch(manager, sessionID, card); err != nil {
		t.Fatalf("legacy relaunch: %v", err)
	}
	legacyToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(legacyToken); err == nil {
		t.Fatal("legacy record without dashboard_control gained dashboard authority")
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if err := testSwitchAgent(manager, sessionID, card, nil, nil, config.BuiltinMCPs()); err != nil {
		t.Fatalf("switch to same card with current opt-out: %v", err)
	}
	sameCardToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(sameCardToken); err == nil {
		t.Fatal("same-card explicit switch did not apply the current opt-out")
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if err := testSwitchAgent(manager, sessionID, secondCard, nil, nil, config.BuiltinMCPs()); err != nil {
		t.Fatalf("switch to opted-in card: %v", err)
	}
	secondToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(secondToken); err != nil {
		t.Fatalf("explicit switch did not apply destination grant: %v", err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
}

func writeTestFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
}

func assertFileContent(t *testing.T, path, want string) {
	t.Helper()
	got, err := os.ReadFile(path)
	if err != nil || string(got) != want {
		t.Fatalf("%s: content=%q err=%v, want %q", path, got, err, want)
	}
}

func assertAbsent(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		t.Fatalf("expected %s to remain absent, err=%v", path, err)
	}
}

func workspaceIDForPath(t *testing.T, workspaces []config.Workspace, path string) string {
	t.Helper()
	for _, workspace := range workspaces {
		if workspace.Path == path {
			return workspace.ID
		}
	}
	t.Fatalf("workspace not found for %s", path)
	return ""
}

internal/session/workspace_validation_te.source:
package session_test

import (
	"os"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
)

type workspaceValidationDriver struct {
	*driver.GenericCLIDriver

	spawns *atomic.Int32
}

func (d *workspaceValidationDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	d.spawns.Add(1)
	return d.GenericCLIDriver.Spawn(cfg)
}

//nolint:gocognit,govet // Each case verifies rejection, no mutation or spawn, and successful retry through the real lifecycle.
func TestActivationRejectsUnavailableSavedWorkspace(t *testing.T) {
	for _, test := range []struct {
		name        string
		useTmp      bool
		operation   string
		replacement string
	}{
		{"relaunch/missing/source", false, "relaunch", "missing"},
		{"relaunch/file/source", false, "relaunch", "file"},
		{"switch/missing/source", false, "switch", "missing"},
		{"switch/file/source", false, "switch", "file"},
		{"relaunch/missing/temporary", true, "relaunch", "missing"},
		{"relaunch/file/temporary", true, "relaunch", "file"},
		{"switch/missing/temporary", true, "switch", "missing"},
		{"switch/file/temporary", true, "switch", "file"},
	} {
		t.Run(test.name, func(t *testing.T) {
			repo, workspaceID := workspaceValidationRepository(t)
			var spawns atomic.Int32
			registry := driver.NewRegistry()
			registry.Register("cat", func() driver.AgentDriver {
				return &workspaceValidationDriver{GenericCLIDriver: driver.NewGenericCLIDriver(), spawns: &spawns}
			})
			manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
			card := config.IDCard{ID: "a", Name: "A", Driver: "cat", WorkspaceID: workspaceID, UseTmpWorkspace: test.useTmp}
			id, err := testLaunch(manager, card, nil, nil, nil)
			if err != nil {
				t.Fatal(err)
			}
			if err := manager.Kill(id); err != nil {
				t.Fatal(err)
			}
			before, found := manager.GetSession(id)
			if !found {
				t.Fatal("session missing")
			}
			backup := filepath.Join(t.TempDir(), "saved-workspace")
			if err := os.Rename(before.WorkingDir, backup); err != nil {
				t.Fatal(err)
			}
			if test.replacement == "file" {
				if err := os.WriteFile(before.WorkingDir, []byte("keep this file"), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			activate := func() error { return testRelaunch(manager, id, card) }
			if test.operation == "switch" {
				card.ID = "b"
				activate = func() error { return testSwitchAgent(manager, id, card, nil, nil, nil) }
			}
			if err := activate(); err == nil || !strings.Contains(err.Error(), before.WorkingDir) {
				t.Fatalf("expected workspace error with saved path, got %v", err)
			}
			if spawns.Load() != 1 {
				t.Fatal("invalid workspace activation reached Spawn")
			}
			after, found := manager.GetSession(id)
			if !found || after.Status != session.StatusTerminated ||
				after.PID != before.PID || after.WorkingDir != before.WorkingDir {
				t.Fatalf("failed activation changed session identity or process: %#v", after)
			}
			if test.replacement == "missing" {
				if _, err := os.Lstat(before.WorkingDir); !os.IsNotExist(err) {
					t.Fatalf("missing workspace was recreated: %v", err)
				}
			} else {
				content, err := os.ReadFile(before.WorkingDir)
				if err != nil || string(content) != "keep this file" {
					t.Fatalf("replacement file changed: %q, %v", content, err)
				}
				if err := os.Remove(before.WorkingDir); err != nil {
					t.Fatal(err)
				}
			}
			if err := os.Rename(backup, before.WorkingDir); err != nil {
				t.Fatal(err)
			}
			if err := activate(); err != nil {
				t.Fatalf("retry after restoring workspace: %v", err)
			}
			if spawns.Load() != 2 {
				t.Fatal("retry did not spawn exactly one agent")
			}
			content, err := os.ReadFile(filepath.Join(before.WorkingDir, "work.txt"))
			if err != nil || string(content) != "saved work" {
				t.Fatalf("saved work lost after retry: %q, %v", content, err)
			}
		})
	}
}

func workspaceValidationRepository(t *testing.T) (*config.FileRepository, string) {
	t.Helper()
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if writeErr := os.WriteFile(filepath.Join(workspace, "work.txt"), []byte("saved work"), 0o600); writeErr != nil {
		t.Fatal(writeErr)
	}
	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); saveErr != nil {
		t.Fatal(saveErr)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", err)
	}
	return repo, workspaces[0].ID
}

internal/ui/attachment_missing_internal_.source:
package ui

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

type controlledAttachmentPort struct {
	resource contracts.Attachment
	entered  chan context.Context
	release  chan struct{}
}

func (p *controlledAttachmentPort) AttachInDashboard(ctx context.Context, _, _ string) (contracts.Attachment, error) {
	if p.entered != nil {
		p.entered <- ctx
		<-p.release
	}
	return p.resource, nil
}
func (p *controlledAttachmentPort) AttachExpectedProcessInDashboard(ctx context.Context, d, s, _ string) (contracts.Attachment, error) {
	return p.AttachInDashboard(ctx, d, s)
}

func attachmentInventory(c *Coordinator, request, epoch uint64, ids ...string) messages.SessionsRefreshedMsg {
	sessions := make([]contracts.SessionSummary, 0, len(ids))
	for _, id := range ids {
		sessions = append(sessions, contracts.SessionSummary{ID: id, DashboardID: c.activeDashboard})
	}
	return messages.SessionsRefreshedMsg{
		DashboardID:        c.activeDashboard,
		Generation:         c.viewGeneration,
		SessionEpoch:       epoch,
		InventoryRequestID: request,
		Inventory: contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true,
			Value:     contracts.DashboardInventory{Sessions: sessions},
		},
	}
}

func TestMissingSessionClosesQueuedAttachment(t *testing.T) {
	for _, full := range []bool{false, true} {
		t.Run(map[bool]string{false: "sessions", true: "full"}[full], func(t *testing.T) {
			c, _ := newLaunchFocusCoordinator(t)
			closed := false
			c.attachment = &controlledAttachmentPort{resource: &fakeAttachment{closed: &closed}}
			ready := c.requestAttach("gone")().(messages.ScopedAttachReadyMsg)
			request := c.lastAppliedInventoryRequest + 1
			if full {
				c.Update(
					messages.DataLoadedMsg{
						DashboardID:        c.activeDashboard,
						Generation:         c.viewGeneration,
						SessionEpoch:       c.sessionEpoch,
						InventoryRequestID: request,
						Inventory:          contracts.ReadResult[contracts.DashboardInventory]{Attempted: true},
					},
				)
			} else {
				c.Update(attachmentInventory(c, request, c.sessionEpoch))
			}
			if !closed {
				t.Fatal("queued attachment was not closed on confirmed absence")
			}
			_, cmd := c.Update(ready)
			if cmd != nil {
				t.Fatal("removed session started terminal")
			}
		})
	}
}

func TestMissingSessionCancelsAcquisitionAndClosesLateResult(t *testing.T) {
	for _, trigger := range []string{"inventory", "removal"} {
		t.Run(trigger, func(t *testing.T) {
			c, _ := newLaunchFocusCoordinator(t)
			closed := false
			port := &controlledAttachmentPort{
				resource: &fakeAttachment{closed: &closed},
				entered:  make(chan context.Context, 1),
				release:  make(chan struct{}),
			}
			c.attachment = port
			cmd := c.requestAttach("gone")
			done := make(chan messages.ScopedAttachReadyMsg, 1)
			go func() { done <- cmd().(messages.ScopedAttachReadyMsg) }()
			ctx := <-port.entered
			if trigger == "inventory" {
				c.Update(attachmentInventory(c, c.lastAppliedInventoryRequest+1, c.sessionEpoch))
			} else {
				c.Update(messages.SessionRemovedMsg{DashboardID: c.activeDashboard, Generation: c.viewGeneration,
					SessionID: "gone", Result: contracts.RemoveSessionResult{InMemoryRemoved: true}})
			}
			select {
			case <-ctx.Done():
			case <-time.After(time.Second):
				t.Fatal("acquisition not cancelled")
			}
			close(port.release)
			ready := <-done
			if !closed || ready.Handle != nil {
				t.Fatalf("late resource: closed=%t handle=%v", closed, ready.Handle)
			}
			if _, next := c.Update(ready); next != nil {
				t.Fatal("late result started terminal")
			}
		})
	}
}

func TestAttachmentSurvivesNonAuthoritativeInventory(t *testing.T) {
	for _, kind := range []string{"failed", "unattempted", "stale_epoch", "stale_request", "other_dashboard", "old_generation", "present"} {
		t.Run(kind, func(t *testing.T) {
			c, _ := newLaunchFocusCoordinator(t)
			c.sessionEpoch = 3
			c.lastAppliedInventoryRequest = 10
			closed := false
			c.attachment = &controlledAttachmentPort{resource: &fakeAttachment{closed: &closed}}
			ready := c.requestAttachExpected("new", "process", messages.AttachRequestLaunch)().(messages.ScopedAttachReadyMsg)
			snapshot := attachmentInventory(c, 11, 3)
			switch kind {
			case "failed":
				snapshot.Inventory.Err = errors.New("read failed")
				snapshot.Err = snapshot.Inventory.Err
			case "unattempted":
				snapshot.Inventory.Attempted = false
			case "stale_epoch":
				snapshot.SessionEpoch = 2
			case "stale_request":
				snapshot.InventoryRequestID = 10
			case "other_dashboard":
				snapshot.DashboardID = "other"
			case "old_generation":
				snapshot.Generation--
			case "present":
				snapshot = attachmentInventory(c, 11, 3, "new")
			}
			c.Update(snapshot)
			if closed || !c.attachmentOwner.current(ready.Sequence, c.activeDashboard, "new") {
				t.Fatal("non-authoritative absence invalidated attachment")
			}
			c.attachmentOwner.close()
		})
	}
}

func TestRemovalResultCancelsMatchingAttachment(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	closed := false
	c.attachment = &controlledAttachmentPort{resource: &fakeAttachment{closed: &closed}}
	ready := c.requestAttach("gone")().(messages.ScopedAttachReadyMsg)
	c.Update(
		messages.SessionRemovedMsg{
			DashboardID: c.activeDashboard,
			Generation:  c.viewGeneration,
			SessionID:   "other",
			Result:      contracts.RemoveSessionResult{InMemoryRemoved: true},
		},
	)
	if closed {
		t.Fatal("unrelated removal closed attachment")
	}
	c.Update(
		messages.SessionRemovedMsg{
			DashboardID: c.activeDashboard,
			Generation:  c.viewGeneration,
			SessionID:   "gone",
			Result:      contracts.RemoveSessionResult{InMemoryRemoved: true},
		},
	)
	if !closed {
		t.Fatal("removed target attachment remained open")
	}
	if _, cmd := c.Update(ready); cmd != nil {
		t.Fatal("removed target started terminal")
	}
}

func TestNewLaunchAttachmentIgnoresPrePublicationInventory(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	oldEpoch := c.sessionEpoch
	oldSnapshot := attachmentInventory(c, c.lastAppliedInventoryRequest+1, oldEpoch)
	c.Update(launchCompleted(c, "new", nil))
	if c.sessionEpoch <= oldEpoch {
		t.Fatal("launch did not advance session epoch")
	}
	closed := false
	c.attachment = &controlledAttachmentPort{resource: &fakeAttachment{closed: &closed}}
	ready := c.requestAttachExpected("new", "process", messages.AttachRequestLaunch)().(messages.ScopedAttachReadyMsg)
	c.Update(oldSnapshot)
	if closed {
		t.Fatal("pre-publication inventory closed new launch")
	}
	if _, cmd := c.Update(ready); cmd == nil {
		t.Fatal("new launch attachment was rejected")
	}
	c.attachmentOwner.close()
}

func TestSuccessfulInventoryWithOtherReadErrorStillClosesMissingAttachment(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	closed := false
	c.attachment = &controlledAttachmentPort{resource: &fakeAttachment{closed: &closed}}
	ready := c.requestAttach("gone")().(messages.ScopedAttachReadyMsg)
	failure := errors.New("registry read failed")
	c.Update(messages.DataLoadedMsg{DashboardID: c.activeDashboard, Generation: c.viewGeneration, SessionEpoch: c.sessionEpoch,
		InventoryRequestID: c.lastAppliedInventoryRequest + 1, Err: failure, RegistryErr: failure,
		Inventory: contracts.ReadResult[contracts.DashboardInventory]{Attempted: true}})
	if !closed {
		t.Fatal("successful empty inventory was ignored because another read failed")
	}
	if _, cmd := c.Update(ready); cmd != nil {
		t.Fatal("removed session started terminal")
	}
}

internal/ui/attachment_owner_test.go.source:
//nolint:testpackage // Exercises package-private resource ownership.
package ui

import (
	"errors"
	"testing"

	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

func TestAttachmentOwnerDisposesLateAndSupersededResults(t *testing.T) {
	o := &attachmentOwner{}
	ctx, old := o.begin(attachmentTarget{})
	_, current := o.begin(attachmentTarget{})
	select {
	case <-ctx.Done():
	default:
		t.Fatal("superseded request was not canceled")
	}
	closed := false
	if o.publish(old, &fakeAttachment{closed: &closed}) || !closed {
		t.Fatal("late resource was not closed")
	}
	closed = false
	if !o.publish(current, &fakeAttachment{closed: &closed}) {
		t.Fatal("current resource rejected")
	}
	o.close()
	if !closed {
		t.Fatal("shutdown did not close queued resource")
	}
}

func TestAttachmentResultIsDiscardedAfterLeavingAndReturning(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	_, request := c.attachmentOwner.begin(attachmentTarget{})
	c.navigateTo(ViewSettings)
	c.navigateTo(ViewDashboard)
	closed := false
	if c.attachmentOwner.publish(request, &fakeAttachment{closed: &closed}) || !closed {
		t.Fatal("attachment from previous visit was retained")
	}
}

func TestAttachmentResultWithErrorClosesResource(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	closed := false
	_, cmd := c.Update(
		messages.ScopedAttachReadyMsg{
			DashboardID: c.activeDashboard,
			Generation:  c.viewGeneration,
			SessionID:   "s",
			Handle:      &fakeAttachment{closed: &closed},
			Err:         errors.New("failed"),
		},
	)
	if !closed || cmd != nil {
		t.Fatalf("closed=%t command=%v", closed, cmd != nil)
	}
}

