package ui

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/component"
	"github.com/BlackGiack/kankuro/internal/ui/models"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type centerTestPort struct{}

func (centerTestPort) ReadSessionReports(context.Context, contracts.SessionReportsRequest) (contracts.SessionReportsResult, error) {
	return contracts.SessionReportsResult{}, nil
}
func (centerTestPort) SubscribeSessionReports(context.Context, contracts.ScopedSessionRequest) (contracts.ReportSubscription, error) {
	return nil, errors.New("test")
}
func (centerTestPort) ReadSessionWorkspace(context.Context, contracts.ScopedSessionRequest) (contracts.SessionWorkspaceResult, error) {
	return contracts.SessionWorkspaceResult{}, nil
}

type centerTestSubscription struct {
	ch       chan struct{}
	released bool
}

func (s *centerTestSubscription) Changes() <-chan struct{} { return s.ch }
func (s *centerTestSubscription) Err() error               { return nil }
func (s *centerTestSubscription) Release()                 { s.released = true }
func centerTestCoordinator(t *testing.T) *Coordinator {
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	d := views.NewDashboard(views.DashboardCallbacks{})
	d.SetSize(120, 35)
	viewMap := make(map[ViewType]component.Model)
	viewMap[ViewDashboard] = d
	c := &Coordinator{currentView: ViewDashboard, activeDashboard: "d", views: viewMap}
	c.center = centerState{
		port:        centerTestPort{},
		sessionID:   "s",
		dashboardID: "d",
		generation:  1,
		ctx:         ctx,
		cancel:      cancel,
		limit:       8,
		data:        models.SessionCenterData{SessionID: "s"},
	}
	return c
}
func TestCenterReportTakesOverAndRejectsLateWorkspace(t *testing.T) {
	c := centerTestCoordinator(t)
	s := &c.center
	if c.centerRead() == nil {
		t.Fatal("no report read")
	}
	_, workspace := c.handleCenter(centerReportsMsg{generation: 1, request: s.request, result: contracts.SessionReportsResult{}})
	if workspace == nil || !s.working {
		t.Fatal("empty reports did not begin workspace read")
	}
	old := s.workspaceRequest
	sub := &centerTestSubscription{ch: make(chan struct{})}
	s.subscription = sub
	_, next := c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	if next == nil || !s.working || !s.reading {
		t.Fatal("report event should read while retaining workspace work")
	}
	c.handleCenter(
		centerReportsMsg{
			generation: 1,
			request:    s.request,
			result:     contracts.SessionReportsResult{Reports: []contracts.SessionReport{{Text: "new"}}},
		},
	)
	if s.working {
		t.Fatal("first report did not cancel obsolete workspace work")
	}
	c.handleCenter(centerWorkspaceMsg{generation: 1, request: old, result: contracts.SessionWorkspaceResult{WorkingDir: "obsolete"}})
	if len(s.data.Reports) != 1 || s.data.Workspace != nil {
		t.Fatalf("late workspace overwrote reports: %+v", s.data)
	}
}
func TestCenterCoalescesAndReleasesStaleSetup(t *testing.T) {
	c := centerTestCoordinator(t)
	s := &c.center
	sub := &centerTestSubscription{ch: make(chan struct{})}
	s.subscription = sub
	c.centerRead()
	c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	if !s.pending {
		t.Fatal("missing pending refresh")
	}
	before := s.request
	_, cmd := c.handleCenter(centerReportsMsg{generation: 1, request: before})
	if cmd == nil || s.request != before+1 || s.pending {
		t.Fatal("events did not coalesce into a follow-up read")
	}
	stale := &centerTestSubscription{ch: make(chan struct{})}
	c.clearCenter()
	c.handleCenter(centerSetupMsg{generation: 1, subscription: stale})
	if !stale.released || !sub.released {
		t.Fatal("selection change leaked subscription")
	}
}
func TestCenterScopeFailureClearsCachedReports(t *testing.T) {
	c := centerTestCoordinator(t)
	s := &c.center
	s.data.Reports = []contracts.SessionReport{{Text: "secret"}}
	s.reading = true
	s.request = 2
	c.handleCenter(centerReportsMsg{generation: 1, request: 2, err: contracts.ErrSessionScope})
	if c.center.sessionID != "" || len(c.center.data.Reports) != 0 {
		t.Fatal("scope rejection retained selection data")
	}
	dashboard := c.views[ViewDashboard].(*views.Dashboard)
	dashboard.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true,
			Value:     contracts.DashboardInventory{Sessions: []contracts.SessionSummary{{ID: "s"}}},
		},
		contracts.DisplayChoicesResult{},
	)
	if cmd := c.reconcileCenter(); cmd != nil || c.center.sessionID != "" {
		t.Fatal("scope rejection caused immediate retry")
	}
}

type fakeCenterClock struct {
	delays chan time.Duration
	ticks  chan struct{}
}

func (f *fakeCenterClock) Wait(ctx context.Context, delay time.Duration) bool {
	f.delays <- delay
	select {
	case <-f.ticks:
		return true
	case <-ctx.Done():
		return false
	}
}
func TestCenterRetryClockIsNonOverlappingAndCanceled(t *testing.T) {
	c := centerTestCoordinator(t)
	clock := &fakeCenterClock{delays: make(chan time.Duration, 1), ticks: make(chan struct{})}
	c.center.clock = clock
	cmd := c.centerSchedule()
	if cmd == nil || c.centerSchedule() != nil {
		t.Fatal("expected exactly one timer")
	}
	done := make(chan tea.Msg, 1)
	go func() { done <- cmd() }()
	if delay := <-clock.delays; delay != 30*time.Second {
		t.Fatalf("delay %s", delay)
	}
	clock.ticks <- struct{}{}
	msg := <-done
	_, next := c.handleCenter(msg)
	if next == nil || !c.center.setup || c.centerSchedule() != nil {
		t.Fatal("retry must resubscribe before reading and cannot overlap")
	}
	c.clearCenter()
}

func TestCenterFailurePolicyRetainsOnlySameSessionData(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	st.data.Reports = []contracts.SessionReport{{Text: "saved"}}
	st.reading = true
	st.request = 1
	_, cmd := c.handleCenter(centerReportsMsg{generation: 1, request: 1, err: errors.New("history error")})
	if len(st.data.Reports) != 1 || !st.data.Stale || st.reportWarning == "" || cmd == nil {
		t.Fatalf("failed history did not retain stale reports: %+v", st.data)
	}
	st.reading = true
	st.request++
	_, cmd = c.handleCenter(centerReportsMsg{generation: 1, request: st.request, result: contracts.SessionReportsResult{}})
	if len(st.data.Reports) != 0 || st.data.Stale || cmd == nil || !st.working {
		t.Fatalf("confirmed empty did not clear reports: %+v", st.data)
	}
	st.data.Workspace = &contracts.SessionWorkspaceResult{WorkingDir: "saved"}
	c.handleCenter(
		centerWorkspaceMsg{
			generation: 1,
			request:    st.workspaceRequest,
			err:        errors.New("missing"),
			result:     contracts.SessionWorkspaceResult{Warnings: []string{"Git failed"}},
		},
	)
	if !st.timer || !st.data.Stale || st.data.Workspace == nil || st.workspaceWarning == "" {
		t.Fatalf("failed workspace did not retain stale data and warnings: %+v", st.data)
	}
	c.clearCenter()
	if len(c.center.data.Reports) != 0 || c.center.data.Workspace != nil {
		t.Fatal("selection clear retained old content")
	}
}

func TestCenterClosedSubscriptionUsesRetry(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	sub := &centerTestSubscription{ch: make(chan struct{})}
	st.subscription = sub
	st.data.Reports = []contracts.SessionReport{{Text: "saved"}}
	_, cmd := c.handleCenter(centerChangeMsg{generation: 1, subscription: sub, closed: true, err: errors.New("closed")})
	if cmd == nil || !st.timer || st.subscription != nil || st.subscriptionWarning == "" || len(st.data.Reports) != 1 {
		t.Fatal("closed stream did not preserve content and schedule recovery")
	}
}

func fireCenterClock(t *testing.T, clock *fakeCenterClock, cmd tea.Cmd) tea.Msg {
	t.Helper()
	if cmd == nil {
		t.Fatal("missing timer command")
	}
	done := make(chan tea.Msg, 1)
	go func() { done <- cmd() }()
	if delay := <-clock.delays; delay != centerRetryInterval {
		t.Fatalf("unexpected retry interval %v", delay)
	}
	clock.ticks <- struct{}{}
	return <-done
}

func TestCenterFailedReadCoalescesChangesUntilRetry(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	clock := &fakeCenterClock{delays: make(chan time.Duration, 1), ticks: make(chan struct{})}
	st.clock = clock
	sub := &centerTestSubscription{ch: make(chan struct{})}
	st.subscription = sub
	st.data.Reports = []contracts.SessionReport{{Text: "retained"}}
	c.centerRead()
	_, timer := c.handleCenter(centerReportsMsg{generation: 1, request: st.request, err: errors.New("history failed")})
	request := st.request
	for range 4 {
		c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	}
	if st.reading || st.request != request || !st.pending || !st.timer {
		t.Fatalf("change bypassed recovery interval: %+v", st)
	}
	_, read := c.handleCenter(fireCenterClock(t, clock, timer))
	if read == nil || !st.reading || st.request != request+1 || st.pending {
		t.Fatal("timer did not start one coalesced retry")
	}
	for range 3 {
		c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	}
	_, timer = c.handleCenter(centerReportsMsg{generation: 1, request: st.request, err: errors.New("history still failed")})
	if st.reading || !st.pending || !st.timer || timer == nil {
		t.Fatal("failed retry started another read instead of scheduling recovery")
	}
}

func TestCenterChangesDoNotRestartWorkspace(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	clock := &fakeCenterClock{delays: make(chan time.Duration, 1), ticks: make(chan struct{})}
	st.clock = clock
	sub := &centerTestSubscription{ch: make(chan struct{})}
	st.subscription = sub
	st.data.Workspace = &contracts.SessionWorkspaceResult{WorkingDir: "existing"}
	timer := c.centerSchedule()
	if timer == nil {
		t.Fatal("missing workspace timer")
	}
	for range 3 {
		c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
		if !st.reading {
			t.Fatal("healthy change did not read reports")
		}
		c.handleCenter(centerReportsMsg{generation: 1, request: st.request, result: contracts.SessionReportsResult{}})
		if st.working || !st.timer {
			t.Fatal("empty event read restarted workspace before timer")
		}
	}
	_, read := c.handleCenter(fireCenterClock(t, clock, timer))
	if read == nil {
		t.Fatal("timer did not start refresh")
	}
	_, workspace := c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
	if workspace == nil || !st.working {
		t.Fatal("scheduled refresh did not start workspace inspection")
	}
	workspaceRequest := st.workspaceRequest
	for range 3 {
		c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
		if !st.working || st.workspaceRequest != workspaceRequest {
			t.Fatal("change canceled slow workspace inspection")
		}
		c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
		if !st.working || st.workspaceRequest != workspaceRequest {
			t.Fatal("empty report read restarted slow workspace inspection")
		}
	}
}

func TestCenterFailedWorkspaceWithoutCacheWaitsForTimer(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	clock := &fakeCenterClock{delays: make(chan time.Duration, 1), ticks: make(chan struct{})}
	st.clock = clock
	sub := &centerTestSubscription{ch: make(chan struct{})}
	st.subscription = sub
	c.centerRead()
	_, workspace := c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
	if workspace == nil || !st.working {
		t.Fatal("initial workspace load did not start")
	}
	_, timer := c.handleCenter(centerWorkspaceMsg{generation: 1, request: st.workspaceRequest, err: errors.New("inaccessible")})
	if timer == nil || !st.timer || st.data.Workspace != nil {
		t.Fatal("failure did not start recovery timer")
	}
	previous := st.workspaceRequest
	for range 4 {
		c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
		if !st.reading {
			t.Fatal("healthy report discovery stopped")
		}
		c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
		if st.working || st.workspaceRequest != previous || !st.timer {
			t.Fatal("workspace was retried before timer")
		}
	}
	_, read := c.handleCenter(fireCenterClock(t, clock, timer))
	if read == nil || !st.reading {
		t.Fatal("timer did not retry reports")
	}
	_, workspace = c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
	if workspace == nil || !st.working || st.workspaceRequest != previous+1 {
		t.Fatal("timer did not permit workspace retry")
	}
}

func TestCenterWorkspaceStaleUntilSuccessfulWorkspaceOrReport(t *testing.T) {
	c := centerTestCoordinator(t)
	st := &c.center
	clock := &fakeCenterClock{delays: make(chan time.Duration, 1), ticks: make(chan struct{})}
	st.clock = clock
	sub := &centerTestSubscription{ch: make(chan struct{})}
	st.subscription = sub
	st.data.Workspace = &contracts.SessionWorkspaceResult{WorkingDir: "cached"}
	c.centerWorkspace()
	_, timer := c.handleCenter(centerWorkspaceMsg{generation: 1, request: st.workspaceRequest, err: errors.New("unavailable")})
	if !st.data.Stale || timer == nil {
		t.Fatal("failed refresh did not mark cached workspace stale")
	}
	c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
	if !st.data.Stale || st.working {
		t.Fatal("empty report read changed stale workspace")
	}
	c.handleCenter(centerChangeMsg{generation: 1, subscription: sub})
	c.handleCenter(centerReportsMsg{generation: 1, request: st.request, err: errors.New("report failure")})
	if !st.data.Stale || st.data.Workspace == nil {
		t.Fatal("failed report read changed stale workspace")
	}
	_, read := c.handleCenter(fireCenterClock(t, clock, timer))
	if read == nil {
		t.Fatal("missing recovery read")
	}
	_, workspace := c.handleCenter(centerReportsMsg{generation: 1, request: st.request})
	if workspace == nil || !st.working || !st.data.Stale {
		t.Fatal("expected stale workspace during retry")
	}
	c.handleCenter(
		centerWorkspaceMsg{generation: 1, request: st.workspaceRequest, result: contracts.SessionWorkspaceResult{WorkingDir: "fresh"}},
	)
	if st.data.Stale || st.workspaceStale || st.data.Workspace.WorkingDir != "fresh" {
		t.Fatal("successful workspace did not clear stale status")
	}
	// A new successful authored report also replaces stale workspace content.
	c.centerWorkspace()
	c.handleCenter(centerWorkspaceMsg{generation: 1, request: st.workspaceRequest, err: errors.New("again")})
	c.centerRead()
	c.handleCenter(
		centerReportsMsg{
			generation: 1,
			request:    st.request,
			result:     contracts.SessionReportsResult{Reports: []contracts.SessionReport{{Text: "report"}}},
		},
	)
	if st.data.Stale || st.data.Workspace != nil || len(st.data.Reports) != 1 {
		t.Fatal("report takeover retained workspace stale state")
	}
}

func TestCenterNavigationRestoresSameSessionAndClearsOnEmpty(t *testing.T) {
	c := centerTestCoordinator(t)
	d := c.views[ViewDashboard].(*views.Dashboard)
	d.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true,
			Value:     contracts.DashboardInventory{Sessions: []contracts.SessionSummary{{ID: "s"}, {ID: "other"}}},
		},
		contracts.DisplayChoicesResult{},
	)
	d.SessionList().SetSelectedByID("s")
	d.SyncCenterSelection()
	st := &c.center
	st.data.Reports = []contracts.SessionReport{{Text: "saved report", Kind: "completed"}}
	st.subscription = &centerTestSubscription{ch: make(chan struct{})}
	c.publishCenter()
	c.navigateTo(ViewSettings)
	if st.saved == nil || len(st.saved.data.Reports) != 1 || st.ctx != nil {
		t.Fatal("navigation did not detach cached content and cancel resources")
	}
	c.navigateTo(ViewDashboard)
	if len(st.data.Reports) != 1 || st.data.Reports[0].Text != "saved report" {
		t.Fatal("same session cache was not restored")
	}
	sub := &centerTestSubscription{ch: make(chan struct{})}
	c.handleCenter(centerSetupMsg{generation: st.generation, subscription: sub})
	c.handleCenter(centerReportsMsg{generation: st.generation, request: st.request, err: errors.New("history unavailable")})
	if !st.data.Stale || len(st.data.Reports) != 1 {
		t.Fatal("failed reread did not retain stale reports")
	}
	if rendered := d.Center().View(); !strings.Contains(rendered, "saved report") || !strings.Contains(rendered, "[stale]") {
		t.Fatalf("panel did not show stale cached report: %q", rendered)
	}
	// A confirmed empty result clears old reports before another navigation.
	c.centerRead()
	c.handleCenter(centerReportsMsg{generation: st.generation, request: st.request})
	if len(st.data.Reports) != 0 {
		t.Fatal("successful empty read did not clear reports")
	}
	c.navigateTo(ViewSettings)
	c.navigateTo(ViewDashboard)
	if len(st.data.Reports) != 0 {
		t.Fatal("cleared reports returned after navigation")
	}
}

func TestCenterNavigationCacheNeverMovesToAnotherSelection(t *testing.T) {
	c := centerTestCoordinator(t)
	d := c.views[ViewDashboard].(*views.Dashboard)
	d.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true,
			Value:     contracts.DashboardInventory{Sessions: []contracts.SessionSummary{{ID: "s"}, {ID: "other"}}},
		},
		contracts.DisplayChoicesResult{},
	)
	d.SessionList().SetSelectedByID("s")
	d.SyncCenterSelection()
	c.center.data.Workspace = &contracts.SessionWorkspaceResult{WorkingDir: "only-s"}
	c.publishCenter()
	c.navigateTo(ViewSettings)
	d.TogglePane()
	d.SessionList().SetSelectedByID("other")
	d.SyncCenterSelection()
	c.navigateTo(ViewDashboard)
	if c.center.sessionID != "other" || c.center.data.Workspace != nil || len(c.center.data.Reports) != 0 {
		t.Fatalf("other selection inherited cached content: %+v", c.center.data)
	}
}

func TestCenterNavigationRestoresWorkspaceAndClearsOnScopeLoss(t *testing.T) {
	c := centerTestCoordinator(t)
	d := c.views[ViewDashboard].(*views.Dashboard)
	d.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true,
			Value:     contracts.DashboardInventory{Sessions: []contracts.SessionSummary{{ID: "s"}}},
		},
		contracts.DisplayChoicesResult{},
	)
	st := &c.center
	st.data.Workspace = &contracts.SessionWorkspaceResult{WorkingDir: "saved workspace"}
	st.workspaceAttempted = true
	c.publishCenter()
	c.navigateTo(ViewSettings)
	c.navigateTo(ViewDashboard)
	if st.data.Workspace == nil || st.data.Workspace.WorkingDir != "saved workspace" {
		t.Fatal("workspace cache was lost on navigation")
	}
	sub := &centerTestSubscription{ch: make(chan struct{})}
	c.handleCenter(centerSetupMsg{generation: st.generation, subscription: sub})
	c.handleCenter(centerReportsMsg{generation: st.generation, request: st.request, err: errors.New("history unavailable")})
	if st.data.Workspace == nil || st.reportWarning == "" {
		t.Fatal("report failure lost the cached workspace fallback")
	}
	c.centerRead()
	c.handleCenter(centerReportsMsg{generation: st.generation, request: st.request, err: contracts.ErrSessionScope})
	if st.data.Workspace != nil || st.saved != nil || st.sessionID != "" {
		t.Fatal("scope rejection retained cached content")
	}
}

type delayedCenterPort struct {
	centerTestPort

	entered chan struct{}
	release chan struct{}
}

func (p delayedCenterPort) ReadSessionReports(
	_ context.Context, _ contracts.SessionReportsRequest,
) (contracts.SessionReportsResult, error) {
	close(p.entered)
	<-p.release
	return contracts.SessionReportsResult{Reports: []contracts.SessionReport{{Text: "old session report"}}}, nil
}

func TestCenterSwitchWhileReadInFlight(t *testing.T) {
	c := centerTestCoordinator(t)
	port := delayedCenterPort{entered: make(chan struct{}), release: make(chan struct{})}
	c.center.port = port
	cmd := c.centerRead()
	result := make(chan tea.Msg, 1)
	go func() { result <- cmd() }()
	<-port.entered
	c.clearCenter()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	//nolint:fatcontext // New selection intentionally owns a fresh context.
	c.center.ctx = ctx
	c.center.cancel = cancel
	c.center.dashboardID = "new-dashboard"
	c.center.sessionID = "new-session"
	close(port.release)
	c.handleCenter(<-result)
	if c.center.dashboardID != "new-dashboard" || c.center.sessionID != "new-session" || len(c.center.data.Reports) != 0 {
		t.Fatalf("stale read crossed selection: %+v", c.center.data)
	}
}

internal/ui/command_race_internal_test.g.source:
package ui

// TestCommandClosuresDoNotRaceCoordinator is a runtime backstop for invariant
// 1 (no tea.Cmd closure touches coordinator-goroutine state: c.views,
// c.center, c.currentView, c.err, c.settings), in addition to the structural
// rule (refresher and sessionActions hold no *Coordinator) and the greps in
// project.md §6. It only means something under `go test -race`; without the
// race detector it merely checks that the flows still complete.
//
// How it works: for each message that returns commands, Update runs on the
// test goroutine (as it does in Bubble Tea), every returned command is then
// executed on its own goroutine (as Bubble Tea does), and meanwhile the test
// goroutine keeps *writing* the state those closures must not touch - through
// Update, which assigns into c.views, c.err, c.currentView and c.settings,
// not just reads. A closure that reads any of them is then an unsynchronised
// access the detector reports. The hammering has to write: two concurrent
// reads of a map are not a race.
//
// Limit: receiving a closure's result from the channel orders everything
// after it behind the closure, so a violation is only reported if a hammer
// write lands between the closure's read and that receive. runCommands
// therefore hammers for a whole slice before draining. That catches reads
// made early in a closure, including fast ones; a closure that reads state
// late, after other work or a delay, can still slip through. This is a
// backstop, not a proof.
//
// Can-fail check (redo it if you change the harness): the fast case is the
// one that matters, because it is what regressed before. In callbacks.go,
// wrap the command launchIDE returns in a closure that reads settings:
//
//	inner := c.actions.launchIDE(sessionID, c.settings.IDECommand)
//	return func() tea.Msg {
//		if c.settings.IDECommand == "planted" { return nil }
//		return inner()
//	}
//
// and this test must fail under -race (the "open IDE" case). Use the value
// in a condition: a bare `_ = c.settings.IDECommand` is a dead load the
// compiler can drop, which leaves the race detector nothing to see.

import (
	"context"
	"errors"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

// raceNoopMsg is a message no handler knows, so Update routes it to the
// current view and then assigns the result back into c.views - the map write
// a leaked closure read would race with.
type raceNoopMsg struct{}

type raceFixture struct {
	coord     *Coordinator
	sessionID string
}

func newRaceFixture(t *testing.T, killSession bool) raceFixture {
	t.Helper()
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	sm := newTestManager(t, repo.Dir(), repo)

	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); saveErr != nil {
		t.Fatalf("save workspace sources: %v", saveErr)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("list workspaces: %v (%d)", err, len(workspaces))
	}

	var first config.IDCard
	for _, name := range []string{"race-a", "race-b"} {
		created, createErr := repo.CreateIDCard(
			config.IDCard{Name: name, Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "default"},
		)
		if createErr != nil {
			t.Fatalf("create card %s: %v", name, createErr)
		}
		if first.ID == "" {
			first = created
		}
	}
	card := first

	service := api.New(repo, sm)
	sessionID, err := launchSessionForTest(context.Background(), service, "default", card.ID)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	if killSession {
		if killErr := sm.Kill(sessionID); killErr != nil {
			t.Fatalf("kill: %v", killErr)
		}
	}

	c := NewCoordinator(testCapabilities(service), sm.LoadErrors())
	c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	c.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})
	c.Update(c.refreshDataSeeded()())
	return raceFixture{coord: c, sessionID: sessionID}
}

// hammer writes coordinator-goroutine state through the public message path.
func hammer(c *Coordinator) {
	c.Update(raceNoopMsg{})
	c.Update(messages.ErrorMsg{Err: errors.New("hammer")})
	c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	c.Update(
		messages.SettingsSavedMsg{
			Settings:    contracts.Settings{ShowPersonasInCardEditor: true, ShowMCPsInCardEditor: true},
			DashboardID: c.activeDashboard,
			Generation:  c.viewGeneration,
		},
	)
	c.Update(messages.ScopedNavigateMsg{View: messages.ViewSettings, DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	_ = c.View()
	c.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	_ = c.View()
}

// spawnCommands executes cmd (unwrapping tea.BatchMsg) with every leaf on its
// own goroutine, sending each leaf's message to results.
func spawnCommands(cmd tea.Cmd, results chan<- tea.Msg) {
	if cmd == nil {
		return
	}
	go func() {
		msg := cmd()
		if batch, ok := msg.(tea.BatchMsg); ok {
			for _, sub := range batch {
				spawnCommands(sub, results)
			}
			return
		}
		if msg != nil {
			results <- msg
		}
	}()
}

// drainResults moves whatever is currently queued on results into got
// without blocking, and reports whether any of it satisfied want.
func drainResults(results <-chan tea.Msg, got []tea.Msg, want func(tea.Msg) bool) ([]tea.Msg, bool) {
	matched := false
	for {
		select {
		case m := <-results:
			got = append(got, m)
			matched = matched || (want != nil && want(m))
		default:
			return got, matched
		}
	}
}

// runCommands executes cmd concurrently (see spawnCommands) while hammering
// the coordinator on this goroutine, until want has seen a result (or, with a
// nil want, for minHammer). It returns every leaf message that arrived.
func runCommands(t *testing.T, c *Coordinator, cmd tea.Cmd, want func(tea.Msg) bool) []tea.Msg {
	t.Helper()
	const (
		minHammer   = 100 * time.Millisecond
		hammerSlice = 300 * time.Millisecond
		maxWait     = 3 * time.Second
	)
	results := make(chan tea.Msg, 64)
	spawnCommands(cmd, results)

	var got []tea.Msg
	seen := want == nil
	start := time.Now()
	for time.Since(start) < maxWait && (time.Since(start) < minHammer || !seen) {
		// Hammer for a whole slice before looking at results: receiving a
		// result orders everything after it behind the closure, so a write
		// must land between the closure's read and that receive. Draining
		// after every hammer() would miss any closure that returns fast.
		for slice := time.Now(); time.Since(slice) < hammerSlice; {
			hammer(c)
		}
		var matched bool
		got, matched = drainResults(results, got, want)
		seen = seen || matched
	}
	if !seen {
		t.Fatalf("expected command to produce the awaited message within %v; got %d messages: %v", maxWait, len(got), got)
	}
	return got
}

func TestCommandClosuresDoNotRaceCoordinator(t *testing.T) {
	key := func(s string) tea.KeyPressMsg { return tea.KeyPressMsg{Code: 0, Text: s} }
	isMsg := func(match func(tea.Msg) bool) func(tea.Msg) bool { return match }

	tests := []struct {
		name       string
		killedSess bool
		// run drives Update on the test goroutine and returns the command(s)
		// whose closures will then be executed concurrently.
		run  func(t *testing.T, f raceFixture) tea.Cmd
		want func(tea.Msg) bool
	}{
		{name: "source load", run: func(_ *testing.T, f raceFixture) tea.Cmd { return f.coord.navigateTo(ViewSourceManagerSkills) }},
		{name: "source save", run: func(t *testing.T, f raceFixture) tea.Cmd {
			f.coord.navigateTo(ViewSourceManagerSkills)
			view := f.coord.views[ViewSourceManagerSkills].(*views.SourceManager)
			view.SourceList().OpenForm(-1)
			view.SourceList().Inputs[0].SetValue(t.TempDir())
			_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			return cmd
		}},
		{name: "source sync", run: func(_ *testing.T, f raceFixture) tea.Cmd {
			f.coord.navigateTo(ViewSourceManagerWorkspaces)
			_, cmd := f.coord.Update(tea.KeyPressMsg{Text: "r"})
			return cmd
		}},
		{name: "settings save", run: func(_ *testing.T, f raceFixture) tea.Cmd {
			return f.coord.settingsCallbacks().OnSave(contracts.Settings{IDECommand: "editor"})
		}, want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SettingsSavedMsg); return ok })},
		{name: "mcp save", run: func(_ *testing.T, f raceFixture) tea.Cmd {
			return f.coord.mcpCallbacks().OnSave(contracts.MCPEditor{Name: "race", Command: "echo", Args: []string{"test"}})
		}, want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.MCPSavedMsg); return ok })},

		{
			name: "idle tick",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(tickMsg(time.Now()))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SessionsRefreshedMsg); return ok }),
		},
		{
			name: "data refresh requested",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(messages.DataRefreshRequestedMsg{})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(configFingerprintMsg); return ok }),
		},
		{
			name: "dashboard list save",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				return f.coord.dashboardListCallbacks().Save("", "race dashboard", "")
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.DashboardMutationFinishedMsg); return ok }),
		},
		{
			name: "asynchronous session name",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				return f.coord.sessionLauncherCallbacks().OnSetNameAsync(f.sessionID, "race session", "expected-process")
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedSessionNamedMsg); return ok }),
		},
		{
			name: "scoped attachment readiness",
			run:  func(_ *testing.T, f raceFixture) tea.Cmd { return f.coord.requestAttach(f.sessionID) },
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedAttachReadyMsg); return ok }),
		},
		{
			name: "launch card (Enter on the cards pane)",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.DashboardCardLoadedMsg); return ok }),
		},
		{
			name: "center report read",
			run: func(t *testing.T, f raceFixture) tea.Cmd {
				cmd := f.coord.centerRead()
				if cmd == nil {
					t.Fatal("expected selected-session report command")
				}
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(centerReportsMsg); return ok }),
		},
		{
			name: "center workspace read",
			run: func(t *testing.T, f raceFixture) tea.Cmd {
				cmd := f.coord.centerWorkspace()
				if cmd == nil {
					t.Fatal("expected selected-session workspace command")
				}
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(centerWorkspaceMsg); return ok }),
		},
		{
			name: "kill the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("x"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SessionStoppedMsg); return ok }),
		},
		{
			name: "open IDE for the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("o"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.WorkspaceOpenedMsg); return ok }),
		},
		{
			name: "open terminal for the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(
					messages.SettingsSavedMsg{
						Settings:    contracts.Settings{TerminalCommand: "/bin/true"},
						DashboardID: f.coord.activeDashboard,
						Generation:  f.coord.viewGeneration,
					},
				)
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("t"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.WorkspaceOpenedMsg); return ok }),
		},
		{
			name:       "relaunch a terminated session (Enter on the sessions pane)",
			killedSess: true,
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ConversationPreparedMsg); return ok }),
		},
		{
			name:       "switch agent on a terminated session",
			killedSess: true,
			run: func(t *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(
					messages.AgentSwitchRequestedMsg{
						SessionID:   f.sessionID,
						SessionName: "race",
						DashboardID: f.coord.activeDashboard,
						Generation:  f.coord.viewGeneration,
					},
				)
				if f.coord.CurrentView() != ViewAgentSwitch {
					t.Fatalf("expected the agent-switch view, got %v", f.coord.CurrentView())
				}
				// Refresh after navigating, or the switch view's list is
				// empty and OnSwitch never fires. Twice: see
				// TestPersistFailureWarningReachesViewOnBothPaths.
				f.coord.Update(f.coord.RefreshData()())
				f.coord.Update(f.coord.RefreshData()())
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ConversationPreparedMsg); return ok }),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			f := newRaceFixture(t, tt.killedSess)
			cmd := tt.run(t, f)
			if cmd == nil {
				t.Fatal("expected Update to return a command")
			}

			// Round 1: the commands Update returned, run concurrently.
			results := runCommands(t, f.coord, cmd, tt.want)

			// Round 2: feed the results back through Update the way Bubble
			// Tea would, and run whatever those return concurrently too.
			for _, msg := range results {
				_, next := f.coord.Update(msg)
				if next != nil {
					runCommands(t, f.coord, next, nil)
				}
			}
		})
	}
}

internal/ui/components/capability_list_l.source:
package components_test

import (
	"fmt"
	"strings"
	"testing"

	bubbletea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/ui/components"
)

// Capability lists render exactly their assigned height. Row positions depend
// on size and unfiltered item count, not the cursor or search results.

type capItem struct{ id string }

func (i capItem) GetID() string          { return i.id }
func (i capItem) GetLabel() string       { return i.id }
func (i capItem) GetDescription() string { return "" }

func capItems(n int) []components.CapabilityItem {
	items := make([]components.CapabilityItem, n)
	for i := range items {
		items[i] = capItem{id: fmt.Sprintf("item-%02d", i)}
	}
	return items
}

func newSizedCapList(n, height int) *components.CapabilityList {
	l := components.NewCapabilityList(components.CapabilityListConfig{Title: "Skills", SourceHint: "hint", MaxVisible: 5})
	l.SetItems(capItems(n))
	l.SetSize(40, height)
	l.SetFocused(true)
	return l
}

func capLines(l *components.CapabilityList) []string {
	return strings.Split(ansi.Strip(l.View()), "\n")
}

// capQueries are a search that matches nothing special (none typed), one item,
// several, and nothing.
const ellipsisRow = "  ..."

var capQueries = []string{"", "item-07", "item-1", "zzz"} //nolint:gochecknoglobals // shared test fixture

// forEveryCapState calls fn for each cursor position of each query.
func forEveryCapState(l *components.CapabilityList, fn func(label string)) {
	for _, q := range capQueries {
		l.SetSearchQuery(q)
		n := len(l.FilteredItems())
		for pos := range max(n, 1) {
			l.SetCursor(pos)
			fn(fmt.Sprintf("query=%q cursor=%d", q, pos))
		}
	}
}

func TestCapabilityListRendersExactlyItsHeight(t *testing.T) {
	for height := 2; height <= 12; height++ {
		slots := height - 1
		for _, n := range []int{0, 1, slots, slots + 1, 30} {
			l := newSizedCapList(n, height)
			forEveryCapState(l, func(state string) {
				if got := len(capLines(l)); got != height {
					t.Errorf("height=%d items=%d %s: rendered %d lines, want %d:\n%s",
						height, n, state, got, height, ansi.Strip(l.View()))
				}
			})
		}
	}
}

func isCapItemRow(s string) bool {
	return strings.HasPrefix(strings.TrimLeft(s, "> "), "[") || strings.Contains(s, "(no matching items)")
}

// assertRowsInPlace checks one rendered state of a list of the given height:
// the header, the first item row, the indicator rows and the padding.
func assertRowsInPlace(t *testing.T, lines []string, height, firstItem int, overflow bool, label string) {
	t.Helper()
	if len(lines) != height {
		t.Fatalf("%s: %d lines, want %d", label, len(lines), height)
	}
	if !strings.HasPrefix(lines[0], "Skills (hint)") {
		t.Errorf("%s: row 0 is %q, want the header", label, lines[0])
	}
	if !isCapItemRow(lines[firstItem]) {
		t.Errorf("%s: row %d is %q, want the first item row:\n%s",
			label, firstItem, lines[firstItem], strings.Join(lines, "\n"))
	}
	if overflow {
		for _, row := range []int{1, height - 1} {
			if lines[row] != "" && lines[row] != ellipsisRow {
				t.Errorf("%s: row %d is %q, want blank or %q", label, row, lines[row], ellipsisRow)
			}
		}
	}
	for _, line := range lines[firstItem:] {
		if strings.TrimSpace(line) == "" && line != "" {
			t.Errorf("%s: padding line %q is not empty", label, line)
		}
	}
}

// assertIndicators checks that the "..." rows say which side has more.
func assertIndicators(t *testing.T, l *components.CapabilityList, n, height int) {
	t.Helper()
	l.SetSearchQuery("")
	for _, c := range []struct {
		name       string
		cursor     int
		top, final string
	}{
		{"top", 0, "", ellipsisRow},
		{"middle", n / 2, ellipsisRow, ellipsisRow},
		{"bottom", n - 1, ellipsisRow, ""},
	} {
		l.SetCursor(c.cursor)
		if lines := capLines(l); lines[1] != c.top || lines[height-1] != c.final {
			t.Errorf("height=%d items=%d %s: rows 1 and last are %q and %q, want %q and %q",
				height, n, c.name, lines[1], lines[height-1], c.top, c.final)
		}
	}
}

func TestCapabilityListItemsKeepTheirRows(t *testing.T) {
	for height := 4; height <= 12; height++ {
		slots := height - 1
		for _, n := range []int{2, slots, slots + 1, 30} {
			l := newSizedCapList(n, height)
			overflow := n > slots && slots >= 3
			firstItem := 1
			if overflow {
				firstItem = 2
			}
			forEveryCapState(l, func(state string) {
				assertRowsInPlace(t, capLines(l), height, firstItem, overflow, fmt.Sprintf("height=%d items=%d %s", height, n, state))
			})
			if overflow {
				assertIndicators(t, l, n, height)
			}
		}
	}
}

// TestCapabilityListScrollsThroughKeys drives the list the way the editor does
// and checks that the focused row is always rendered.
func TestCapabilityListScrollsThroughKeys(t *testing.T) {
	l := newSizedCapList(20, 7)
	for range 20 {
		plain := ansi.Strip(l.View())
		if !strings.Contains(plain, "> [") {
			t.Fatalf("cursor %d is not on screen:\n%s", l.Cursor(), plain)
		}
		l.Update(bubbletea.KeyPressMsg{Code: bubbletea.KeyDown})
	}
}

// TestCapabilityListUnsizedStillRenders: a list built before SetSize runs keeps
// the old, content-driven layout.
func TestCapabilityListUnsizedStillRenders(t *testing.T) {
	l := components.NewCapabilityList(components.CapabilityListConfig{Title: "Skills", MaxVisible: 3})
	l.SetItems(capItems(10))
	plain := ansi.Strip(l.View())
	if got := strings.Count(plain, "[ ]"); got != 3 {
		t.Errorf("unsized list shows %d items, want its MaxVisible (3):\n%s", got, plain)
	}
}

