package components_test

import (
	"strings"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/components"
	"github.com/BlackGiack/kankuro/internal/ui/models"
	"github.com/charmbracelet/x/ansi"
)

func TestSessionCenterReportsFitAndSanitize(t *testing.T) {
	p := components.NewSessionCenter()
	p.SetSize(20, 4)
	p.SetSession(&models.SessionRow{ID: "one"})
	p.SetData(
		models.SessionCenterData{
			SessionID: "one",
			Reports: []contracts.SessionReport{
				{CreatedAt: time.Unix(0, 0), Kind: "progress", Text: "\x1b[31mhello\x1b[0m 世界\nsecond"},
				{Text: "older"},
			},
		},
	)
	got := p.View()
	if strings.Contains(got, "\x1b[31m") || !strings.Contains(got, "hello") {
		t.Fatalf("unsafe or missing report: %q", got)
	}
	lines := strings.Split(got, "\n")
	if len(lines) > 4 {
		t.Fatalf("height %d", len(lines))
	}
	for _, line := range lines {
		if ansi.StringWidth(line) > 20 {
			t.Fatalf("wide line: %q", line)
		}
	}
	p.SetSession(&models.SessionRow{ID: "two"})
	if strings.Contains(p.View(), "hello") {
		t.Fatal("old session content survived selection")
	}
	p.SetSize(0, 0)
	if p.View() != "" || p.ReportLimit() != 0 {
		t.Fatal("zero size not safe")
	}
}

func TestSessionCenterKeepsSessionHeaderAboveBody(t *testing.T) {
	p := components.NewSessionCenter()
	p.SetSize(50, 20)
	row := models.SessionRow{
		ID: "session-id", Name: "Selected session", Status: "running",
		WorkingDir: "/work/project", StartedAt: time.Date(2026, 1, 1, 13, 4, 5, 0, time.UTC),
		CardName: "Active card", PuppetName: "custom", PuppetLines: []string{"puppet-artwork"},
	}
	p.SetSession(&row)
	row.PuppetLines[0] = "other-artwork"
	p.SetData(models.SessionCenterData{
		SessionID: row.ID, Workspace: &contracts.SessionWorkspaceResult{Kind: contracts.WorkspaceDirectory, WorkingDir: row.WorkingDir},
	})
	view := ansi.Strip(p.View())
	lines := strings.Split(view, "\n")
	wantLines := []string{
		"Selected session",
		"Running",
		"ID: session-id",
		"WS: /work/project",
		"Started: 13:04:05",
		"Card: Active card",
		"",
		strings.Repeat("─", 50),
		"Directory: /work/project",
	}
	if len(lines) != len(wantLines) {
		t.Fatalf("unexpected header and body rows:\n%s", view)
	}
	for i, want := range wantLines {
		line := strings.TrimSpace(lines[i])
		if !strings.HasPrefix(line, want) || (want == "" && line != "") {
			t.Fatalf("row %d should start with %q in:\n%s", i, want, view)
		}
	}
	if !strings.Contains(lines[0], "puppet-artwork") || strings.Contains(view, "other-artwork") {
		t.Fatalf("session artwork missing or aliased:\n%s", view)
	}

	row.Name, row.Status = "Renamed session", "waiting"
	p.SetSession(&row)
	view = ansi.Strip(p.View())
	if !strings.Contains(view, "Renamed session") || !strings.Contains(view, "Waiting") ||
		!strings.Contains(view, "other-artwork") || !strings.Contains(view, "Directory: /work/project") {
		t.Fatalf("same-session refresh lost metadata or body:\n%s", view)
	}
	p.SetData(
		models.SessionCenterData{SessionID: row.ID, Reports: []contracts.SessionReport{{Text: "First authored report", Kind: "progress"}}},
	)
	view = ansi.Strip(p.View())
	if !strings.Contains(view, "Renamed session") || !strings.Contains(view, "First authored report") ||
		strings.Contains(view, "Directory:") {
		t.Fatalf("report did not take over the body beneath the header:\n%s", view)
	}
	p.SetSession(&models.SessionRow{ID: "next-session", Status: "terminated"})
	p.SetData(models.SessionCenterData{SessionID: row.ID, Reports: []contracts.SessionReport{{Text: "Late report"}}})
	view = ansi.Strip(p.View())
	if !strings.Contains(view, "next-session") || !strings.Contains(view, "Terminated") || !strings.Contains(view, "Loading…") ||
		strings.Contains(view, "Renamed session") || strings.Contains(view, "report") {
		t.Fatalf("new selection retained the previous session:\n%s", view)
	}
}

func TestSessionCenterReservesSpaceForBody(t *testing.T) {
	p := components.NewSessionCenter()
	row := models.SessionRow{
		ID: "session-id", Name: strings.Repeat("界", 24), Status: "running",
		WorkingDir: "/long/workspace/path/project", CardName: "card",
		PuppetName: "custom", PuppetLines: []string{"puppet-artwork"},
	}
	p.SetSession(&row)
	p.SetData(models.SessionCenterData{SessionID: row.ID, Reports: []contracts.SessionReport{{Text: "report text"}}})
	for _, tc := range []struct {
		width, height, limit int
		art                  bool
	}{{50, 20, 10, true}, {20, 16, 6, false}, {50, 4, 1, false}, {20, 2, 1, false}, {50, 1, 1, false}} {
		p.SetSize(tc.width, tc.height)
		view := ansi.Strip(p.View())
		if strings.Contains(view, "puppet-artwork") != tc.art || !strings.Contains(view, "report text") {
			t.Fatalf("%dx%d rendered unexpected header or body:\n%s", tc.width, tc.height, view)
		}
		if got := p.ReportLimit(); got != tc.limit {
			t.Fatalf("%dx%d report limit = %d, want %d", tc.width, tc.height, got, tc.limit)
		}
		lines := strings.Split(view, "\n")
		if len(lines) > tc.height {
			t.Fatalf("%dx%d rendered %d rows", tc.width, tc.height, len(lines))
		}
		for _, line := range lines {
			if ansi.StringWidth(line) > tc.width {
				t.Fatalf("%dx%d rendered wide line %q", tc.width, tc.height, line)
			}
		}
		if tc.width == 20 && tc.height == 16 && !strings.Contains(view, "project") {
			t.Fatalf("workspace tail missing from:\n%s", view)
		}
	}
}

//nolint:gocognit // The table checks several distinct rendering boundaries.
func TestSessionCenterWorkspaceNamesCannotForgeRows(t *testing.T) {
	target := "target\nWarning: forged\t\x01end"
	cases := []struct {
		name      string
		workspace contracts.SessionWorkspaceResult
		want      []string
	}{
		{
			name: "git paths",
			workspace: contracts.SessionWorkspaceResult{
				Kind:           contracts.WorkspaceGit,
				RepositoryRoot: "/repo",
				GitEntries: []contracts.GitEntry{
					{IndexStatus: '?', WorktreeStatus: '?', Path: "actual\n?? forged\t\x01end", OriginalPath: "old\nWarning: forged"},
				},
			},
			want: []string{"?? actual ?? forged", "old Warning: forged"},
		},
		{
			name: "directory name and symlink",
			workspace: contracts.SessionWorkspaceResult{
				Kind:       contracts.WorkspaceDirectory,
				WorkingDir: "/workspace",
				Entries:    []contracts.DirectoryEntry{{Name: "link\n?? forged\t\x01end", SymlinkTarget: &target}},
			},
			want: []string{"link ?? forged", "target Warning: forged"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p := components.NewSessionCenter()
			p.SetSize(200, 10)
			p.SetSession(&models.SessionRow{ID: "s"})
			p.SetData(models.SessionCenterData{SessionID: "s", Workspace: &tc.workspace})
			got := p.View()
			if strings.ContainsAny(got, "\t\x01") {
				t.Fatalf("control character leaked: %q", got)
			}
			for _, want := range tc.want {
				if !strings.Contains(got, want) {
					t.Errorf("missing sanitized %q in %q", want, got)
				}
			}
			for line := range strings.SplitSeq(got, "\n") {
				if strings.HasPrefix(line, "?? forged") || strings.HasPrefix(line, "Warning: forged") {
					t.Errorf("filename forged a row: %q", line)
				}
				if ansi.StringWidth(line) > 200 {
					t.Errorf("line overflow: %q", line)
				}
			}
		})
	}
}

func TestSessionCenterPreservesMultilineReport(t *testing.T) {
	p := components.NewSessionCenter()
	p.SetSize(80, 8)
	p.SetSession(&models.SessionRow{ID: "s"})
	p.SetData(
		models.SessionCenterData{SessionID: "s", Reports: []contracts.SessionReport{{Text: "first line\nsecond line", Kind: "progress"}}},
	)
	if got := p.View(); !strings.Contains(got, "first line\nsecond line") {
		t.Fatalf("report line breaks lost: %q", got)
	}
}

func TestSessionCenterReportHeaderKeepsKindWhenItFits(t *testing.T) {
	for _, tc := range []struct {
		width    int
		wantTime string
	}{{80, "2026-11-16 12:34"}, {20, "12:34"}} {
		p := components.NewSessionCenter()
		p.SetSize(tc.width, 2)
		p.SetSession(&models.SessionRow{ID: "s"})
		p.SetData(
			models.SessionCenterData{
				SessionID: "s",
				Reports: []contracts.SessionReport{
					{Kind: "blocked", Text: "Need input", CreatedAt: time.Date(2026, 11, 16, 12, 34, 0, 0, time.Local)},
				},
			},
		)
		got := p.View()
		if !strings.Contains(got, tc.wantTime) || !strings.Contains(got, "blocked") || !strings.Contains(got, "Need input") {
			t.Fatalf("width %d lost metadata or content: %q", tc.width, got)
		}
	}
}

func TestSessionCenterOmitsUntimestampedReport(t *testing.T) {
	p := components.NewSessionCenter()
	p.SetSession(&models.SessionRow{ID: "session"})
	p.SetSize(26, 16)
	p.SetData(models.SessionCenterData{
		SessionID: "session",
		Reports: []contracts.SessionReport{
			{
				Text:      "Newest\nline two\nline three\nline four\nline five\nline six\nline seven",
				CreatedAt: time.Date(2026, 1, 1, 15, 4, 0, 0, time.Local),
			},
			{Text: "Older", CreatedAt: time.Date(2026, 1, 1, 15, 3, 0, 0, time.Local)},
		},
	})
	view := p.View()
	if !strings.Contains(view, "15:04") || !strings.Contains(view, "Newest") || strings.Contains(view, "Older") {
		t.Fatalf("expected only the timestamped newest report: %q", view)
	}
	p.SetSize(12, 3)
	p.SetData(models.SessionCenterData{
		SessionID: "session",
		Warnings:  []string{"warning consumes the available space"},
		Reports: []contracts.SessionReport{{
			Text: "Newest long report", CreatedAt: time.Date(2026, 1, 1, 15, 4, 0, 0, time.Local),
		}},
	})
	if view = p.View(); !strings.Contains(view, "15:04 New") {
		t.Fatalf("expected a compact timestamp and clipped body together: %q", view)
	}
}

internal/ui/components/session_list_layo.source:
package components_test

import (
	"fmt"
	"strings"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/components"
	"github.com/BlackGiack/kankuro/internal/ui/uitest"
)

// Session lists stay within their assigned dimensions. Each item occupies
// SessionDelegateHeight rows plus one spacing row; names must not move the status row.

const sessionItemRows = components.SessionDelegateHeight + 1 // item rows + spacing row

// sessionListMinHeight is the shortest list the dashboard hands its sessions
// pane on a 24-row terminal: the coordinator gives the dashboard 24-4 = 20,
// the pane is 21 rows, minus its border (2) and title block (2). Below ~9 rows
// the list's own chrome (pagination) plus one item no longer fits;
// that is out of range, since the dashboard is never that short.
const sessionListMinHeight = 17

// sessionListMinWidth is the narrowest list the dashboard hands its sessions
// pane on the smallest terminal it supports (80 columns, see
// views/dashboard_layout_test.go): 80/4 = 20 pane columns minus the two border
// columns. TestSessionListFitsEveryWidth covers narrower lists too.
const sessionListMinWidth = 18

func sweepNames() []string { return uitest.AdversarialNames }

func sessionFixtures(n int, names []string) ([]session.Snapshot, []config.IDCard) {
	faces := []string{"", "happy", "focused", "thinking", "neutral"}
	statuses := []session.Status{session.StatusRunning, session.StatusWaiting, session.StatusTerminated}
	dirs := []string{
		"/home/user/projects/a-rather-long-directory-name/with/many/segments",
		"/home/用户/项目/日本語のディレクトリ/とても長い名前",
		"/tmp/x",
		"",
		"/home/user/🚀/🚀/🚀/🚀/🚀/🚀/🚀/🚀",
	}
	var cards []config.IDCard
	var sessions []session.Snapshot
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	for i := range n {
		cardID := fmt.Sprintf("card-%d", i)
		if i%7 != 6 { // every seventh session's card was deleted
			cards = append(cards, config.IDCard{
				ID:        cardID,
				Name:      names[(i+1)%len(names)],
				FaceStyle: faces[i%len(faces)],
			})
		}
		sessions = append(sessions, session.Snapshot{
			ID:              fmt.Sprintf("session-%d-%s", i, strings.Repeat("0123456789", 4)),
			CardID:          cardID,
			Name:            names[i%len(names)],
			PID:             1000 + i,
			WorkingDir:      dirs[i%len(dirs)],
			UseTmpWorkspace: i%3 == 0,
			StartedAt:       base.Add(time.Duration(i) * time.Minute),
			Status:          statuses[i%len(statuses)],
			Pinged:          i%4 == 0,
		})
	}
	return sessions, cards
}

func TestSessionListStaysWithinItsBox(t *testing.T) {
	for _, count := range []int{0, 1, 20} {
		for _, query := range []string{"", "s"} {
			sessions, cards := sessionFixtures(count, sweepNames())
			for w := sessionListMinWidth; w <= 80; w += 3 {
				for h := sessionListMinHeight; h <= 30; h += 3 {
					sl := components.NewSessionList(components.SessionListCallbacks{})
					sl.SetSize(w, h)
					sl.SetRows(sessionRowsFromSnapshots(sessions, cards))
					sl.SetSearchQuery(query)
					label := fmt.Sprintf("sessions=%d query=%q %dx%d", count, query, w, h)
					uitest.AssertWithin(t, sl.View(), w, h, label)
				}
			}
		}
	}
}

func TestSessionListRegistrationDetailsStayWithinTheirRows(t *testing.T) {
	sessions, cards := sessionFixtures(1, []string{strings.Repeat("n", 200)})
	sessions[0].Registration = session.RegistrationPending
	sessions[0].RegistrationErr = strings.Repeat("registration failure ", 20)
	sessions[0].ActiveConversationID = strings.Repeat("native-id-", 20)
	sessions[0].Conversations = map[string][]session.ConversationBinding{
		sessions[0].CardID: {{ID: sessions[0].ActiveConversationID, Name: strings.Repeat("conversation name ", 10), Driver: "codex"}},
	}
	for _, width := range []int{sessionListMinWidth, 23, 40, 80} {
		list := components.NewSessionList(components.SessionListCallbacks{})
		list.SetSize(width, sessionListMinHeight)
		list.SetRows(sessionRowsFromSnapshots(sessions, cards))
		uitest.AssertWithin(
			t,
			list.View(),
			width,
			sessionListMinHeight,
			fmt.Sprintf("registration details %dx%d", width, sessionListMinHeight),
		)
		assertItemRows(t, list, sessionListMinHeight, fmt.Sprintf("registration rows %d", width))
	}
}

// TestSessionListKeepsItemRowsInPlace checks each item against its own region.
// Every name from AdversarialNames gets its own sweep, since a single wrapped
// or overlong title shifts every row below it.
func TestSessionListKeepsItemRowsInPlace(t *testing.T) {
	for i, name := range sweepNames() {
		sessions, cards := sessionFixtures(12, []string{name})
		for _, w := range []int{sessionListMinWidth, 23, 29, 40, 80} {
			for _, h := range []int{17, 24, 30} {
				sl := components.NewSessionList(components.SessionListCallbacks{})
				sl.SetSize(w, h)
				sl.SetRows(sessionRowsFromSnapshots(sessions, cards))
				label := fmt.Sprintf("name#%d %dx%d", i, w, h)
				assertItemRows(t, sl, h, label)
			}
		}
	}
}

func assertItemRows(t *testing.T, sl *components.SessionList, h int, label string) {
	t.Helper()
	out := sl.View()
	rows := strings.Split(ansi.Strip(out), "\n")
	onPage := sl.ItemsOnPage()
	if onPage*sessionItemRows-1 > h {
		t.Errorf("%s: %d items of %d rows cannot fit in %d:\n%s", label, onPage, sessionItemRows, h, ansi.Strip(out))
		return
	}
	for k := range onPage {
		row := sessionItemRows*k + 2
		if row >= len(rows) || !strings.Contains(rows[row], "pid=") && !strings.Contains(rows[row], "wai") &&
			!strings.Contains(rows[row], "run") && !strings.Contains(rows[row], "ter") {
			t.Errorf("%s: item %d has no status row at line %d:\n%s", label, k, row, ansi.Strip(out))
			return
		}
	}
	for i, r := range rows[:min(len(rows), onPage*sessionItemRows)] {
		if i%sessionItemRows == sessionItemRows-1 && strings.TrimSpace(r) != "" {
			t.Errorf("%s: spacing row %d is not blank %q:\n%s", label, i, r, ansi.Strip(out))
			return
		}
	}
}

// TestSessionListEmptyAndFilteredAway covers 0 items and a search that matches
// nothing: the filter changes what is drawn, and the result must still fit.
func TestSessionListEmptyAndFilteredAway(t *testing.T) {
	sessions, cards := sessionFixtures(5, []string{"alpha"})
	sl := components.NewSessionList(components.SessionListCallbacks{})
	sl.SetSize(30, sessionListMinHeight)
	sl.SetRows(sessionRowsFromSnapshots(sessions, cards))
	sl.SetSearchQuery("zzz-matches-nothing")
	uitest.AssertWithin(t, sl.View(), 30, sessionListMinHeight, "filtered away")
	if sl.ItemCount() != 0 {
		t.Fatalf("expected the query to match nothing, got %d items", sl.ItemCount())
	}
}

// TestSessionListDescriptionIsValidUTF8 guards the path trimming in
// Description(): it slices a byte offset, so a path with multibyte runes near
// the cut produced invalid UTF-8, which terminals draw as replacement boxes
// and which breaks width measurement.
func TestSessionListDescriptionIsValidUTF8(t *testing.T) {
	for _, dir := range []string{
		"/home/用户/项目/日本語のディレクトリ/とても長い名前",
		"/home/user/🚀/🚀/🚀/🚀/🚀/🚀/🚀/🚀",
		"/ééééééééééééééééééééééééééééé",
	} {
		item := components.SessionListItem{Session: sessionRowsFromSnapshots([]session.Snapshot{{ID: "s", WorkingDir: dir}}, nil)[0]}
		desc := item.Description()
		if !utf8.ValidString(desc) {
			t.Errorf("working dir %q: Description() is not valid UTF-8: %q", dir, desc)
		}
	}
}

// TestSessionListFitsEveryWidth is the regression test for the list's built-in
// help line ("up / down / q quit / ? more"), which was wider than the list at
// list widths 17-20, 26-28 and 35-36 (and below 17 for an empty list) and made
// the dashboard's sessions pane wrap it and grow two rows - on a stock 80- and
// 120-column terminal. It sweeps every width, narrower than the dashboard ever
// asks for, so re-enabling the help (or any other fixed-width row) fails here.
// Seen to fail: with SetShowHelp(false) removed from NewSessionList.
func TestSessionListFitsEveryWidth(t *testing.T) {
	for _, count := range []int{0, 3, 20} {
		sessions, cards := sessionFixtures(count, []string{"alpha"})
		for w := 10; w <= 80; w++ {
			sl := components.NewSessionList(components.SessionListCallbacks{})
			sl.SetSize(w, sessionListMinHeight)
			sl.SetRows(sessionRowsFromSnapshots(sessions, cards))
			uitest.AssertWithin(t, sl.View(), w, sessionListMinHeight, fmt.Sprintf("sessions=%d width=%d", count, w))
		}
	}
}

// TestSessionListNameWithTabsFitsWidth: lipgloss expands a tab to four spaces
// after the delegate has measured and truncated the title, so a name with tabs
// ends up wider than the list.
func TestSessionListNameWithTabsFitsWidth(t *testing.T) {
	sessions, cards := sessionFixtures(3, []string{"name\twith\ttabs and more text"})
	sl := components.NewSessionList(components.SessionListCallbacks{})
	sl.SetSize(30, sessionListMinHeight)
	sl.SetRows(sessionRowsFromSnapshots(sessions, cards))
	uitest.AssertWithin(t, sl.View(), 30, sessionListMinHeight, "tab name")
}

