package components_test

import (
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/ui/components"
)

func truncateInputs() []string {
	return []string{
		"",
		"short",
		"/home/user/very/long/path/to/some/project",
		"/家/项目/很长的路径/名字/文件夹/子目录",
		"/home/usér/proje\u0301ct/nested/deep/path",
		"/home/👍🎉🚀/project/deep/nested/path",
		"👨‍👩‍👧‍👦 family ❤️ heart 🇮🇹 flag",
		"名前名前名前名前名前名前",
	}
}

func TestTruncateFitsAtEveryWidth(t *testing.T) {
	fns := map[string]func(string, int) string{
		"TruncateHead": components.TruncateHead,
		"TruncateTail": components.TruncateTail,
	}
	for name, fn := range fns {
		for _, in := range truncateInputs() {
			for w := -1; w <= ansi.StringWidth(in)+2; w++ {
				got := fn(in, w)
				if !utf8.ValidString(got) {
					t.Fatalf("%s(%q, %d) = %q: invalid UTF-8", name, in, w, got)
				}
				if gw := ansi.StringWidth(got); gw > max(w, 0) {
					t.Fatalf("%s(%q, %d) = %q: width %d exceeds %d", name, in, w, got, gw, w)
				}
				if ansi.StringWidth(in) <= w && got != in {
					t.Fatalf("%s(%q, %d) = %q: text that fits was changed", name, in, w, got)
				}
			}
		}
	}
}

func TestTruncateKeepsTheRightEnd(t *testing.T) {
	in := "/home/user/very/long/path/to/some/project"
	if got, want := components.TruncateTail(in, 20), "...h/to/some/project"; got != want {
		t.Errorf("TruncateTail = %q, want %q", got, want)
	}
	if got, want := components.TruncateHead(in, 20), "/home/user/very/l..."; got != want {
		t.Errorf("TruncateHead = %q, want %q", got, want)
	}
}

func TestTruncateBelowEllipsisWidth(t *testing.T) {
	for _, w := range []int{1, 2, 3} {
		if got := components.TruncateHead("abcdefgh", w); got != "abcdefgh"[:w] {
			t.Errorf("TruncateHead w=%d = %q", w, got)
		}
		if got := components.TruncateTail("abcdefgh", w); got != "abcdefgh"[8-w:] {
			t.Errorf("TruncateTail w=%d = %q", w, got)
		}
	}
	if got := components.TruncateHead("abc", 0); got != "" {
		t.Errorf("w=0 should give an empty string, got %q", got)
	}
}

func TestDisplayText(t *testing.T) {
	tests := []struct{ name, in, want string }{
		{"plain", "my session", "my session"},
		{"tab", "a\tb", "a b"},
		{"newlines", "a\nb\r\nc", "a b  c"},
		{"control bytes dropped", "a\x00b\x07c\x1fd\x7fe", "abcde"},
		{"ansi stripped", "\x1b[31mred\x1b[0m text", "red text"},
		{"osc stripped", "\x1b]0;title\x07name", "name"},
		{"unicode kept", "名前 👍", "名前 👍"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := components.DisplayText(tt.in)
			if got != tt.want {
				t.Errorf("DisplayText(%q) = %q, want %q", tt.in, got, tt.want)
			}
			if strings.ContainsAny(got, "\t\n\r\x1b") {
				t.Errorf("DisplayText(%q) left a control character in %q", tt.in, got)
			}
		})
	}
}

internal/ui/configuration_deletion_inter.source:
package ui

import (
	"errors"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type deletingConfiguration struct {
	configurationPort

	ids []string
	err error
}

func (d *deletingConfiguration) DeleteConfiguredMCP(id string) error {
	d.ids = append(d.ids, id)
	return d.err
}

//nolint:gocognit // Both entry points must propagate success and failure.
func TestMCPDeletionUsesConfigurationCapability(t *testing.T) {
	for _, manager := range []bool{false, true} {
		for _, fail := range []bool{false, true} {
			name := "editor"
			if manager {
				name = "manager"
			}
			if fail {
				name += " failure"
			}
			t.Run(name, func(t *testing.T) {
				c, _ := newLaunchFocusCoordinator(t)
				fake := &deletingConfiguration{configurationPort: c.configuration}
				if fail {
					fake.err = errors.New("delete denied")
				}
				c.configuration = fake
				var cmd tea.Cmd
				if !manager {
					_, cmd = c.Update(messages.MCPDeleteRequestedMsg{MCPID: "custom"})
				} else {
					c.navigateTo(ViewMCPManager)
					view := c.views[ViewMCPManager].(*views.MCPManager)
					view.SetData(
						messages.DataLoadedMsg{
							MCPRows: []contracts.MCPRow{{ID: "custom", Name: "Custom", Delete: contracts.Availability{Enabled: true}}},
						},
					)
					c.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
					_, confirm := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
					if confirm == nil {
						t.Fatal("missing confirmation")
					}
					_, cmd = c.Update(confirm())
				}
				if cmd == nil {
					t.Fatal("missing deletion command")
				}
				if len(fake.ids) != 0 {
					t.Fatal("deletion ran synchronously")
				}
				replacement := &deletingConfiguration{configurationPort: fake.configurationPort}
				c.configuration = replacement
				result := cmd()
				if len(replacement.ids) != 0 {
					t.Fatal("command used replacement capability")
				}
				if len(fake.ids) != 1 || fake.ids[0] != "custom" {
					t.Fatalf("calls: %v", fake.ids)
				}
				if manager {
					m, ok := result.(messages.MCPManagerDeletedMsg)
					if !ok || !errors.Is(m.Err, fake.err) {
						t.Fatalf("result: %#v", result)
					}
				} else if fail {
					m, ok := result.(messages.ErrorMsg)
					if !ok || !errors.Is(m.Err, fake.err) {
						t.Fatalf("result: %#v", result)
					}
				} else if _, ok := result.(messages.MCPDeletedMsg); !ok {
					t.Fatalf("result: %#v", result)
				}
			})
		}
	}
}

internal/ui/configuration_pending_intern.source:
package ui

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type pendingSaveOverride struct {
	configurationPort

	settingsErr, mcpErr error
}

func (p pendingSaveOverride) SaveSettings(v contracts.Settings) error {
	if p.settingsErr != nil {
		return p.settingsErr
	}
	return p.configurationPort.SaveSettings(v)
}
func (p pendingSaveOverride) SaveMCP(v contracts.MCPEditor) (contracts.MCPEditor, error) {
	if p.mcpErr != nil {
		return contracts.MCPEditor{}, p.mcpErr
	}
	return p.configurationPort.SaveMCP(v)
}

//nolint:gocognit // Each visit and outcome must preserve its independent state.
func TestSettingsSaveCompletionRespectsVisitAndDraft(t *testing.T) {
	for _, fail := range []bool{false, true} {
		for _, destination := range []string{"source", "reopened", "new draft"} {
			t.Run(destination+map[bool]string{true: " failure", false: " success"}[fail], func(t *testing.T) {
				c, _, _, _ := newLaunchFocusCoordinatorWithRepo(t)
				failure := errors.New("save failed")
				override := pendingSaveOverride{configurationPort: c.configuration}
				if fail {
					override.settingsErr = failure
				}
				c.configuration = override
				c.navigateTo(ViewSettings)
				c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				settings := c.views[ViewSettings].(*views.SettingsView)
				settings.Input().SetValue("first")
				_, held := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				if held == nil {
					t.Fatal("missing save")
				}
				_, openSources := c.Update(tea.KeyPressMsg{Text: "p"})
				if openSources == nil {
					t.Fatal("missing puppet source navigation")
				}
				c.Update(openSources())
				if c.currentView != ViewSourceManagerPuppets {
					t.Fatal("puppet sources did not open")
				}
				if destination != "source" {
					c.navigateTo(ViewSettings)
				}
				if destination == "new draft" {
					c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
					settings.Input().SetValue("new draft")
					_, blocked := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
					if blocked != nil || !strings.Contains(settings.View(), "save is still in progress") {
						t.Fatal("pending save was not explained")
					}
				}
				marker := errors.New("current view error")
				c.err = marker
				c.Update(held())
				wantView := ViewSettings
				if destination == "source" {
					wantView = ViewSourceManagerPuppets
				}
				if c.currentView != wantView || !errors.Is(c.err, marker) {
					t.Fatalf("old result changed view/feedback: view=%v err=%v", c.currentView, c.err)
				}
				if c.settingsSaving {
					t.Fatal("pending save not released")
				}
				if !fail && c.settings.IDECommand != "first" {
					t.Fatal("saved global settings not applied")
				}
				if destination == "new draft" {
					if settings.Mode() != views.SettingsModeEdit || settings.Input().Value() != "new draft" {
						t.Fatal("old result lost newer draft")
					}
					if strings.Contains(settings.View(), "save is still in progress") {
						t.Fatal("stale pending feedback remained")
					}
					_, retry := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
					if retry == nil {
						t.Fatal("new draft could not be saved")
					}
				}
			})
		}
	}
}

func TestMCPSavePendingBlocksEditingAndRecoversOnFailure(t *testing.T) {
	c, _, _, _ := newLaunchFocusCoordinatorWithRepo(t)
	failure := errors.New("save failed")
	c.configuration = pendingSaveOverride{configurationPort: c.configuration, mcpErr: failure}
	c.navigateTo(ViewMCPForm)
	form := c.views[ViewMCPForm].(*views.MCPForm)
	form.Inputs()[0].SetValue("first")
	form.Inputs()[1].SetValue("echo")
	_, held := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if held == nil {
		t.Fatal("missing save")
	}
	c.Update(tea.KeyPressMsg{Text: "x"})
	c.Update(tea.PasteMsg{Content: "pasted"})
	_, again := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if again != nil || form.Inputs()[0].Value() != "first" || !strings.Contains(form.View(), "Saving MCP") {
		t.Fatal("pending form accepted input or hid status")
	}
	c.Update(held())
	if !errors.Is(c.err, failure) || c.currentView != ViewMCPForm {
		t.Fatal("failure was not shown")
	}
	c.Update(tea.KeyPressMsg{Text: "x"})
	if form.Inputs()[0].Value() == "first" {
		t.Fatal("failed save left form locked")
	}
	c.configuration = pendingSaveOverride{configurationPort: c.configuration.(pendingSaveOverride).configurationPort}
	_, retry := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if retry == nil {
		t.Fatal("retry not admitted")
	}
}

//nolint:gocognit // Exercise both pending keys through failure and retry.
func TestSettingsPendingBlocksEditAndAllowsRetryAfterFailure(t *testing.T) {
	for _, key := range []struct {
		name string
		msg  tea.KeyPressMsg
	}{
		{"enter", tea.KeyPressMsg{Code: tea.KeyEnter}},
		{"edit", tea.KeyPressMsg{Text: "e"}},
	} {
		t.Run(key.name, func(t *testing.T) {
			c, _, _, _ := newLaunchFocusCoordinatorWithRepo(t)
			failure := errors.New("settings save failed")
			base := c.configuration
			c.configuration = pendingSaveOverride{configurationPort: base, settingsErr: failure}
			c.navigateTo(ViewSettings)
			c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			form := c.views[ViewSettings].(*views.SettingsView)
			form.Input().SetValue("first")
			_, held := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			if held == nil {
				t.Fatal("missing save")
			}
			_, again := c.Update(key.msg)
			if again != nil || form.Mode() != views.SettingsModeDisplay || !strings.Contains(form.View(), "Saving settings") {
				t.Fatal("pending save permitted another edit or hid status")
			}
			c.Update(held())
			if !errors.Is(c.err, failure) {
				t.Fatal("missing save error")
			}
			if strings.Contains(form.View(), "Saving settings") || strings.Contains(form.View(), "save is still in progress") {
				t.Fatal("completed save retained pending feedback")
			}
			if form.Input().Value() != "first" {
				t.Fatal("failed save lost draft")
			}
			c.configuration = base
			c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			if form.Mode() != views.SettingsModeEdit {
				t.Fatal("failed save left settings locked")
			}
			_, retry := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			if retry == nil {
				t.Fatal("retry not admitted")
			}
		})
	}
}

func TestMCPSavePendingCommitsOnlyDisplayedDraft(t *testing.T) {
	c, _, _, _ := newLaunchFocusCoordinatorWithRepo(t)
	c.navigateTo(ViewMCPForm)
	form := c.views[ViewMCPForm].(*views.MCPForm)
	form.Inputs()[0].SetValue("first")
	form.Inputs()[1].SetValue("echo")
	_, held := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if held == nil {
		t.Fatal("missing save")
	}
	c.Update(tea.KeyPressMsg{Text: "x"})
	_, duplicate := c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if duplicate != nil || form.Inputs()[0].Value() != "first" {
		t.Fatal("pending edit or duplicate submission was accepted")
	}
	c.Update(held())
	rows, err := c.configuration.ReadMCPRows()
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, row := range rows {
		if row.Name == "first" {
			found = true
		}
		if row.Name == "firstx" {
			t.Fatal("blocked input was persisted")
		}
	}
	if !found || c.currentView != ViewDashboard {
		t.Fatalf("successful save: found=%v view=%v", found, c.currentView)
	}
}

internal/ui/conversation_choice_internal.source:
package ui

import (
	"context"
	"encoding/json"
	"os"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type coordinatorCodexDriver struct{ *driver.GenericCLIDriver }

func (d *coordinatorCodexDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	cfg.Driver = "cat"
	return d.GenericCLIDriver.Spawn(cfg)
}

//nolint:cyclop,gocognit,gocyclo,govet // Exercises refresh recovery for both relaunch and switch errors against real manager state.
func TestConversationChoiceRefreshesDriverAndRejectsStaleContext(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", err)
	}
	registry := driver.NewBuiltinRegistry()
	registry.Register("codex", func() driver.AgentDriver {
		return &coordinatorCodexDriver{GenericCLIDriver: driver.NewGenericCLIDriver()}
	})
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	card, err := repo.CreateIDCard(
		config.IDCard{
			DashboardID: "default",
			ID:          "conversation-card",
			Name:        "Conversation card",
			Driver:      "cat",
			WorkspaceID: workspaces[0].ID,
			MCPIDs:      []string{config.BuiltinMCPKankuro},
		},
	)
	if err != nil {
		t.Fatal(err)
	}
	service := api.New(repo, manager)
	sessionID, err := launchSessionForTest(context.Background(), service, "default", card.ID)
	if err != nil {
		t.Fatal(err)
	}
	catSnapshot, _ := manager.GetSession(sessionID)
	if _, err := manager.RegisterConversation(
		readMCPToken(t, driver.MCPConfigPath(catSnapshot.WorkingDir)),
		"cat-native-id",
		"Cat conversation",
	); err != nil {
		t.Fatal(err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	card.Driver = "codex"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	if err := service.SwitchInDashboard(
		context.Background(), "default", sessionID, card.ID,
		session.ConversationChoice{New: true},
	); err != nil {
		t.Fatal(err)
	}
	codexSnapshot, _ := manager.GetSession(sessionID)
	if _, err := manager.RegisterConversation(
		readMCPToken(t, driver.MCPConfigPath(codexSnapshot.WorkingDir)),
		"codex-native-id",
		"Codex conversation",
	); err != nil {
		t.Fatal(err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}

	preparation, err := service.ReadConversationPreparation(
		context.Background(),
		contracts.ConversationPreparationRequest{DashboardID: "default", SessionID: sessionID},
	)
	if err != nil || len(preparation.Options) != 2 {
		t.Fatalf("preparation: %+v %v", preparation, err)
	}
	originalName := preparation.Options[0].Name
	preparation.Options[0].Name = "caller mutation"
	again, err := service.ReadConversationPreparation(
		context.Background(),
		contracts.ConversationPreparationRequest{DashboardID: "default", SessionID: sessionID},
	)
	if err != nil || again.Options[0].Name != originalName {
		t.Fatalf("options not detached: %+v %v", again, err)
	}

	coord := NewCoordinator(testCapabilities(service), manager.LoadErrors())
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coord.Update(
		messages.DashboardOpenRequestedMsg{DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive},
	)
	coord.Update(coord.refreshData()())
	request := coord.DashboardCallbacks().OnRelaunch(sessionID)
	if request == nil {
		t.Fatal("relaunch request returned no command")
	}
	coord.Update(request())
	choiceView := coord.Views()[ViewConversationChoice].(*views.ConversationChoiceView)
	choiceView.SetSize(80, 20)
	if selected, ok := choiceView.SelectedOption(); !ok || selected.NativeID != "codex-native-id" {
		t.Fatalf("initial compatible selection = %#v, found=%v", selected, ok)
	}

	// An error-triggered refresh must re-read the destination driver and reselect
	// the saved conversation that is compatible with that refreshed driver.
	card.Driver = "cat"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	relaunchRefresh := coord.refreshConversationChoiceContext()
	if relaunchRefresh == nil {
		t.Fatal("missing conversation refresh")
	}
	coord.Update(relaunchRefresh())
	if !strings.Contains(choiceView.View(), "no longer available or compatible") {
		t.Fatal("changed driver did not invalidate selected conversation")
	}
	if _, cmd := choiceView.Update(tea.KeyPressMsg{Code: tea.KeyEnter}); cmd != nil {
		t.Fatal("stale choice submitted")
	}
	selected, ok := choiceView.SelectedOption()
	if !ok || selected.NativeID != "cat-native-id" {
		t.Fatalf("compatible option: %+v", selected)
	}

	card.Driver = "codex"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	switchRefresh := coord.refreshConversationChoiceContext()
	if switchRefresh == nil {
		t.Fatal("missing second refresh")
	}
	coord.Update(switchRefresh())
	selected, ok = choiceView.SelectedOption()
	if !ok || selected.NativeID != "codex-native-id" {
		t.Fatalf("refreshed compatible option: %+v", selected)
	}

	preflight, err := service.PreflightCardDeletion("default", card.ID)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := service.ConfirmCardDeletion(
		context.Background(),
		"default",
		card.ID,
		preflight.Token,
		preflight.RequiresForeignConfirmation,
	); err != nil {
		t.Fatal(err)
	}
	coord.Update(coord.refreshConversationChoiceContext()())
	if !strings.Contains(choiceView.View(), "card or dashboard is unavailable") {
		t.Fatalf("removed destination did not leave an actionable picker error: %s", choiceView.View())
	}
	if _, cmd := choiceView.Update(tea.KeyPressMsg{Code: tea.KeyEnter}); cmd != nil {
		t.Fatal("stale picker submitted an activation after its destination card disappeared")
	}
	if err := manager.Remove(sessionID); err != nil {
		t.Fatal(err)
	}
	coord.Update(coord.refreshConversationChoiceContext()())
	if !strings.Contains(choiceView.View(), "session is outside dashboard scope") {
		t.Fatalf("removed session did not leave an actionable picker error: %s", choiceView.View())
	}
}

func readMCPToken(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var config struct {
		MCPServers map[string]struct {
			Headers map[string]string `json:"headers"`
		} `json:"mcpServers"`
	}
	if unmarshalErr := json.Unmarshal(data, &config); unmarshalErr != nil {
		t.Fatal(unmarshalErr)
	}
	return strings.TrimPrefix(config.MCPServers["kankuro"].Headers["Authorization"], "Bearer ")
}

