package ui_test

import (
	"context"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/session"
	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

func newCurrentRepository(dir string) (*config.FileRepository, error) {
	if err := configstartup.PrepareStartup(dir); err != nil {
		return nil, err
	}
	return config.NewFileRepository(dir)
}

func newScopedCoordinator(repo config.Repository, manager *session.Manager) *app.Coordinator {
	return app.NewCoordinator(testCapabilities(api.New(repo, manager)), manager.LoadErrors())
}

func openDefaultDashboard(coordinator *app.Coordinator) {
	coordinator.Update(
		messages.DashboardOpenRequestedMsg{DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive},
	)
}

func newOpenedCoordinator(repo config.Repository, manager *session.Manager) *app.Coordinator {
	coordinator := newScopedCoordinator(repo, manager)
	openDefaultDashboard(coordinator)
	return coordinator
}

func createCurrentCard(repo config.Repository, card config.IDCard) (config.IDCard, error) {
	if card.DashboardID == "" {
		card.DashboardID = "default"
	}
	return repo.CreateIDCard(card)
}

func launchCurrentSession(repo config.Repository, manager *session.Manager, card config.IDCard) (string, error) {
	return launchSessionForTest(context.Background(), api.New(repo, manager), card.DashboardID, card.ID)
}

internal/ui/dashboard_list_keys_test.go.source:
package ui_test

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	app "github.com/BlackGiack/kankuro/internal/ui"
)

func TestDashboardListRequiresExplicitQuit(t *testing.T) {
	coord := newBannerCoordinator(t)
	_, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	for _, msg := range collectMsgs(t, cmd) {
		coord.Update(msg)
	}
	if coord.CurrentView() != app.ViewDashboardList {
		t.Fatal("Escape did not return to the dashboard list")
	}
	for _, size := range [][2]int{{120, 40}, {40, 10}, {120, 40}} {
		coord.Update(tea.WindowSizeMsg{Width: size[0], Height: size[1]})
		for _, key := range []tea.KeyPressMsg{
			{Code: tea.KeyEsc}, {Code: tea.KeyEsc}, {Code: 'c', Mod: tea.ModCtrl},
		} {
			_, cmd = coord.Update(key)
			for _, msg := range collectMsgs(t, cmd) {
				if _, quit := msg.(tea.QuitMsg); quit {
					t.Fatalf("key %v quit the dashboard list", key)
				}
				coord.Update(msg)
			}
			if coord.CurrentView() != app.ViewDashboardList {
				t.Fatalf("key %v left the dashboard list", key)
			}
		}
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Text: "q", Code: 'q'})
	if cmd == nil {
		t.Fatal("q returned no quit command")
	}
	if _, quit := cmd().(tea.QuitMsg); !quit {
		t.Fatal("q did not quit the dashboard list")
	}
}

internal/ui/delete_card_guard_test.go.source:
package ui_test

import (
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

// Card deletion always requires a preflight and confirmation, including when a
// session references the card. The existing session must survive deletion.
//
//nolint:gocognit,govet // Cover both deletion cases and each operation error.
func TestOnDeleteCardPreflightsAndPreservesReferencedSession(t *testing.T) {
	for _, referenced := range []bool{false, true} {
		t.Run(map[bool]string{false: "unreferenced", true: "referenced"}[referenced], func(t *testing.T) {
			repo, err := newCurrentRepository(t.TempDir())
			if err != nil {
				t.Fatal(err)
			}
			sm := newTestManager(t, repo.Dir(), repo)
			if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("workspaces: %v %v", workspaces, err)
			}
			card, err := createCurrentCard(repo, config.IDCard{Name: "Card", Driver: "cat", WorkspaceID: workspaces[0].ID})
			if err != nil {
				t.Fatal(err)
			}
			var sessionID string
			if referenced {
				sessionID, err = launchCurrentSession(repo, sm, card)
				if err != nil {
					t.Fatal(err)
				}
			}
			coord := newOpenedCoordinator(repo, sm)
			callbacks := coord.DashboardCallbacks()
			cmd, err := callbacks.OnDeleteCard(card.ID)
			if err != nil || cmd == nil {
				t.Fatalf("prepare deletion: %v", err)
			}
			prepared, ok := cmd().(messages.CardDeletionPreparedMsg)
			if !ok || prepared.Err != nil || prepared.Token == "" {
				t.Fatalf("preflight: %#v", prepared)
			}
			cards, err := repo.ListIDCards()
			if err != nil || len(cards) != 1 {
				t.Fatalf("preflight changed cards: %v %v", cards, err)
			}
			result, ok := callbacks.OnConfirmCardDeletion(card.ID, prepared.Token, prepared.RequiresForeignConfirmation)().(messages.ScopedActionFinishedMsg)
			if !ok || result.Err != nil {
				t.Fatalf("confirm: %#v", result)
			}
			cards, err = repo.ListIDCards()
			if err != nil || len(cards) != 0 {
				t.Fatalf("card remains: %v %v", cards, err)
			}
			if referenced {
				if _, ok := sm.GetSession(sessionID); !ok {
					t.Fatal("referenced session was removed")
				}
			}
		})
	}
}

internal/ui/deletion_presentation_intern.source:
package ui

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:gocognit // Exercise each outcome through both coordinator views and failed refreshes.
func TestDeletionOutcomesReachCardAndDashboardViews(t *testing.T) {
	cases := []struct {
		outcome contracts.DeletionOutcome
		want    string
	}{
		{contracts.DeletionNoIntent, "No deletion intent was saved"},
		{contracts.DeletionPendingOutcome, "Deletion is pending"},
		{contracts.DeletionCompleted, "Deletion completed"},
		{contracts.DeletionUncertain, "Deletion outcome is uncertain"},
	}
	for _, tc := range cases {
		t.Run(string(tc.outcome), func(t *testing.T) {
			for _, kind := range []string{"card", "dashboard"} {
				t.Run(kind, func(t *testing.T) {
					c, _ := newLaunchFocusCoordinator(t)
					p := contracts.DeletionProgress{
						DashboardID: c.activeDashboard,
						Outcome:     tc.outcome,
						Diagnostic:  "cleanup error",
						Sessions:    []contracts.DeletionSession{{ID: "checkpoint", Stopped: true}},
					}
					if kind == "card" {
						p.CardID = "card"
						c.cardDeleteAction = 1
						c.cardDeleteTarget = "card"
						c.Update(
							messages.ScopedActionFinishedMsg{
								DashboardID: c.activeDashboard,
								Generation:  c.viewGeneration,
								Request:     1,
								Visit:       c.deletionVisit,
								Progress:    p,
								Err:         errors.New("cleanup error"),
							},
						)
					} else {
						c.navigateTo(ViewDashboardList)
						c.dashboardDeleteAction = 1
						c.dashboardDeleteTarget = p.DashboardID
						c.Update(
							messages.DashboardMutationFinishedMsg{
								Generation: c.viewGeneration,
								Request:    1,
								Visit:      c.deletionVisit,
								Progress:   p,
								Err:        errors.New("cleanup error"),
							},
						)
					}
					check := func() {
						t.Helper()
						rendered := c.View()
						for _, want := range []string{tc.want, "cleanup error", "checkpoint"} {
							if !strings.Contains(rendered, want) {
								t.Fatalf("missing %q in view: %s", want, rendered)
							}
						}
					}
					check()
					if kind == "card" {
						readErr := errors.New("inventory failed")
						c.Update(messages.SessionsRefreshedMsg{
							DashboardID: c.activeDashboard, Generation: c.viewGeneration, SessionEpoch: c.sessionEpoch,
							InventoryRequestID: c.lastAppliedInventoryRequest + 1, Err: readErr,
							Inventory: contracts.ReadResult[contracts.DashboardInventory]{Attempted: true, Err: readErr},
						})
					} else {
						c.Update(messages.DashboardListLoadedMsg{RequestID: c.dashboardListRequest, Err: errors.New("inventory failed")})
					}
					check()
					if kind == "dashboard" {
						list := c.views[ViewDashboardList].(*views.DashboardList)
						if tc.outcome != contracts.DeletionPendingOutcome && strings.Contains(list.View(), "Delete: retry") {
							t.Fatal("unsafe retry offered for outcome")
						}
					}
				})
			}
		})
	}
}

func TestDashboardExecutionProgressSurvivesStatusReadFailure(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	c.navigateTo(ViewDashboardList)
	list := c.views[ViewDashboardList].(*views.DashboardList)
	list.SetDashboards(
		[]contracts.DashboardSummary{
			{ID: "d", Name: "Dashboard", State: contracts.DashboardDeleting, Inspect: contracts.Availability{Enabled: true}},
		},
	)
	c.dashboardDeleteAction = 1
	c.dashboardDeleteTarget = "d"
	c.Update(
		messages.DashboardMutationFinishedMsg{
			Generation: c.viewGeneration,
			Request:    1,
			Visit:      c.deletionVisit,
			Progress: contracts.DeletionProgress{
				DashboardID: "d",
				Outcome:     contracts.DeletionPendingOutcome,
				Sessions:    []contracts.DeletionSession{{ID: "checkpoint", Removed: true}},
			},
			Err: errors.New("cleanup"),
		},
	)
	c.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	c.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	c.Update(
		messages.DashboardDeletionStatusMsg{
			DashboardID: "d",
			Request:     c.dashboardDeleteRead,
			Visit:       c.deletionVisit,
			Err:         errors.New("status unavailable"),
		},
	)
	rendered := c.View()
	for _, want := range []string{"Deletion is pending", "checkpoint", "status unavailable"} {
		if !strings.Contains(rendered, want) {
			t.Fatalf("missing %q: %s", want, rendered)
		}
	}
}

func TestDeletionResultsFromOldVisitsAreIgnored(t *testing.T) {
	c, _ := newLaunchFocusCoordinator(t)
	c.cardDeleteAction = 2
	c.cardDeleteTarget = "new"
	c.Update(
		messages.ScopedActionFinishedMsg{
			DashboardID: c.activeDashboard,
			Generation:  c.viewGeneration,
			Request:     1,
			Visit:       c.deletionVisit,
			Progress:    contracts.DeletionProgress{CardID: "old", Outcome: contracts.DeletionPendingOutcome},
		},
	)
	if strings.Contains(c.View(), "Deletion is pending") {
		t.Fatal("stale card result displayed")
	}
	c.navigateTo(ViewDashboardList)
	c.dashboardDeleteAction = 2
	c.dashboardDeleteTarget = "new"
	c.Update(
		messages.DashboardMutationFinishedMsg{
			Generation: c.viewGeneration,
			Request:    1,
			Visit:      c.deletionVisit,
			Progress:   contracts.DeletionProgress{DashboardID: "old", Outcome: contracts.DeletionPendingOutcome},
		},
	)
	if strings.Contains(c.View(), "Deletion is pending") {
		t.Fatal("stale dashboard result displayed")
	}
}

