internal/ui/inline_rename_refresh_intern.source:
package ui

import (
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:gocognit // The test checks each refresh path across the rename lifecycle.
func TestInlineRenameRejectsOlderRefreshSnapshots(t *testing.T) {
	for _, kind := range []string{"full", "sessions", "fingerprint"} {
		t.Run(kind, func(t *testing.T) {
			coordinator, dashboard, manager, id := newInlineRenameCoordinator(t)
			before, ok := manager.GetSession(id)
			if !ok || before.PID <= 0 || !before.ProcessStarted {
				t.Fatalf("missing live session: %+v", before)
			}
			// Execute the reads before the rename, but withhold their results
			// until the rename's own refresh has installed the new name.
			full, ok := coordinator.refreshDataSeeded()().(configFingerprintMsg)
			if !ok || full.data == nil || full.data.Err != nil {
				t.Fatalf("full refresh failed: %+v", full)
			}
			var stale tea.Msg
			switch kind {
			case "full":
				stale = *full.data
			case "sessions":
				stale = coordinator.refreshSessions()()
			case "fingerprint":
				stale = full
			}

			coordinator.Update(tea.KeyPressMsg{Text: "e"})
			if !strings.Contains(dashboard.View(), "Rename Session") {
				t.Fatal("session edit did not open the inline rename dialog")
			}
			coordinator.Update(tea.KeyPressMsg{Code: 'a', Mod: tea.ModCtrl})
			coordinator.Update(tea.KeyPressMsg{Code: 'k', Mod: tea.ModCtrl})
			const renamed = "Renamed 日本語 session"
			coordinator.Update(tea.KeyPressMsg{Text: renamed})
			_, submit := coordinator.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
			if submit == nil {
				t.Fatal("inline rename returned no save command")
			}
			result, ok := submit().(messages.DashboardSessionRenamedMsg)
			if !ok || result.Result.Diagnostic != "" || !result.Result.Applied || result.SessionID != id {
				t.Fatalf("inline rename failed: %+v", result)
			}
			_, refresh := coordinator.Update(result)
			if refresh == nil {
				t.Fatal("successful inline rename returned no refresh")
			}
			current, ok := refresh().(configFingerprintMsg)
			if !ok || current.data == nil || current.data.Err != nil {
				t.Fatalf("rename must return a full refresh, not attachment: %+v", current)
			}
			coordinator.Update(current)
			assertInlineRenamedSession(t, coordinator, dashboard, id, renamed)

			coordinator.Update(stale)
			assertInlineRenamedSession(t, coordinator, dashboard, id, renamed)
			after, ok := manager.GetSession(id)
			if !ok || after.PID != before.PID || after.ActivationID != before.ActivationID || !after.ProcessStarted {
				t.Fatalf("rename changed activation: before=%+v after=%+v", before, after)
			}
		})
	}
}

func newInlineRenameCoordinator(t *testing.T) (*Coordinator, *views.Dashboard, *session.Manager, string) {
	t.Helper()
	coordinator, dashboard, repo, manager := newLaunchFocusCoordinatorWithRepo(t)
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspace discovery: %v, %v", workspaces, err)
	}
	card, err := repo.CreateIDCard(config.IDCard{
		DashboardID: "default", Name: "Original session", Driver: "cat", WorkspaceID: workspaces[0].ID,
	})
	if err != nil {
		t.Fatal(err)
	}
	result := coordinator.actions.port.LaunchSession(t.Context(), contracts.LaunchSessionRequest{DashboardID: "default", CardID: card.ID})
	if result.Effect != contracts.UsableActivation {
		t.Fatal(result.Diagnostic)
	}
	id := result.SessionID
	coordinator.Update(coordinator.refreshDataSeeded()())
	coordinator.Update(tea.KeyPressMsg{Code: tea.KeyTab})
	dashboard.SessionList().SetSelectedByID(id)
	dashboard.SyncCenterSelection()
	return coordinator, dashboard, manager, id
}

func assertInlineRenamedSession(t *testing.T, coordinator *Coordinator, dashboard *views.Dashboard, id, name string) {
	t.Helper()
	if coordinator.currentView != ViewDashboard || coordinator.err != nil || strings.Contains(dashboard.View(), "Rename Session") {
		t.Fatalf("inline rename did not leave a usable dashboard: view=%v err=%v", coordinator.currentView, coordinator.err)
	}
	assertFocusedSession(t, dashboard, id)
	selected, ok := dashboard.SessionList().Selected()
	if !ok || selected.Name != name {
		t.Fatalf("refresh displaced renamed selection or preview: selected=%+v preview=%q", selected, dashboard.Center().View())
	}
}

internal/ui/integration_test.go.source:
package ui_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/models"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:gocognit,gocyclo,cyclop // The test exercises the complete launch and rename journey.
func TestFullSessionLaunchFlow(t *testing.T) {
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	workspace := t.TempDir()
	if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v %v", workspaces, err)
	}
	card, err := createCurrentCard(repo, config.IDCard{Name: "Agent", Driver: "cat", WorkspaceID: workspaces[0].ID})
	if err != nil {
		t.Fatal(err)
	}
	if _, err = launchCurrentSession(repo, sm, card); err != nil {
		t.Fatalf("create existing session: %v", err)
	}
	coord := newOpenedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coord.Update(coord.RefreshData()())
	dashboard := coord.Views()[app.ViewDashboard].(*views.Dashboard)
	if !hasSessionNamed(dashboard.Sessions(), "Agent") {
		t.Fatal("older Agent session was not loaded for the filter regression")
	}
	dashboard.TogglePane()
	dashboard.Update(tea.KeyPressMsg{Text: "/"})
	dashboard.Update(tea.KeyPressMsg{Text: "Agent"})
	dashboard.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	dashboard.TogglePane()
	if dashboard.Search().SessionsQuery != "Agent" {
		t.Fatalf("could not establish retained matching filter: %+v", dashboard.Search())
	}
	_, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	var launch messages.SessionLaunchCompletedMsg
	pending := collectMsgs(t, cmd)
	for len(pending) > 0 {
		msg := pending[0]
		pending = pending[1:]
		if result, ok := msg.(messages.SessionLaunchCompletedMsg); ok {
			launch = result
		}
		_, followup := coord.Update(msg)
		if followup != nil {
			pending = append(pending, collectMsgs(t, followup)...)
		}
	}
	if launch.Result.Effect != contracts.UsableActivation || launch.Result.SessionID == "" {
		t.Fatalf("launch did not succeed: %+v", launch)
	}
	snap, ok := sm.GetSession(launch.Result.SessionID)
	if !ok || snap.CardID != card.ID || snap.WorkingDir != workspace || !snap.ProcessStarted || snap.Status != session.StatusRunning ||
		snap.PID <= 0 {
		t.Fatalf("missing live activation: %+v", snap)
	}
	selected, selectedOK := dashboard.SessionList().Selected()
	if !selectedOK || selected.ID != launch.Result.SessionID || dashboard.FocusedPane() != views.PaneSessions ||
		dashboard.CenterSessionID() != launch.Result.SessionID {
		t.Fatalf("launched session was not selected: selected=%+v ok=%v pane=%v preview=%q", selected, selectedOK,
			dashboard.FocusedPane(), dashboard.CenterSessionID())
	}
	if dashboard.Search().SessionsQuery != "Agent" {
		t.Fatalf("matching initial session name did not preserve filter: %+v", dashboard.Search())
	}
	launcher := coord.Views()[app.ViewSessionLauncher].(*views.SessionLauncher)
	launcher.SetName("Created session")
	_, nameCmd := launcher.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	var nameResult messages.ScopedSessionNamedMsg
	for _, msg := range collectMsgs(t, nameCmd) {
		if result, isNameResult := msg.(messages.ScopedSessionNamedMsg); isNameResult {
			nameResult = result
		}
	}
	if nameResult.SessionID != launch.Result.SessionID || nameResult.Result.Diagnostic != "" || !nameResult.Result.Applied {
		t.Fatalf("name confirmation failed: %+v", nameResult)
	}
	_, attachFlow := coord.Update(nameResult)
	if dashboard.Search().SessionsQuery != "Agent" {
		t.Fatalf("renamed focus cleared filter before refreshed name arrived: %+v", dashboard.Search())
	}
	if coord.CurrentView() != app.ViewDashboard {
		t.Fatal("name confirmation did not return to dashboard")
	}
	if attachFlow == nil {
		t.Fatal("name confirmation did not request attachment")
	}
	_, refresh := coord.Update(messages.AttachFinishedMsg{
		SessionID: launch.Result.SessionID, DashboardID: launch.DashboardID, Generation: launch.Generation,
	})
	for _, refreshMsg := range collectMsgs(t, refresh) {
		coord.Update(refreshMsg)
	}
	selected, selectedOK = dashboard.SessionList().Selected()
	if !selectedOK || selected.ID != launch.Result.SessionID || dashboard.CenterSessionID() != launch.Result.SessionID {
		t.Fatalf("detachment refresh changed launched session selection: selected=%+v ok=%v preview=%q", selected,
			selectedOK, dashboard.CenterSessionID())
	}
	if dashboard.Search().SessionsQuery != "" {
		t.Fatalf("filter that no longer matches confirmed name was not cleared: %+v", dashboard.Search())
	}
	bytes, err := os.ReadFile(filepath.Join(repo.Dir(), "sessions", launch.Result.SessionID+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var persisted session.Data
	if err = json.Unmarshal(bytes, &persisted); err != nil {
		t.Fatal(err)
	}
	if persisted.ID != launch.Result.SessionID || persisted.CardID != card.ID || persisted.DashboardID != "default" ||
		persisted.WorkingDir != workspace {
		t.Fatalf("persisted wrong session: %+v", persisted)
	}
}

func hasSessionNamed(sessions []models.SessionRow, name string) bool {
	for _, sess := range sessions {
		if sess.Name == name {
			return true
		}
	}
	return false
}

func TestCardCRUDFlow(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	wd := t.TempDir()
	repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	editor := coord.Views()[app.ViewCardEditor]

	testCard := config.IDCard{
		Name:        "New Card",
		Driver:      "claude",
		Model:       "opus",
		WorkspaceID: workspaces[0].ID,
	}

	editor.(*views.CardEditor).LoadEditor(
		contracts.CardEditorData{
			CanEdit: true,
			Values: contracts.CardValues{
				Name:        testCard.Name,
				Driver:      testCard.Driver,
				Model:       testCard.Model,
				WorkspaceID: testCard.WorkspaceID,
			},
		},
	)

	card := editor.(*views.CardEditor).Draft().Values
	if card.Name != testCard.Name {
		t.Errorf("Expected card name %s, got %s", testCard.Name, card.Name)
	}

	saved, err := createCurrentCard(repo, testCard)
	if err != nil {
		t.Fatalf("CreateIDCard failed: %v", err)
	}

	if saved.ID == "" {
		t.Error("Saved card should have an ID")
	}

	cards, _ := repo.ListIDCards()
	if len(cards) != 1 {
		t.Errorf("Expected 1 card in repo, got %d", len(cards))
	}
}

func TestSourceManagementFlow(t *testing.T) {
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newOpenedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	drive(t, coord, coord.NavigateTo(app.ViewSourceManagerSkills))
	manager := coord.Views()[app.ViewSourceManagerSkills].(*views.SourceManager)
	if len(manager.SourceList().Items) != 0 {
		t.Fatal("expected empty initial list")
	}
	if err = repo.SaveSkillSources([]string{"/first/source", "/second/source"}); err != nil {
		t.Fatal(err)
	}
	_, refreshCmd := coord.Update(tea.KeyPressMsg{Text: "r"})
	for _, msg := range collectMsgs(t, refreshCmd) {
		_, next := coord.Update(msg)
		if next != nil {
			drive(t, coord, next)
		}
	}
	items := manager.SourceList().Items
	if len(items) != 2 || items[0].Display() != "/first/source" || items[1].Display() != "/second/source" {
		t.Fatalf("refresh was not propagated to source view: %v", items)
	}
	if err = repo.SaveSkillSources(nil); err != nil {
		t.Fatal(err)
	}
	_, refreshCmd = coord.Update(tea.KeyPressMsg{Text: "r"})
	for _, msg := range collectMsgs(t, refreshCmd) {
		_, next := coord.Update(msg)
		if next != nil {
			drive(t, coord, next)
		}
	}
	if len(manager.SourceList().Items) != 0 {
		t.Fatal("refresh did not clear removed sources")
	}
}

func TestSessionManagementFlow(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	wd := t.TempDir()
	repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	card, _ := createCurrentCard(repo, config.IDCard{
		Name:        "Test",
		Driver:      "echo",
		Model:       "test",
		WorkspaceID: workspaces[0].ID,
	})

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	sessionID, err := launchCurrentSession(repo, sm, card)
	if err != nil {
		t.Fatalf("Launch failed: %v", err)
	}

	sessions := sm.List()
	if len(sessions) != 1 {
		t.Errorf("Expected 1 session, got %d", len(sessions))
	}

	if sessions[0].ID != sessionID {
		t.Error("Session ID mismatch")
	}
}

func TestNavigationFlow(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	viewsList := []app.ViewType{
		app.ViewDashboard,
		app.ViewCardEditor,
		app.ViewSourceManagerSkills,
		app.ViewSourceManagerPersonas,
		app.ViewSourceManagerPuppets,
		app.ViewSourceManagerWorkspaces,
		app.ViewSettings,
		app.ViewMCPForm,
	}

	for _, v := range viewsList {
		coord.NavigateTo(v)
		if coord.CurrentView() != v {
			t.Errorf("Expected %v, got %v", v, coord.CurrentView())
		}
	}
}

func TestPreviousViewRestoration(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	// 1. Dashboard -> Source Manager -> Back to Dashboard
	coord.NavigateTo(app.ViewDashboard)
	coord.NavigateTo(app.ViewSourceManagerSkills)
	if coord.CurrentView() != app.ViewSourceManagerSkills {
		t.Errorf("Expected ViewSourceManagerSkills, got %v", coord.CurrentView())
	}
	coord.Update(messages.NavigateBackMsg{})
	if coord.CurrentView() != app.ViewDashboard {
		t.Errorf("Expected ViewDashboard after back from source manager, got %v", coord.CurrentView())
	}

	// 2. Card Editor -> Source Manager -> Back to Card Editor
	coord.NavigateTo(app.ViewCardEditor)
	coord.NavigateTo(app.ViewSourceManagerPersonas)
	if coord.CurrentView() != app.ViewSourceManagerPersonas {
		t.Errorf("Expected ViewSourceManagerPersonas, got %v", coord.CurrentView())
	}
	coord.Update(messages.NavigateBackMsg{})
	if coord.CurrentView() != app.ViewCardEditor {
		t.Errorf("Expected ViewCardEditor after back from source manager, got %v", coord.CurrentView())
	}

	// 3. Card Editor -> MCP Form -> Back to Card Editor
	coord.NavigateTo(app.ViewCardEditor)
	coord.NavigateTo(app.ViewMCPForm)
	if coord.CurrentView() != app.ViewMCPForm {
		t.Errorf("Expected ViewMCPForm, got %v", coord.CurrentView())
	}
	coord.Update(messages.NavigateBackMsg{})
	if coord.CurrentView() != app.ViewCardEditor {
		t.Errorf("Expected ViewCardEditor after back from MCP form, got %v", coord.CurrentView())
	}
}

func TestSessionActionsFlow(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	wd := t.TempDir()
	repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	card, _ := createCurrentCard(repo, config.IDCard{
		Name:        "Test Card",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	})

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	// Launch a session
	sessionID, err := launchCurrentSession(repo, sm, card)
	if err != nil {
		t.Fatalf("Launch failed: %v", err)
	}

	msg := coord.RefreshData()()
	coord.Update(msg)

	// Test Attach on running session
	// We need to simulate the Enter key on the session list
	// but we can also test the callback directly via coordinator
	callbacks := coord.DashboardCallbacks()

	// Running session -> Attach
	cmd := callbacks.OnAttach(sessionID)
	if cmd == nil {
		t.Error("Expected cmd for attach")
	}

	// Terminate the session
	_ = sm.Kill(sessionID)
	msg = coord.RefreshData()()
	coord.Update(msg)

	// Terminated session -> Relaunch
	cmd = callbacks.OnRelaunch(sessionID)
	if cmd == nil {
		t.Error("Expected cmd for relaunch")
	}

	// Terminated session -> Switch Agent
	newCard, err := createCurrentCard(repo, config.IDCard{
		Name:        "New Agent",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	})
	if err != nil {
		t.Fatalf("CreateIDCard failed: %v", err)
	}
	// Agent-switch is only reachable through AgentSwitchCallbacks (the
	// AgentSwitchView's callback), which - unlike DashboardCallbacks -
	// actually gets invoked by real input. It's async (the blocking
	// SwitchAgent call runs inside the returned Cmd, not synchronously
	// here), so drive it through Update the way a real Bubble Tea runtime
	// would: execute the Cmd, feed the resulting message back in.
	coord.Update(messages.AgentSwitchRequestedMsg{SessionID: sessionID, DashboardID: "default", Generation: 1})
	switchCmd := coord.AgentSwitchCallbacks().OnSwitch(sessionID, newCard.ID)
	if switchCmd == nil {
		t.Fatal("Expected cmd for switch")
	}
	result := executePreparedActivation(t, coord, switchCmd)
	if switched, ok := result.(messages.SessionActivationCompletedMsg); !ok || switched.Result.Diagnostic != "" {
		t.Fatalf("switch result: %#v", result)
	}
	coord.Update(result)

	// Verify session now uses new card
	sess, ok := sm.GetSession(sessionID)
	if !ok {
		t.Fatalf("Session %s not found", sessionID)
	}
	if sess.CardID != newCard.ID {
		t.Errorf("Expected card ID %s, got %s", newCard.ID, sess.CardID)
	}

	// Terminated session -> Remove
	// We must kill it again because SwitchAgent started it
	_ = sm.Kill(sessionID)
	cmd, err = callbacks.OnRemove(sessionID)
	if err != nil {
		t.Errorf("Remove failed: %v", err)
	}
	if cmd != nil {
		cmd()
	}
	msg = coord.RefreshData()()
	coord.Update(msg)
	if len(sm.List()) != 0 {
		t.Error("Expected 0 sessions after removal")
	}
}

