)

type focusConfiguration struct{ configurationPort }

func (focusConfiguration) DefaultSettings() contracts.Settings {
	return contracts.Settings{ShowPersonasInCardEditor: true, ShowMCPsInCardEditor: true}
}
func (focusConfiguration) SaveSettings(contracts.Settings) error { return nil }
func (focusConfiguration) SaveMCP(value contracts.MCPEditor) (contracts.MCPEditor, error) {
	return value, nil
}

// Focus-only tests inject inert capabilities and supply scoped results directly.
func newLaunchFocusCoordinator(t *testing.T, sessions ...contracts.SessionSummary) (*Coordinator, *views.Dashboard) {
	t.Helper()
	coordinator := NewCoordinator(Capabilities{
		Configuration: focusConfiguration{}, Center: centerTestPort{}, Actions: &fakeSessionPort{},
	}, nil)
	coordinator.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coordinator.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})
	dashboard := coordinator.views[ViewDashboard].(*views.Dashboard)
	coordinator.launchCardID = "test-card"
	coordinator.views[ViewSessionLauncher].(*views.SessionLauncher).SetCard(contracts.CardSummary{ID: "test-card"})
	setFocusSummaries(dashboard, sessions...)
	return coordinator, dashboard
}

func setFocusSummaries(dashboard *views.Dashboard, sessions ...contracts.SessionSummary) {
	dashboard.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{Attempted: true, Value: contracts.DashboardInventory{Sessions: sessions}},
		contracts.DisplayChoicesResult{},
	)
}

// Real repository/service fixture for tests that verify persistence and refresh.
func newLaunchFocusCoordinatorWithRepo(
	t *testing.T,
) (*Coordinator, *views.Dashboard, *config.FileRepository, *session.Manager) {
	t.Helper()
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	manager := newTestManager(t, repo.Dir(), repo)
	coordinator := NewCoordinator(testCapabilities(api.New(repo, manager)), manager.LoadErrors())
	coordinator.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coordinator.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})
	dashboard := coordinator.views[ViewDashboard].(*views.Dashboard)
	coordinator.launchCardID = "test-card"
	coordinator.views[ViewSessionLauncher].(*views.SessionLauncher).SetCard(contracts.CardSummary{ID: "test-card"})
	setFocusedSessionSnapshots(dashboard, nil)
	return coordinator, dashboard, repo, manager
}

func launchCompleted(coordinator *Coordinator, sessionID string, err error) messages.SessionLaunchCompletedMsg {
	result := contracts.LifecycleResult{Effect: contracts.UsableActivation, SessionID: sessionID, ProcessActivationID: "process"}
	if err != nil && !errors.Is(err, session.ErrPersistFailed) {
		result = contracts.LifecycleResult{Effect: contracts.NoEffect, Diagnostic: err.Error(), DiagnosticCode: contracts.DiagnosticFailure}
	} else if err != nil {
		result.Diagnostic = err.Error()
		result.DiagnosticCode = contracts.DiagnosticPersistence
	}
	return messages.SessionLaunchCompletedMsg{
		CardID:      "test-card",
		Result:      result,
		DashboardID: coordinator.activeDashboard,
		Generation:  coordinator.viewGeneration,
	}
}

func TestLaunchFocusSnapshotBeforeCompletion(t *testing.T) {
	coordinator, dashboard := newLaunchFocusCoordinator(t,
		contracts.SessionSummary{ID: "existing", Name: "Existing"},
		contracts.SessionSummary{ID: "new", Name: "New"},
	)
	coordinator.Update(launchCompleted(coordinator, "new", nil))
	assertFocusedSession(t, dashboard, "new")
}

func TestLaunchFocusRejectsRefreshStartedBeforeLaunchAndName(t *testing.T) {
	oldSession := contracts.SessionSummary{ID: "old", Name: "Agent", StartedAt: time.Unix(1, 0)}
	newSession := contracts.SessionSummary{ID: "new", Name: "Agent", StartedAt: time.Unix(2, 0)}
	coordinator, dashboard := newLaunchFocusCoordinator(t, oldSession)
	preLaunchEpoch := coordinator.sessionEpoch
	coordinator.Update(messages.ScopedNavigateMsg{
		View: messages.ViewSessionLauncher, DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
	})
	coordinator.Update(launchCompleted(coordinator, newSession.ID, nil))
	setFocusSummaries(dashboard, oldSession, newSession)
	assertFocusedSession(t, dashboard, newSession.ID)

	coordinator.Update(messages.ScopedSessionNamedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
		SessionID: newSession.ID, Name: "My task", Result: contracts.RenameSessionResult{Applied: true, Persisted: true},
	})
	stale := messages.SessionsRefreshedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
		SessionEpoch: preLaunchEpoch,
		Inventory: contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true, Value: contracts.DashboardInventory{Sessions: []contracts.SessionSummary{oldSession}},
		},
	}
	coordinator.Update(stale)
	assertFocusedSession(t, dashboard, newSession.ID)

	newSession.Name = "My task"
	current := messages.SessionsRefreshedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
		SessionEpoch: coordinator.sessionEpoch,
		Inventory: contracts.ReadResult[contracts.DashboardInventory]{
			Attempted: true, Value: contracts.DashboardInventory{Sessions: []contracts.SessionSummary{oldSession, newSession}},
		},
	}
	coordinator.Update(current)
	assertFocusedSession(t, dashboard, newSession.ID)
}

func TestLaunchFocusFailureAndEmptyIDDoNotMoveFocus(t *testing.T) {
	for _, test := range []struct {
		name      string
		sessionID string
		err       error
	}{
		{name: "fatal error", sessionID: "new", err: errors.New("launch failed")},
		{name: "empty ID"},
	} {
		t.Run(test.name, func(t *testing.T) {
			coordinator, dashboard := newLaunchFocusCoordinator(t, contracts.SessionSummary{ID: "existing", Name: "Existing"})
			coordinator.Update(launchCompleted(coordinator, test.sessionID, test.err))
			selected, ok := dashboard.SessionList().Selected()
			if !ok || selected.ID != "existing" || dashboard.FocusedPane() != views.PaneCards {
				t.Fatalf("failed launch moved focus: selected=%+v ok=%v pane=%v", selected, ok, dashboard.FocusedPane())
			}
		})
	}
}

func TestLaunchFocusPersistenceWarningStillSelectsSession(t *testing.T) {
	coordinator, dashboard := newLaunchFocusCoordinator(t,
		contracts.SessionSummary{ID: "existing", Name: "Existing"},
		contracts.SessionSummary{ID: "new", Name: "New"},
	)
	warning := errors.Join(session.ErrPersistFailed, errors.New("disk full"))
	coordinator.Update(launchCompleted(coordinator, "new", warning))
	assertFocusedSession(t, dashboard, "new")
	launcher := coordinator.views[ViewSessionLauncher].(*views.SessionLauncher)
	if launcher.LaunchErr() == nil || launcher.LaunchErr().Error() != warning.Error() {
		t.Fatalf("launcher did not retain persistence warning: %v", launcher.LaunchErr())
	}
}

func TestLaunchFocusIgnoresStaleResults(t *testing.T) {
	for _, test := range []struct {
		name        string
		dashboardID string
		generation  func(*Coordinator) uint64
	}{
		{name: "dashboard", dashboardID: "other", generation: func(c *Coordinator) uint64 { return c.viewGeneration }},
		{name: "generation", dashboardID: "default", generation: func(c *Coordinator) uint64 { return c.viewGeneration - 1 }},
	} {
		t.Run(test.name, func(t *testing.T) {
			coordinator, dashboard := newLaunchFocusCoordinator(t, contracts.SessionSummary{ID: "existing", Name: "Existing"})
			coordinator.Update(messages.SessionLaunchCompletedMsg{
				Result: contracts.LifecycleResult{
					Effect:              contracts.UsableActivation,
					SessionID:           "new",
					ProcessActivationID: "process",
				},
				DashboardID: test.dashboardID,
				Generation:  test.generation(coordinator),
			})
			selected, ok := dashboard.SessionList().Selected()
			if !ok || selected.ID != "existing" || dashboard.FocusedPane() != views.PaneCards {
				t.Fatalf("stale launch moved focus: selected=%+v ok=%v pane=%v", selected, ok, dashboard.FocusedPane())
			}
		})
	}
}

func TestLaunchFocusPendingRequestIsCancelledOnDashboardExit(t *testing.T) {
	coordinator, dashboard := newLaunchFocusCoordinator(t, contracts.SessionSummary{ID: "existing", Name: "Existing"})
	staleLaunch := launchCompleted(coordinator, "new", nil)
	coordinator.Update(staleLaunch)
	coordinator.Update(messages.DashboardListRequestedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
	})
	coordinator.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})
	coordinator.Update(staleLaunch)
	setFocusSummaries(dashboard, []contracts.SessionSummary{
		{ID: "existing", Name: "Existing"},
		{ID: "new", Name: "New"},
	}...)
	selected, ok := dashboard.SessionList().Selected()
	if !ok || selected.ID != "existing" || dashboard.FocusedPane() != views.PaneCards {
		t.Fatalf("pending focus crossed dashboard exit: selected=%+v ok=%v pane=%v", selected, ok, dashboard.FocusedPane())
	}
}

func setFocusedSessionSnapshots(dashboard *views.Dashboard, snapshots []session.Snapshot) {
	dashboard.SetInventory(
		contracts.ReadResult[contracts.DashboardInventory]{Attempted: true, Value: sessionInventory(snapshots...)},
		contracts.DisplayChoicesResult{},
	)
}

func sessionInventory(snapshots ...session.Snapshot) contracts.DashboardInventory {
	summaries := make([]contracts.SessionSummary, 0, len(snapshots))
	for _, snapshot := range snapshots {
		summaries = append(summaries, contracts.SessionSummary{
			ID: snapshot.ID, DashboardID: snapshot.DashboardID, CardID: snapshot.CardID, Name: snapshot.Name,
			Status: string(snapshot.Status), StartedAt: snapshot.StartedAt,
		})
	}
	return contracts.DashboardInventory{Sessions: summaries}
}

func assertFocusedSession(t *testing.T, dashboard *views.Dashboard, sessionID string) {
	t.Helper()
	selected, ok := dashboard.SessionList().Selected()
	if !ok || selected.ID != sessionID || dashboard.FocusedPane() != views.PaneSessions || dashboard.CenterSessionID() != sessionID {
		t.Fatalf("session focus mismatch: selected=%+v ok=%v pane=%v preview=%q", selected, ok,
			dashboard.FocusedPane(), dashboard.CenterSessionID())
	}
}

func TestLaunchTransitionCannotNavigateAfterLeavingOrNewerLaunch(t *testing.T) {
	coordinator, _ := newLaunchFocusCoordinator(t)
	coordinator.actions.port = &fakeSessionPort{}
	coordinator.launchRequest, coordinator.launchCardID = 1, "old-card"
	oldCard := contracts.CardSummary{ID: "old-card", Name: "Old"}
	_, oldCmd := coordinator.Update(messages.DashboardCardLoadedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
		Request: 1, CardID: oldCard.ID, Card: oldCard, Action: messages.DashboardCardLaunch,
	})
	if coordinator.currentView != ViewSessionLauncher || oldCmd == nil {
		t.Fatal("checked card load did not enter launcher")
	}
	oldMessages := collectMsgs(oldCmd)
	if len(oldMessages) != 1 {
		t.Fatalf("old launch messages: %+v", oldMessages)
	}
	if _, ok := oldMessages[0].(messages.SessionLaunchCompletedMsg); !ok {
		t.Fatalf("launch queued a navigation: %T", oldMessages[0])
	}
	coordinator.Update(
		messages.ScopedNavigateMsg{
			View:        messages.ViewSettings,
			DashboardID: coordinator.activeDashboard,
			Generation:  coordinator.viewGeneration,
		},
	)
	coordinator.Update(oldMessages[0])
	if coordinator.currentView != ViewSettings {
		t.Fatalf("late launch changed settings view to %v", coordinator.currentView)
	}

	coordinator.Update(
		messages.ScopedNavigateMsg{
			View:        messages.ViewDashboard,
			DashboardID: coordinator.activeDashboard,
			Generation:  coordinator.viewGeneration,
		},
	)
	coordinator.launchRequest++
	coordinator.launchCardID = "new-card"
	newCard := contracts.CardSummary{ID: "new-card", Name: "New"}
	_, newCmd := coordinator.Update(messages.DashboardCardLoadedMsg{
		DashboardID: coordinator.activeDashboard, Generation: coordinator.viewGeneration,
		Request: coordinator.launchRequest, CardID: newCard.ID, Card: newCard, Action: messages.DashboardCardLaunch,
	})
	if coordinator.currentView != ViewSessionLauncher || newCmd == nil {
		t.Fatal("newer launch did not enter launcher")
	}
	coordinator.Update(oldMessages[0])
	launcher := coordinator.views[ViewSessionLauncher].(*views.SessionLauncher)
	if coordinator.currentView != ViewSessionLauncher || launcher.Card().ID != newCard.ID || launcher.LaunchDone() {
		t.Fatal("old launch changed the newer launcher")
	}
	newMessages := collectMsgs(newCmd)
	if len(newMessages) != 1 {
		t.Fatalf("new launch messages: %+v", newMessages)
	}
	coordinator.Update(newMessages[0])
	if !launcher.LaunchDone() {
		t.Fatal("new launch completion was not accepted")
	}
}

internal/ui/main_test.go.source:
package ui_test

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/testenv"
)

// TestMain runs the package inside testenv's private temp root: TMPDIR and
// KANKURO_TMP_DIR point into it, so nothing reaches the developer's real
// directories, and the package fails if a test leaves anything behind - which
// is what a manager without a Shutdown cleanup does (see newTestManager). A
// test may still override KANKURO_TMP_DIR with t.Setenv.
func TestMain(m *testing.M) {
	_, source, _, ok := runtime.Caller(0)
	if !ok {
		os.Exit(2)
	}
	root := filepath.Clean(filepath.Join(filepath.Dir(source), "..", ".."))
	mcpSkill, err := os.ReadFile(filepath.Join(root, "kankuro_skills/mcp-cli/SKILL.md"))
	if err != nil {
		os.Exit(2)
	}
	puppetSkill, err := os.ReadFile(filepath.Join(root, "kankuro_skills/kankuro-puppet/SKILL.md"))
	if err != nil {
		os.Exit(2)
	}
	config.SetBuiltinMCPCLISkillContent(mcpSkill)
	config.SetBuiltinKankuroPuppetSkillContent(puppetSkill)
	os.Exit(testenv.Run(m, "app"))
}

// newTestManager is session.NewManager plus a Cleanup that shuts it down.
// t.Cleanup runs last-in-first-out, so as long as the config dir's
// t.TempDir() was created *before* this call - always the case when the
// manager is built from it - Shutdown runs before that dir is removed, and no
// watcher can write into it afterwards.
func newTestManager(t testing.TB, configDir string, repo session.WorkspaceReader) *session.Manager {
	t.Helper()
	sm := session.NewManager(configDir, repo, session.WithStartupDelay(0))
	t.Cleanup(func() { sm.Shutdown() })
	return sm
}

internal/ui/mcp_manager_gaps_test.go.source:
package ui_test

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

// Fail at the repository mutation boundary, without relying on chmod behavior
// (which differs for root). Reads and subsequent retries use the real repository.
type mcpWriteFailureRepository struct {
	config.Repository

	saveErr   error
	deleteErr error
}

func (r *mcpWriteFailureRepository) UpsertMCP(server config.MCPServer) (config.MCPServer, error) {
	if r.saveErr != nil {
		return config.MCPServer{}, r.saveErr
	}
	return r.Repository.UpsertMCP(server)
}

func (r *mcpWriteFailureRepository) DeleteMCP(id string) error {
	if r.deleteErr != nil {
		return r.deleteErr
	}
	return r.Repository.DeleteMCP(id)
}

type mcpGapFixture struct {
	coord  *app.Coordinator
	repo   *config.FileRepository
	faults *mcpWriteFailureRepository
	other  config.Dashboard
	server config.MCPServer
}

func newMCPGapFixture(t *testing.T) *mcpGapFixture {
	t.Helper()
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	server, err := repo.UpsertMCP(config.MCPServer{Name: "Alpha", Command: "server", Description: "preserve me"})
	if err != nil {
		t.Fatal(err)
	}
	other, err := repo.CreateDashboard(config.Dashboard{Name: "Other"})
	if err != nil {
		t.Fatal(err)
	}
	faults := &mcpWriteFailureRepository{Repository: repo}
	coord := newOpenedCoordinator(faults, newTestManager(t, repo.Dir(), repo))
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	drive(t, coord, coord.RefreshData())
	f := &mcpGapFixture{coord: coord, repo: repo, faults: faults, other: other, server: server}
	f.open(t)
	return f
}

func (f *mcpGapFixture) key(t *testing.T, code rune) tea.Cmd {
	t.Helper()
	_, cmd := f.coord.Update(tea.KeyPressMsg{Code: code})
	return cmd
}

func (f *mcpGapFixture) open(t *testing.T) {
	t.Helper()
	_, cmd := f.coord.Update(tea.KeyPressMsg{Text: "m"})
	drive(t, f.coord, cmd)
	if f.coord.CurrentView() != app.ViewMCPManager {
		t.Fatal("MCP manager did not open")
	}
}

func (f *mcpGapFixture) openEditor(t *testing.T) {
	t.Helper()
	cmd := f.key(t, tea.KeyEnter)
	if cmd == nil {
		t.Fatal("missing editor request")
	}
	_, load := f.coord.Update(cmd())
	drive(t, f.coord, load)
}

func (f *mcpGapFixture) switchDashboard(t *testing.T) {
	t.Helper()
	current := f.coord.RefreshData()().(messages.DataLoadedMsg)
	f.coord.Update(messages.DashboardListRequestedMsg{DashboardID: current.DashboardID, Generation: current.Generation})
	_, cmd := f.coord.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: f.other.ID, DashboardName: f.other.Name,
		DashboardState: contracts.DashboardActive, Generation: current.Generation + 1,
	})
	drive(t, f.coord, cmd)
	f.open(t)
}

func (f *mcpGapFixture) confirmDelete(t *testing.T) tea.Cmd {
	t.Helper()
	f.key(t, tea.KeyDelete)
	cmd := f.key(t, tea.KeyEnter)
	if cmd == nil {
		t.Fatal("confirmation produced no request")
	}
	return cmd
}

func (f *mcpGapFixture) registryBytes(t *testing.T) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(f.repo.Dir(), config.MCPsFilename))
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func mcpDiskFailure(repo *config.FileRepository) error {
	return &os.PathError{Op: "rename", Path: filepath.Join(repo.Dir(), config.MCPsFilename), Err: syscall.ENOSPC}
}

func TestMCPManagerCrossDashboardRequests(t *testing.T) {
	for _, action := range []string{"edit", "delete"} {
		t.Run(action, func(t *testing.T) {
			checkMCPManagerCrossDashboardRequests(t, action)
		})
	}
}

func checkMCPManagerCrossDashboardRequests(t *testing.T, action string) {
	t.Helper()
	f := newMCPGapFixture(t)
	before := f.registryBytes(t)
	held := f.key(t, tea.KeyEnter)
	if action == "delete" {
		held = f.confirmDelete(t)
	}
	f.switchDashboard(t)
	fresh := f.confirmDelete(t)
	_, discarded := f.coord.Update(held())
	if discarded != nil || f.coord.CurrentView() != app.ViewMCPManager {
		t.Fatal("old dashboard request was admitted or navigated the new dashboard")
	}
	if !bytes.Equal(before, f.registryBytes(t)) {
		t.Fatal("discarded request mutated the registry")
	}
	// Discarding the old request must not clear the new visit's pending deletion.
	_, mutation := f.coord.Update(fresh())
	if mutation == nil {
		t.Fatal("stale request cleared the new dashboard's pending confirmation")
	}
	result := mutation().(messages.MCPManagerDeletedMsg)
	if result.Err != nil || result.DashboardID != f.other.ID {
		t.Fatalf("fresh delete: %+v", result)
	}
	_, refresh := f.coord.Update(result)
	drive(t, f.coord, refresh)
	if strings.Contains(f.coord.View(), "Alpha") {
		t.Fatal("successful deletion was not reflected in current dashboard registry")
	}
}

func TestMCPManagerCrossDashboardSaveResults(t *testing.T) {
	for _, failed := range []bool{false, true} {
		t.Run(map[bool]string{false: "success", true: "failure"}[failed], func(t *testing.T) {
			checkMCPManagerCrossDashboardSaveResults(t, failed)
		})
	}
}

func checkMCPManagerCrossDashboardSaveResults(t *testing.T, failed bool) {
	t.Helper()
	f := newMCPGapFixture(t)
	f.openEditor(t)
	f.coord.Views()[app.ViewMCPForm].(*views.MCPForm).Inputs()[0].SetValue("Saved from first dashboard")
	held := f.key(t, tea.KeyEnter)
	if failed {
		f.faults.saveErr = mcpDiskFailure(f.repo)
	}
	f.switchDashboard(t)
	f.openEditor(t)
	form := f.coord.Views()[app.ViewMCPForm].(*views.MCPForm)
	form.Inputs()[0].SetValue("Other dashboard draft")
	marker := errors.New("current dashboard error")
	f.coord.Update(messages.ErrorMsg{Err: marker})
	result := held().(messages.MCPSavedMsg)
	_, refresh := f.coord.Update(result)
	if failed && !errors.Is(result.Err, syscall.ENOSPC) {
		t.Fatalf("missing original write error: %v", result.Err)
	}
	if !failed {
		if result.Err != nil || refresh == nil {
			t.Fatalf("successful stale save must refresh global data: %v", result.Err)
		}
		drive(t, f.coord, refresh)
	}
	if f.coord.CurrentView() != app.ViewMCPForm || form.Inputs()[0].Value() != "Other dashboard draft" ||
		!errors.Is(f.coord.Err(), marker) {
		t.Fatal("old save result overwrote current form, error or navigation")
	}
	want := f.server.Name
	if !failed {
		want = "Saved from first dashboard"
	}
	data := f.coord.RefreshData()().(messages.DataLoadedMsg)
	if data.DashboardID != f.other.ID || data.MCPRows[0].Name != want {
		t.Fatalf("global save or current refresh scope incorrect: %+v", data)
	}
}

func TestMCPManagerCrossDashboardDeleteResults(t *testing.T) {
	for _, failed := range []bool{false, true} {
		t.Run(map[bool]string{false: "success", true: "failure"}[failed], func(t *testing.T) {
			checkMCPManagerCrossDashboardDeleteResults(t, failed)
		})
	}
}

func checkMCPManagerCrossDashboardDeleteResults(t *testing.T, failed bool) {
	t.Helper()
	f := newMCPGapFixture(t)
	_, held := f.coord.Update(f.confirmDelete(t)())
	if failed {
		f.faults.deleteErr = mcpDiskFailure(f.repo)
	}
	f.switchDashboard(t)
	marker := errors.New("current dashboard error")
	f.coord.Update(messages.ErrorMsg{Err: marker})
	result := held().(messages.MCPManagerDeletedMsg)
	_, refresh := f.coord.Update(result)
	if failed && !errors.Is(result.Err, syscall.ENOSPC) {
		t.Fatalf("missing original write error: %v", result.Err)
	}
	if !failed {
		if result.Err != nil || refresh == nil {
			t.Fatalf("successful stale deletion must refresh global data: %v", result.Err)
		}
		drive(t, f.coord, refresh)
	}
	if f.coord.CurrentView() != app.ViewMCPManager || !errors.Is(f.coord.Err(), marker) {
		t.Fatal("old delete result overwrote current error or navigation")
	}
	if !failed && strings.Contains(f.coord.View(), "Alpha") {
		t.Fatal("successful deletion did not refresh the new dashboard's manager")
	}
	if failed {
		f.faults.deleteErr = nil
		_, retry := f.coord.Update(f.confirmDelete(t)())
		if retry == nil || retry().(messages.MCPManagerDeletedMsg).Err != nil {
			t.Fatal("old failed deletion stranded pending state across dashboards")
		}
	}
}

func TestMCPManagerWriteFailuresRetainDataAndAllowRetry(t *testing.T) {
	for _, action := range []string{"save", "delete"} {
		t.Run(action, func(t *testing.T) {
			checkMCPManagerWriteFailuresRetainDataAndAllowRetry(t, action)
		})
	}
}

func checkMCPManagerWriteFailuresRetainDataAndAllowRetry(t *testing.T, action string) {
	t.Helper()
	f := newMCPGapFixture(t)
	before := f.registryBytes(t)
	failure := mcpDiskFailure(f.repo)
	var result tea.Msg
	if action == "save" {
		f.openEditor(t)
		f.coord.Views()[app.ViewMCPForm].(*views.MCPForm).Inputs()[0].SetValue("Retry draft")
		f.faults.saveErr = failure
		result = f.key(t, tea.KeyEnter)()
	} else {
		f.faults.deleteErr = failure
		_, cmd := f.coord.Update(f.confirmDelete(t)())
		result = cmd()
	}
	f.coord.Update(result)
	assertBannerShown(t, f.coord, failure, "MCP write failure")
	if !bytes.Equal(before, f.registryBytes(t)) {
		t.Fatal("failed write changed persisted MCP definitions")
	}
	if action == "save" {
		if f.coord.CurrentView() != app.ViewMCPForm ||
			f.coord.Views()[app.ViewMCPForm].(*views.MCPForm).Inputs()[0].Value() != "Retry draft" {
			t.Fatal("failed save discarded edited fields")
		}
		f.faults.saveErr = nil
		result = f.key(t, tea.KeyEnter)()
	} else {
		if f.coord.CurrentView() != app.ViewMCPManager || !strings.Contains(f.coord.View(), "Alpha") {
			t.Fatal("failed deletion removed the visible entry")
		}
		f.faults.deleteErr = nil
		_, cmd := f.coord.Update(f.confirmDelete(t)())
		result = cmd()
	}
	_, refresh := f.coord.Update(result)
	drive(t, f.coord, refresh)
	if f.coord.Err() != nil || f.coord.CurrentView() != app.ViewMCPManager || bytes.Equal(before, f.registryBytes(t)) {
		t.Fatal("retry did not persist the mutation and return to the refreshed manager")
	}
}

internal/ui/mcp_manager_review_test.go.source:
package ui_test

import (
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

func TestMCPManagerStaleRequests(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	server, err := repo.UpsertMCP(config.MCPServer{Name: "Alpha", Command: "cmd"})
	if err != nil {
		t.Fatal(err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newScopedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 80, Height: 24})
	openDefaultDashboard(coord)
	servers, err := repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	coord.Update(messages.DataLoadedMsg{DashboardID: "default", Generation: 1, MCPRows: mcpRowsForTest(servers)})
	open := func() { t.Helper(); _, cmd := coord.Update(tea.KeyPressMsg{Text: "m"}); coord.Update(cmd()) }
	leave := func() { t.Helper(); _, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc}); coord.Update(cmd()) }
	open()
	_, heldEdit := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	leave()
	open()
	coord.Update(heldEdit())
	if coord.CurrentView() != app.ViewMCPManager {
		t.Fatal("stale edit opened form")
	}
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	_, heldDelete := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if heldDelete == nil {
		t.Fatal("confirmation did not produce request")
	}
	leave()
	open()
	coord.Update(heldDelete())
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	_, deleteRequest := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if deleteRequest == nil {
		t.Fatal("discarded request stranded deletion")
	}
	_, deleteCmd := coord.Update(deleteRequest())
	if deleteCmd == nil {
		t.Fatal("fresh deletion was not admitted")
	}
	result := deleteCmd()
	leave()
	open()
	coord.Update(result)
	if coord.CurrentView() != app.ViewMCPManager {
		t.Fatal("delayed result changed the current view")
	}
	servers, err = repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	for _, item := range servers {
		if item.ID == server.ID {
			t.Fatal("fresh deletion did not remove server")
		}
	}
}

func TestMCPManagerEditPreservesMetadataAndNewIsBlank(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	original, err := repo.UpsertMCP(config.MCPServer{Name: "Alpha", Command: "cmd", Description: "keep this"})
	if err != nil {
		t.Fatal(err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newScopedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 80, Height: 24})
	openDefaultDashboard(coord)
	servers, err := repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	coord.Update(messages.DataLoadedMsg{DashboardID: "default", Generation: 1, MCPRows: mcpRowsForTest(servers)})
	_, cmd := coord.Update(tea.KeyPressMsg{Text: "m"})
	coord.Update(cmd())
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	_, load := coord.Update(cmd())
	drive(t, coord, load)
	form := coord.Views()[app.ViewMCPForm].(*views.MCPForm)
	form.Inputs()[0].SetValue("Updated")
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	saved := cmd().(messages.MCPSavedMsg)
	if saved.Err != nil || saved.MCP.ID != original.ID || saved.MCP.Description != original.Description {
		t.Fatalf("metadata lost: %#v", saved)
	}
	coord.Update(saved)
	servers, err = repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	coord.Update(messages.DataLoadedMsg{DashboardID: "default", Generation: 1, MCPRows: mcpRowsForTest(servers)})
	// Move from the selected custom server through the built-in row to New.
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDown})
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDown})
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	_, load = coord.Update(cmd())
	drive(t, coord, load)
	form = coord.Views()[app.ViewMCPForm].(*views.MCPForm)
	for _, input := range form.Inputs() {
		if input.Value() != "" {
			t.Fatal("new form retained old value")
		}
	}
	form.Inputs()[0].SetValue("New")
	form.Inputs()[1].SetValue("cmd")
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	created := cmd().(messages.MCPSavedMsg)
	if created.Err != nil || created.MCP.ID == original.ID || created.MCP.Description != "" {
		t.Fatalf("new inherited metadata: %#v", created)
	}
}

func TestMCPManagerReferencedDeleteReportsError(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	server, err := repo.UpsertMCP(config.MCPServer{Name: "Alpha", Command: "cmd"})
	if err != nil {
		t.Fatal(err)
	}
	if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("workspaces: %v", err)
	}
	_, err = repo.CreateIDCard(config.IDCard{
		DashboardID: "default", Name: "Card", Driver: "cat", WorkspaceID: workspaces[0].ID, MCPIDs: []string{server.ID},
	})
	if err != nil {
		t.Fatal(err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newScopedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 80, Height: 24})
	openDefaultDashboard(coord)
	servers, err := repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	coord.Update(messages.DataLoadedMsg{DashboardID: "default", Generation: 1, MCPRows: mcpRowsForTest(servers)})
	_, cmd := coord.Update(tea.KeyPressMsg{Text: "m"})
	coord.Update(cmd())
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	_, cmd = coord.Update(cmd())
	result := cmd().(messages.MCPManagerDeletedMsg)
	if result.Err == nil {
		t.Fatal("referenced server deletion succeeded")
	}
	coord.Update(result)
	if coord.Err() == nil || coord.CurrentView() != app.ViewMCPManager {
		t.Fatal("deletion failure not shown in manager")
	}
	servers, err = repo.ListMCPs()
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, item := range servers {
		found = found || item.ID == server.ID
	}
	if !found {
		t.Fatal("referenced server was removed")
	}
}

func mcpRowsForTest(servers []config.MCPServer) []contracts.MCPRow {
	rows := make([]contracts.MCPRow, 0, len(servers))
	for _, server := range servers {
		row := contracts.MCPRow{
			ID:      server.ID,
			Name:    server.Name,
			Builtin: server.Builtin,
			Edit:    contracts.Availability{Enabled: true},
			Delete:  contracts.Availability{Enabled: true},
		}
		if server.ID == config.BuiltinMCPKankuro {
			row.Edit = contracts.Availability{Reason: "read-only"}
			row.Delete = contracts.Availability{Reason: "cannot be deleted"}
		}
		rows = append(rows, row)
	}
	return rows
}

internal/ui/multi_dashboard_internal_tes.source:
package ui

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:govet // Setup errors are checked at the point of use.
func TestMultiDashboardDiscardsStaleResultsAndPreservesViews(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(
		filepath.Join(repo.Dir(), config.DashboardsFilename),
		[]byte("schema_version: 1\ndashboards:\n  - {id: a, name: A, state: active}\n  - {id: b, name: B, state: active}\n"),
		0o600,
	); err != nil {
		t.Fatal(err)
	}
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v, %v", workspaces, err)
	}
	cardA, err := repo.CreateIDCard(config.IDCard{Name: "A card", Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "a"})
	if err != nil {
		t.Fatal(err)
	}
	cardB, err := repo.CreateIDCard(config.IDCard{Name: "B card", Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "b"})
	if err != nil {
		t.Fatal(err)
	}
	manager := newTestManager(t, repo.Dir(), repo)
	service := api.New(repo, manager)
	idA, err := launchSessionForTest(context.Background(), service, "a", cardA.ID)
	if err != nil {
		t.Fatal(err)
	}
	idB, err := launchSessionForTest(context.Background(), service, "b", cardB.ID)
	if err != nil {
		t.Fatal(err)
	}
	c := NewCoordinator(testCapabilities(service), manager.LoadErrors())
	c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	c.Update(
		messages.DashboardOpenRequestedMsg{
			DashboardID: "a", DashboardName: "A", DashboardState: contracts.DashboardActive,
			Generation: c.viewGeneration,
		},
	)
	viewA := c.views[ViewDashboard]
	c.Update(messages.SessionSelectedMsg{SessionID: idB})
	if c.center.sessionID == idB {
		t.Fatal("foreign session center was selected")
	}
	stale := c.refreshData()
	stalePuppetNavigation := c.settingsCallbacks().OnOpenPuppetSources()
	oldGeneration := c.viewGeneration
	c.Update(messages.DashboardListRequestedMsg{DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	c.Update(
		messages.DashboardOpenRequestedMsg{
			DashboardID: "b", DashboardName: "B", DashboardState: contracts.DashboardActive,
			Generation: c.viewGeneration,
		},
	)
	current := c.refreshData()
	c.Update(current())
	c.Update(stale())
	c.Update(stalePuppetNavigation())
	if c.currentView != ViewDashboard {
		t.Fatal("stale settings navigation crossed dashboard context")
	}
	dashboard := c.views[ViewDashboard].(*views.Dashboard)
	if len(dashboard.Cards()) != 1 || dashboard.Cards()[0].ID != cardB.ID || len(dashboard.Sessions()) != 1 ||
		dashboard.Sessions()[0].DashboardID != "b" {
		t.Fatalf("stale refresh crossed scope: cards=%+v sessions=%+v", dashboard.Cards(), dashboard.Sessions())
	}
	c.Update(messages.SessionAttachRequestedMsg{SessionID: idA, DashboardID: "a", Generation: oldGeneration})
	c.Update(messages.ScopedNavigateMsg{View: messages.ViewSessionLauncher, DashboardID: "a", Generation: oldGeneration})
	if c.currentView != ViewDashboard || c.activeDashboard != "b" {
		t.Fatal("stale attach changed dashboard")
	}
	c.Update(messages.DashboardListRequestedMsg{DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	c.Update(
		messages.DashboardOpenRequestedMsg{
			DashboardID: "a", DashboardName: "A", DashboardState: contracts.DashboardActive,
			Generation: c.viewGeneration,
		},
	)
	if c.views[ViewDashboard] != viewA {
		t.Fatal("dashboard context was not restored")
	}
}

internal/ui/navigation_test.go.source:
package ui_test

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

//nolint:gocognit // Verify navigation across all source and settings views.
func TestCoordinator_NavigationKeys(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)

	coord := newScopedCoordinator(repo, sm)
	coord.Init()
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	openDefaultDashboard(coord)

	// Test 'n' key - should navigate to CardEditor
	_, cmd := coord.Update(tea.KeyPressMsg{Code: 0, Text: "n"})
	// Execute the captured-context navigation command
	if cmd != nil {
		coord.Update(cmd())
	}
	if coord.CurrentView() != app.ViewCardEditor {
		t.Errorf("Expected ViewCardEditor after 'n' key, got %v", coord.CurrentView())
	}

	// Navigate back to dashboard
	coord.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: "default", Generation: 1})

	// Test 'm' key - should navigate to MCPManager
	_, cmd = coord.Update(tea.KeyPressMsg{Code: 0, Text: "m"})
	// Execute the captured-context navigation command
	if cmd != nil {
		msg := cmd()
		if navigateMsg, ok := msg.(messages.ScopedNavigateMsg); ok {
			coord.Update(navigateMsg)
		}
	}
	if coord.CurrentView() != app.ViewMCPManager {
		t.Errorf("Expected ViewMCPManager after 'm' key, got %v", coord.CurrentView())
	}

	// Navigate back to dashboard
	coord.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: "default", Generation: 1})

	// Test 'w' key - should navigate to SourceManagerWorkspaces
	_, cmd = coord.Update(tea.KeyPressMsg{Code: 0, Text: "w"})
	// Execute the captured-context navigation command
	if cmd != nil {
		msg := cmd()
		if navigateMsg, ok := msg.(messages.ScopedNavigateMsg); ok {
			coord.Update(navigateMsg)
		}
	}
	if coord.CurrentView() != app.ViewSourceManagerWorkspaces {
		t.Errorf("Expected ViewSourceManagerWorkspaces after 'w' key, got %v", coord.CurrentView())
	}

	// Navigate back to dashboard
	coord.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: "default", Generation: 1})

	// Test 'c' key - should navigate to Settings
	_, cmd = coord.Update(tea.KeyPressMsg{Code: 0, Text: "c"})
	if cmd != nil {
		msg := cmd()
		if navigateMsg, ok := msg.(messages.ScopedNavigateMsg); ok {
			coord.Update(navigateMsg)
		}
	}
	if coord.CurrentView() != app.ViewSettings {
		t.Errorf("Expected ViewSettings after 'c' key, got %v", coord.CurrentView())
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Text: "p", Code: 'p'})
	if cmd == nil {
		t.Fatal("settings did not open puppet sources")
	}
	coord.Update(cmd())
	if coord.CurrentView() != app.ViewSourceManagerPuppets {
		t.Fatal("puppet sources did not open")
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	if cmd == nil {
		t.Fatal("source manager did not return to settings")
	}
	coord.Update(cmd())
	if coord.CurrentView() != app.ViewSettings {
		t.Fatal("source manager returned to the wrong view")
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	if cmd == nil {
		t.Fatal("settings did not return to dashboard")
	}
	coord.Update(cmd())
	if coord.CurrentView() != app.ViewDashboard {
		t.Fatal("settings returned to the wrong view")
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	if cmd == nil {
		t.Fatal("dashboard did not return to list")
	}
	coord.Update(cmd())
	if coord.CurrentView() != app.ViewDashboardList {
		t.Fatal("dashboard list did not open")
	}
}

func TestMCPManagerNestedNavigation(t *testing.T) {
	repo, _ := newCurrentRepository(t.TempDir())
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newScopedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 80, Height: 24})
	openDefaultDashboard(coord)
	for range 2 {
		_, cmd := coord.Update(tea.KeyPressMsg{Text: "m"})
		coord.Update(cmd())
		_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
		coord.Update(cmd())
		if coord.CurrentView() != app.ViewMCPForm {
			t.Fatal("new MCP did not open form")
		}
		_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
		coord.Update(cmd())
		if coord.CurrentView() != app.ViewMCPManager {
			t.Fatal("form did not return to list")
		}
		_, cmd = coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
		coord.Update(cmd())
		if coord.CurrentView() != app.ViewDashboard {
			t.Fatal("list did not return to dashboard")
		}
	}
}

internal/ui/refresh_cadence_internal_tes.source:
package ui

// Whitebox tests for the idle tick's config half
// (maybeRefreshConfig/Fingerprint). These live in
// package app (not app_test) because they need direct access to
// configFingerprintMsg and c.configFingerprint, which are intentionally
// unexported.

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/models"
)

// countingRepo wraps a real Repository and counts calls to the List* methods
// refreshConfig/loadConfigData reads, so a test can assert a given check did
// or did not re-read the registries.
type countingRepo struct {
	config.Repository

	cardListCalls   int
	sourceListCalls int
}

func (r *countingRepo) ListIDCards() ([]config.IDCard, error) {
	r.cardListCalls++
	return r.Repository.ListIDCards()
}

func (r *countingRepo) ListSkillSources() ([]string, error) {
	r.sourceListCalls++
	return r.Repository.ListSkillSources()
}

func newCountingCoordinator(t *testing.T) (*Coordinator, *countingRepo, *config.FileRepository) {
	t.Helper()
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	base, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	repo := &countingRepo{Repository: base}
	sm := newTestManager(t, base.Dir(), base)
	c := NewCoordinator(testCapabilities(api.New(repo, sm)), sm.LoadErrors())
	c.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})
	return c, repo, base
}

// TestMaybeRefreshConfigSkipsUnchangedRegistry pins step 1: a second
// maybeRefreshConfig check with nothing changed on disk must not re-read (and
// re-parse) the registries.
func TestMaybeRefreshConfigSkipsUnchangedRegistry(t *testing.T) {
	c, repo, _ := newCountingCoordinator(t)

	msg1, ok := c.maybeRefreshConfig()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected a configFingerprintMsg")
	}
	if msg1.data == nil {
		t.Fatal("expected the first check (no baseline yet) to read the registries")
	}
	c.configFingerprint = msg1.token
	callsAfterFirst := repo.cardListCalls
	if callsAfterFirst == 0 {
		t.Fatal("expected ListIDCards to have been called at least once")
	}

	msg2, ok := c.maybeRefreshConfig()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected a configFingerprintMsg")
	}
	if msg2.data != nil {
		t.Fatal("expected an unchanged registry to skip the reload")
	}
	if repo.cardListCalls != callsAfterFirst {
		t.Fatalf("expected no additional ListIDCards call, got %d calls (was %d)",
			repo.cardListCalls, callsAfterFirst)
	}
}

// TestMaybeRefreshConfigPicksUpFileChange pins step 1 move 2: an out-of-band
// edit to a registry file (different mtime+size) must cause the next check to
// re-read.
func TestMaybeRefreshConfigPicksUpFileChange(t *testing.T) {
	c, repo, base := newCountingCoordinator(t)

	msg1, ok := c.maybeRefreshConfig()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected a configFingerprintMsg")
	}
	c.configFingerprint = msg1.token
	callsAfterFirst := repo.cardListCalls

	idCardsPath := filepath.Join(base.Dir(), config.IDCardsFilename)
	data, err := os.ReadFile(idCardsPath)
	if err != nil {
		t.Fatalf("read id_cards.yaml: %v", err)
	}
	data = append(data, []byte("\n# touched by test\n")...)
	if writeErr := os.WriteFile(idCardsPath, data, 0o600); writeErr != nil {
		t.Fatalf("write id_cards.yaml: %v", writeErr)
	}
	// Force the mtime forward: same-second writes can otherwise be missed
	// by mtime-only comparison (documented residual - see Fingerprint).
	future := time.Now().Add(2 * time.Second)
	if chErr := os.Chtimes(idCardsPath, future, future); chErr != nil {
		t.Fatalf("chtimes id_cards.yaml: %v", chErr)
	}

	msg2, ok := c.maybeRefreshConfig()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected a configFingerprintMsg")
	}
	if msg2.data == nil {
		t.Fatal("expected the changed registry file to trigger a reload")
	}
	if repo.cardListCalls == callsAfterFirst {
		t.Fatal("expected an additional ListIDCards call after the on-disk edit")
	}
}

// TestMutationRefreshDoesNotWaitForTick pins step 1's other half: a
// mutation-triggered refresh (here, CardSavedMsg after a save) must reflect
// immediately, without going through maybeRefreshConfig/the tick at all.
func TestMutationRefreshDoesNotWaitForTick(t *testing.T) {
	c, _, base := newCountingCoordinator(t)

	wd := t.TempDir()
	if err := base.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd}}); err != nil {
		t.Fatalf("save workspace sources: %v", err)
	}
	workspaces, err := base.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("list workspaces: %v (%d)", err, len(workspaces))
	}

	saved, err := base.CreateIDCard(config.IDCard{
		DashboardID: "default",
		Name:        "Mutation Card",
		Driver:      "echo",
		WorkspaceID: workspaces[0].ID,
	})
	if err != nil {
		t.Fatalf("create card: %v", err)
	}

	c.currentView = ViewCardEditor
	_, cmd := c.Update(messages.CardSavedMsg{DashboardID: "default", Generation: c.viewGeneration})
	if cmd == nil {
		t.Fatal("expected CardSavedMsg to produce a follow-up cmd")
	}
	// Drive every message the batch produces back through Update, the way
	// the real Bubble Tea runtime would - CardSavedMsg batches a refresh
	// with a navigate, and tea.Batch gives no ordering guarantee.
	for _, m := range collectMsgs(cmd) {
		c.Update(m)
	}

	dashboard, ok := c.views[ViewDashboard].(interface {
		Cards() []models.CardRow
	})
	if !ok {
		t.Fatal("expected dashboard view with a Cards() accessor")
	}
	if got := dashboard.Cards(); len(got) != 1 || got[0].ID != saved.ID {
		t.Fatalf("expected the dashboard to have the saved card immediately, got: %v", got)
	}
}

// TestIdleTickDoesNotTriggerSourceReload pins review finding 1: the idle
// tick's sessions-only refresh must never reach a config-registry view like
// SourceManager, whose SetData reloads its source files from disk regardless
// of what changed. Before the fix, refreshSessions returned a DataLoadedMsg
// broadcast to every DataReceiver, so this failed.
func TestIdleTickDoesNotTriggerSourceReload(t *testing.T) {
	c, repo, _ := newCountingCoordinator(t)

	for range 2 {
		c.Update(c.refreshSessions()())
	}

	if repo.sourceListCalls != 0 {
		t.Fatalf("expected the idle tick to never read source files, got %d ListSkillSources calls",
			repo.sourceListCalls)
	}
}

// TestFullRefreshSeedsFingerprintBaseline pins review finding 2: a
// mutation-triggered refresh (refreshDataSeeded, used by Init and every
// mutation path) must seed c.configFingerprint, so the very next idle tick
// sees the baseline as unchanged and does not reload everything a second
// time.
func TestFullRefreshSeedsFingerprintBaseline(t *testing.T) {
	c, repo, _ := newCountingCoordinator(t)

	msg, ok := c.refreshDataSeeded()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected refreshDataSeeded to return a configFingerprintMsg")
	}
	c.Update(msg)
	callsAfterMutation := repo.cardListCalls
	if callsAfterMutation == 0 {
		t.Fatal("expected the mutation refresh to have read the registries at least once")
	}

	tickMsg, ok := c.maybeRefreshConfig()().(configFingerprintMsg)
	if !ok {
		t.Fatal("expected a configFingerprintMsg")
	}
	if tickMsg.data != nil {
		t.Fatal("expected the tick right after a mutation refresh to see an unchanged baseline")
	}
	if tickMsg.token != "" {
		t.Fatal("expected an unchanged result to carry no token")
	}
	if repo.cardListCalls != callsAfterMutation {
		t.Fatalf("expected no additional ListIDCards call from the tick, got %d (was %d)",
			repo.cardListCalls, callsAfterMutation)
	}
}

// An unchanged tick result must not overwrite a newer baseline from a mutation refresh.
func TestUnchangedTickResultDoesNotClobberNewerBaseline(t *testing.T) {
	c, _, _ := newCountingCoordinator(t)

	newerBaseline := contracts.RegistryChangeToken("opaque-newer-token")
	c.Update(configFingerprintMsg{
		token:     newerBaseline,
		requestID: 1,
		data: &messages.DataLoadedMsg{
			DashboardID: "default",
			Generation:  c.viewGeneration,
		},
		dashboardID: "default",
		generation:  c.viewGeneration,
	})
	if c.configFingerprint != newerBaseline {
		t.Fatalf("expected newer baseline to be adopted, got %q", c.configFingerprint)
	}

	// A stale tick result, captured before the mutation, arrives after it.
	c.Update(configFingerprintMsg{requestID: 0})

	if c.configFingerprint != newerBaseline {
		t.Fatalf("expected stale unchanged result not to clobber the newer baseline, got %q", c.configFingerprint)
	}
}

func TestNewerUnchangedRefreshInvalidatesOlderChangedResult(t *testing.T) {
	c, _, _ := newCountingCoordinator(t)
	c.configFingerprint = "seed"
	generation := c.viewGeneration
	c.Update(configFingerprintMsg{
		requestID: 2, dashboardID: "default", generation: generation,
	})
	c.Update(configFingerprintMsg{
		token: "older-change", requestID: 1, dashboardID: "default", generation: generation,
		data: &messages.DataLoadedMsg{DashboardID: "default", Generation: generation},
	})
	if c.configFingerprint != "seed" {
		t.Fatalf("older changed refresh replaced the baseline after a newer unchanged result: %q", c.configFingerprint)
	}
}

// TestLaunchCardAbortsOnRegistryReadError pins review finding 4: a corrupt
// registry must abort launchCard (no session created, an error surfaced via
// SessionLaunchCompletedMsg) rather than launching capability-less.
func TestLaunchCardAbortsOnRegistryReadError(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	base, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	sm := newTestManager(t, base.Dir(), base)
	c := NewCoordinator(testCapabilities(api.New(base, sm)), sm.LoadErrors())
	c.Update(messages.DashboardOpenRequestedMsg{
		DashboardID: "default", DashboardName: "Default", DashboardState: contracts.DashboardActive,
	})

	wd := t.TempDir()
	if saveErr := base.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd}}); saveErr != nil {
		t.Fatalf("save workspace sources: %v", saveErr)
	}
	workspaces, err := base.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("list workspaces: %v (%d)", err, len(workspaces))
	}

	skill, err := base.UpsertSkill(config.Skill{Name: "a skill"})
	if err != nil {
		t.Fatalf("upsert skill: %v", err)
	}

	card, err := base.CreateIDCard(config.IDCard{
		DashboardID: "default",
		Name:        "Launch Card",
		Driver:      "echo",
		WorkspaceID: workspaces[0].ID,
		SkillIDs:    []string{skill.ID},
	})
	if err != nil {
		t.Fatalf("create card: %v", err)
	}

	skillsPath := filepath.Join(base.Dir(), config.SkillsFilename)
	if writeErr := os.WriteFile(skillsPath, []byte("not: valid: yaml: :::"), 0o600); writeErr != nil {
		t.Fatalf("corrupt skills.yaml: %v", writeErr)
	}

	loadCmd := c.dashboardCallbacks().OnLaunchCard(card.ID)
	if loadCmd == nil {
		t.Fatal("expected OnLaunchCard to return a cmd")
	}
	loaded, loadSucceeded := loadCmd().(messages.DashboardCardLoadedMsg)
	if !loadSucceeded {
		t.Fatalf("expected card-load result, got %T", loaded)
	}
	_, cmd := c.Update(loaded)

	var launchMsg *messages.SessionLaunchCompletedMsg
	for _, m := range collectMsgs(cmd) {
		if lm, ok := m.(messages.SessionLaunchCompletedMsg); ok {
			launchMsg = &lm
		}
	}
	if launchMsg == nil {
		t.Fatal("expected a SessionLaunchCompletedMsg")
	}
	if launchMsg.Result.Diagnostic == "" {
		t.Fatal("expected launchCard to surface the corrupt skills.yaml read error")
	}
	if launchMsg.Result.SessionID != "" {
		t.Fatalf("expected no session ID on an aborted launch, got %q", launchMsg.Result.SessionID)
	}
	if got := sm.List(); len(got) != 0 {
		t.Fatalf("expected no session to have been created, got %d", len(got))
	}
}

// collectMsgs executes cmd, recursing into tea.BatchMsg, and returns every
// leaf message it produces.
func collectMsgs(cmd tea.Cmd) []tea.Msg {
	if cmd == nil {
		return nil
	}
	msg := cmd()
	if msg == nil {
		return nil
	}
	if batch, ok := msg.(tea.BatchMsg); ok {
		var out []tea.Msg
		for _, c := range batch {
			out = append(out, collectMsgs(c)...)
		}
		return out
	}
	return []tea.Msg{msg}
}

internal/ui/refresh_certification_intern.source:
package ui

import (
	"context"
	"errors"
	"testing"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type startupConfigurationSpy struct {
	configurationPort

	puppetSyncs int
}

func (s *startupConfigurationSpy) SyncSources(ctx context.Context, kind contracts.SourceKind) contracts.SourceSyncResult {
	if kind == contracts.SourcePuppets {
		s.puppetSyncs++
	}
	return s.configurationPort.SyncSources(ctx, kind)
}

func TestCoordinatorStartupReadsRegistriesWithoutResyncingPuppets(t *testing.T) {
	_, _, repo := newCountingCoordinator(t)
	service := api.New(repo, nil)
	ports := testCapabilities(service)
	spy := &startupConfigurationSpy{configurationPort: service}
	ports.Configuration = spy
	c := NewCoordinator(ports, nil)

	var refreshed bool
	for _, msg := range collectMsgs(c.Init()) {
		if refresh, ok := msg.(configFingerprintMsg); ok {
			if refresh.data == nil || refresh.data.Err != nil || refresh.token == "" {
				t.Fatalf("initial registry read failed to establish a baseline: %+v", refresh)
			}
			refreshed = true
		}
	}
	if !refreshed || spy.puppetSyncs != 0 {
		t.Fatalf("initial refresh completed = %t, UI puppet syncs = %d", refreshed, spy.puppetSyncs)
	}
}

type certificationReader struct {
	tokens       []tokenResult
	tokenCalls   int
	choices      contracts.DisplayChoicesResult
	inventory    contracts.DashboardInventory
	inventoryErr error
}

type tokenResult struct {
	token contracts.RegistryChangeToken
	err   error
}

func (r *certificationReader) ReadDashboardInventory() ([]contracts.DashboardSummary, error) {
	return nil, nil
}
func (r *certificationReader) ReadDashboardOverview(string) (contracts.DashboardInventory, error) {
	return r.inventory, r.inventoryErr
}
func (r *certificationReader) ReadDisplayChoices() contracts.DisplayChoicesResult { return r.choices }
func (r *certificationReader) ReadRegistryChangeToken() (contracts.RegistryChangeToken, error) {
	index := r.tokenCalls
	r.tokenCalls++
	if index >= len(r.tokens) {
		return "stable", nil
	}
	return r.tokens[index].token, r.tokens[index].err
}

func TestRefreshTokenCertificationFailuresRetryAndKeepInventory(t *testing.T) {
	tests := []struct {
		name   string
		tokens []tokenResult
	}{
		{"token read before load fails", []tokenResult{{err: errors.New("before failed")}, {token: "stable"}}},
		{"token read after load fails", []tokenResult{{token: "stable"}, {err: errors.New("after failed")}}},
		{"token changes during load", []tokenResult{{token: "before"}, {token: "after"}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c, _, _ := newCountingCoordinator(t)
			reader := successfulCertificationReader()
			reader.choices = emptySuccessfulChoices()
			reader.tokens = tt.tokens
			c.reads = reader
			msg := c.refreshDataSeeded()()
			c.Update(msg)
			if c.configFingerprint != "" || c.err == nil {
				t.Fatalf("uncertified registry baseline accepted: token=%q err=%v", c.configFingerprint, c.err)
			}
			if rows := c.views[ViewDashboard].(*views.Dashboard).Sessions(); len(rows) != 1 || rows[0].Name != "usable" {
				t.Fatalf("useful inventory was lost: %+v", rows)
			}
			// With no valid baseline, an unchanged token still triggers a new read.
			retry := c.maybeRefreshConfig()().(configFingerprintMsg)
			if retry.data == nil {
				t.Fatal("retry skipped despite invalid baseline")
			}
			c.Update(retry)
			if c.configFingerprint != "stable" {
				t.Fatalf("retry did not certify unchanged metadata: %q", c.configFingerprint)
			}
		})
	}
}

func TestFirstInventorySurvivesFailedDisplayChoices(t *testing.T) {
	c, _, _ := newCountingCoordinator(t)
	reader := successfulCertificationReader()
	choiceErr := errors.New("choice registry unavailable")
	reader.choices = contracts.DisplayChoicesResult{
		Skills:   contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Err: choiceErr},
		Personas: contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Err: choiceErr},
		Puppets:  contracts.ReadResult[[]contracts.PuppetChoice]{Attempted: true, Err: choiceErr},
	}
	reader.inventory.Cards = []contracts.CardSummary{{ID: "c", OwnerDashboardID: "default", Name: "Card", SkillIDs: []string{"missing"}}}
	c.reads = reader
	c.Update(c.refreshDataSeeded()())
	dashboard := c.views[ViewDashboard].(*views.Dashboard)
	if len(dashboard.Cards()) != 1 || dashboard.Cards()[0].ID != "c" || len(dashboard.Sessions()) != 1 {
		t.Fatalf("first successful inventory was withheld on choice failure: cards=%+v sessions=%+v",
			dashboard.Cards(), dashboard.Sessions())
	}
	if c.err == nil || c.configFingerprint != "" {
		t.Fatalf("choice failure did not surface or invalidate baseline: err=%v token=%q", c.err, c.configFingerprint)
	}
}

func TestRefreshChoiceFailuresAreIndependentAndRecover(t *testing.T) {
	for _, failed := range []string{"skills", "personas", "puppets"} {
		t.Run(failed, func(t *testing.T) { assertChoiceFailureAndRecovery(t, failed) })
	}
}

func assertChoiceFailureAndRecovery(t *testing.T, failed string) {
	t.Helper()
	c, _, _ := newCountingCoordinator(t)
	c.displayChoices = contracts.DisplayChoices{
		Skills:   []contracts.NamedChoice{{ID: "skill", Name: "prior skill"}},
		Personas: []contracts.NamedChoice{{ID: "persona", Name: "prior persona"}},
		Puppets:  []contracts.PuppetChoice{{ID: "puppet", Name: "Prior Puppet", Lines: []string{"prior art"}}},
	}
	reader := successfulCertificationReader()
	reader.choices = emptySuccessfulChoices()
	setChoiceFailure(reader, failed, errors.New("choice read failed"))
	c.reads = reader
	c.Update(c.refreshDataSeeded()())
	if c.err == nil || c.configFingerprint != "" {
		t.Fatalf("choice failure did not surface/invalidate token: err=%v token=%q", c.err, c.configFingerprint)
	}
	if rows := c.views[ViewDashboard].(*views.Dashboard).Sessions(); len(rows) != 1 || rows[0].Name != "usable" {
		t.Fatalf("inventory was discarded with independent choice failure: %+v", rows)
	}
	assertFailedChoiceRetained(t, c.displayChoices, failed)

	reader.choices = emptySuccessfulChoices()
	reader.tokens = []tokenResult{{token: "stable"}, {token: "stable"}}
	c.Update(c.refreshDataSeeded()())
	assertSuccessfulEmptyClears(t, c.displayChoices)
	if c.configFingerprint != "stable" {
		t.Fatalf("recovered reads did not certify baseline: err=%v token=%q", c.err, c.configFingerprint)
	}
}

func setChoiceFailure(reader *certificationReader, failed string, err error) {
	switch failed {
	case "skills":
		reader.choices.Skills = contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Err: err}
	case "personas":
		reader.choices.Personas = contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Err: err}
	case "puppets":
		reader.choices.Puppets = contracts.ReadResult[[]contracts.PuppetChoice]{Attempted: true, Err: err}
	}
}

func assertFailedChoiceRetained(t *testing.T, choices contracts.DisplayChoices, failed string) {
	t.Helper()
	if failed == "skills" && (len(choices.Skills) != 1 || choices.Skills[0].Name != "prior skill") {
		t.Fatalf("failed skill read discarded cache: %+v", choices.Skills)
	}
	if failed == "personas" && (len(choices.Personas) != 1 || choices.Personas[0].Name != "prior persona") {
		t.Fatalf("failed persona read discarded cache: %+v", choices.Personas)
	}
	if failed == "puppets" && (len(choices.Puppets) != 1 || choices.Puppets[0].Lines[0] != "prior art") {
		t.Fatalf("failed puppet read discarded artwork cache: %+v", choices.Puppets)
	}
}

func assertSuccessfulEmptyClears(t *testing.T, choices contracts.DisplayChoices) {
	t.Helper()
	if len(choices.Skills) != 0 {
		t.Fatalf("successful empty skills did not clear: %+v", choices.Skills)
	}
	if len(choices.Personas) != 0 {
		t.Fatalf("successful empty personas did not clear: %+v", choices.Personas)
	}
	if len(choices.Puppets) != 0 {
		t.Fatalf("successful empty puppets did not clear: %+v", choices.Puppets)
	}
}

func successfulCertificationReader() *certificationReader {
	return &certificationReader{
		tokens: []tokenResult{{token: "stable"}, {token: "stable"}},
		inventory: contracts.DashboardInventory{Sessions: []contracts.SessionSummary{{
			ID: "s", DashboardID: "default", CardID: "c", Name: "usable",
		}}},
		choices: emptySuccessfulChoices(),
	}
}

func emptySuccessfulChoices() contracts.DisplayChoicesResult {
	return contracts.DisplayChoicesResult{
		Skills:   contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Value: []contracts.NamedChoice{}},
		Personas: contracts.ReadResult[[]contracts.NamedChoice]{Attempted: true, Value: []contracts.NamedChoice{}},
		Puppets:  contracts.ReadResult[[]contracts.PuppetChoice]{Attempted: true, Value: []contracts.PuppetChoice{}},
	}
}

