package ui_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	app "github.com/BlackGiack/kankuro/internal/ui"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

// A failed skills read leaves the card editor's previous data and selection intact.
func TestTransientSkillsReadFailureDoesNotWipeCardEditor(t *testing.T) {
	repo, errRepo := newCurrentRepository(t.TempDir())
	if errRepo != nil {
		t.Fatalf("new repo: %v", errRepo)
	}
	sm := newTestManager(t, repo.Dir(), repo)

	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	card, errCreate := createCurrentCard(repo, config.IDCard{
		Name:        "With Skills",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
		SkillIDs:    []string{config.BuiltinSkillMCPCLI},
	})
	if errCreate != nil {
		t.Fatalf("create card: %v", errCreate)
	}

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coord.Update(coord.RefreshData()())

	editor, ok := coord.Views()[app.ViewCardEditor].(*views.CardEditor)
	if !ok {
		t.Fatal("expected *views.CardEditor for ViewCardEditor")
	}
	editor.LoadEditor(
		contracts.CardEditorData{
			CardID:  card.ID,
			CanEdit: true,
			Values:  contracts.CardValues{Name: card.Name, Driver: card.Driver, WorkspaceID: card.WorkspaceID, SkillIDs: card.SkillIDs},
		},
	)

	if got := editor.Draft().Values.SkillIDs; len(got) != 1 || got[0] != config.BuiltinSkillMCPCLI {
		t.Fatalf("card editor lost its skills before the read failure even happened: %v", got)
	}

	// Corrupt skills.yaml so the next ListSkills() call fails.
	skillsPath := filepath.Join(repo.Dir(), config.SkillsFilename)
	if err := os.WriteFile(skillsPath, []byte("not: valid: yaml: at: all: :::"), 0o600); err != nil {
		t.Fatalf("corrupt skills.yaml: %v", err)
	}

	msg, ok := coord.RefreshData()().(messages.DataLoadedMsg)
	if !ok {
		t.Fatal("expected refreshData to produce a DataLoadedMsg")
	}
	if msg.Err == nil {
		t.Fatal("expected refreshData to surface the corrupt skills.yaml read error")
	}
	if !msg.EditorChoices.Skills.Attempted || msg.EditorChoices.Skills.Err == nil {
		t.Fatal("expected failed skills read")
	}

	coord.Update(msg)

	got := editor.Draft().Values.SkillIDs
	if len(got) != 1 || got[0] != config.BuiltinSkillMCPCLI {
		t.Fatalf("a transient skills.yaml read failure wiped the card editor's skills: %v", got)
	}
}

// A failed cards read leaves the agent-switch list intact until a successful refresh.
func TestTransientCardsReadFailureDoesNotEmptyAgentSwitchCardList(t *testing.T) {
	repo, errRepo := newCurrentRepository(t.TempDir())
	if errRepo != nil {
		t.Fatalf("new repo: %v", errRepo)
	}
	sm := newTestManager(t, repo.Dir(), repo)

	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	card, errCreate := createCurrentCard(repo, config.IDCard{
		Name:        "Switch Target Card",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	})
	if errCreate != nil {
		t.Fatalf("create card: %v", errCreate)
	}

	sessionID, errLaunch := launchCurrentSession(repo, sm, card)
	if errLaunch != nil {
		t.Fatalf("launch: %v", errLaunch)
	}
	defer func() { _ = sm.Kill(sessionID) }()

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coord.Update(coord.RefreshData()())

	// SessionName is deliberately different from card.Name - see the
	// comment on the sibling preview-trigger test above for why: the
	// header always echoes SessionName, which would make an assertion on
	// card.Name pass trivially regardless of the card list's real content.
	coord.Update(
		messages.AgentSwitchRequestedMsg{SessionID: sessionID, SessionName: "Switch Session", DashboardID: "default", Generation: 1},
	)
	if coord.CurrentView() != app.ViewAgentSwitch {
		t.Fatalf("expected ViewAgentSwitch, got %v", coord.CurrentView())
	}

	switchView, ok := coord.Views()[app.ViewAgentSwitch].(*views.AgentSwitchView)
	if !ok {
		t.Fatal("expected *views.AgentSwitchView for ViewAgentSwitch")
	}

	if view := switchView.View(); !strings.Contains(view, card.Name) {
		t.Fatalf("agent-switch view's card list was empty before the read failure even happened: %q", view)
	}

	// Corrupt id_cards.yaml so the next ListIDCards() call fails.
	idCardsPath := filepath.Join(repo.Dir(), config.IDCardsFilename)
	if err := os.WriteFile(idCardsPath, []byte("not: valid: yaml: at: all: :::"), 0o600); err != nil {
		t.Fatalf("corrupt id_cards.yaml: %v", err)
	}

	msg, ok := coord.RefreshData()().(messages.DataLoadedMsg)
	if !ok {
		t.Fatal("expected refreshData to produce a DataLoadedMsg")
	}
	if msg.Err == nil {
		t.Fatal("expected refreshData to surface the corrupt id_cards.yaml read error")
	}
	if !msg.Inventory.Attempted || msg.Inventory.Err == nil {
		t.Fatalf("expected an explicit failed inventory result, got: %+v", msg.Inventory)
	}

	coord.Update(msg)

	if view := switchView.View(); !strings.Contains(view, card.Name) {
		t.Fatalf("a transient id_cards.yaml read failure emptied the agent-switch view's card list: %q", view)
	}
}

internal/ui/scoped_refresh_error_interna.source:
package ui

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:gocognit // Exercise all refresh producers through the same failure and recovery scenario.
func TestScopedRefreshPreservesDataOnInventoryFailure(t *testing.T) {
	for _, kind := range []string{"full", "sessions", "config"} {
		t.Run(kind, func(t *testing.T) {
			root := t.TempDir()
			if err := configstartup.PrepareStartup(root); err != nil {
				t.Fatal(err)
			}
			repo, err := config.NewFileRepository(root)
			if err != nil {
				t.Fatal(err)
			}
			if err = os.WriteFile(
				filepath.Join(repo.Dir(), config.DashboardsFilename),
				[]byte("schema_version: 1\ndashboards:\n  - {id: a, name: A, state: active}\n"),
				0600,
			); err != nil {
				t.Fatal(err)
			}
			if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("workspaces: %v %v", workspaces, err)
			}
			card, err := repo.CreateIDCard(config.IDCard{Name: "card", Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "a"})
			if err != nil {
				t.Fatal(err)
			}
			manager := newTestManager(t, repo.Dir(), repo)
			service := api.New(repo, manager)
			id, err := launchSessionForTest(context.Background(), service, "a", card.ID)
			if err != nil {
				t.Fatal(err)
			}
			c := NewCoordinator(testCapabilities(service), manager.LoadErrors())
			c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
			c.Update(
				messages.DashboardOpenRequestedMsg{
					DashboardID: "a", DashboardName: "A", DashboardState: contracts.DashboardActive,
					Generation: c.viewGeneration,
				},
			)
			c.Update(c.refreshData()())
			dashboard := c.views[ViewDashboard].(*views.Dashboard)
			if len(dashboard.Cards()) != 1 || len(dashboard.Sessions()) != 1 {
				t.Fatalf("initial cards/sessions: %v %v", dashboard.Cards(), dashboard.Sessions())
			}
			path := filepath.Join(repo.Dir(), config.IDCardsFilename)
			raw, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if err = os.WriteFile(path, []byte("invalid: ["), 0600); err != nil {
				t.Fatal(err)
			}
			var cmd tea.Cmd
			switch kind {
			case "full":
				cmd = c.refreshData()
			case "sessions":
				cmd = c.refreshSessions()
			default:
				cmd = c.maybeRefreshConfig()
			}
			c.Update(cmd())
			if c.err == nil || len(dashboard.Cards()) != 1 || dashboard.Cards()[0].ID != card.ID || len(dashboard.Sessions()) != 1 ||
				dashboard.Sessions()[0].ID != id {
				t.Fatalf("failure cleared data: error=%v cards=%v sessions=%v", c.err, dashboard.Cards(), dashboard.Sessions())
			}
			if _, err = launchSessionForTest(context.Background(), service, "a", card.ID); err == nil {
				t.Fatal("corrupt inventory allowed launch")
			}
			if err = os.WriteFile(path, raw, 0600); err != nil {
				t.Fatal(err)
			}
			c.Update(c.refreshData()())
			if len(dashboard.Cards()) != 1 || len(dashboard.Sessions()) != 1 {
				t.Fatal("data did not recover")
			}
		})
	}
}

func TestScopedRefreshReturnsExplicitEmptyInventory(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	manager := newTestManager(t, repo.Dir(), repo)
	service := api.New(repo, manager)
	r := refresher{editor: service, configuration: service}
	full := unwrapRefresh(r.scopedFull(service, "default", 1, 1, 1)()).(messages.DataLoadedMsg)
	if full.Err != nil || !full.Inventory.Attempted || full.Inventory.Err != nil ||
		len(full.Inventory.Value.Cards) != 0 || len(full.Inventory.Value.Sessions) != 0 {
		t.Fatalf("empty full refresh: %+v", full)
	}
	tick := r.scopedSessions(service, "default", 1, 1)().(messages.SessionsRefreshedMsg)
	if tick.Err != nil || !tick.Inventory.Attempted || tick.Inventory.Err != nil ||
		len(tick.Inventory.Value.Cards) != 0 || len(tick.Inventory.Value.Sessions) != 0 || tick.Choices.Skills.Attempted {
		t.Fatalf("empty session refresh: %+v", tick)
	}
	changed := r.scopedConfigIfChanged(service, "default", 1, "", 1, 1)().(configFingerprintMsg)
	if changed.data == nil || changed.data.Err != nil || !changed.data.Inventory.Attempted ||
		changed.data.Inventory.Err != nil || len(changed.data.Inventory.Value.Cards) != 0 {
		t.Fatalf("empty config refresh: %+v", changed)
	}
}

