package views_test

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/uitest"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

func dashboardSummaryFixture(id, name, description string, state contracts.DashboardState) contracts.DashboardSummary {
	row := contracts.DashboardSummary{ID: id, Name: name, Description: description, State: state}
	if state == contracts.DashboardActive {
		available := contracts.Availability{Enabled: true}
		row.Open, row.Edit, row.Delete = available, available, available
	} else if state == contracts.DashboardDeleting {
		available := contracts.Availability{Enabled: true}
		row.Inspect, row.Retry = available, available
	}
	return row
}

func TestDashboardListShowsDeletionPreparationAndStatusErrors(t *testing.T) {
	tests := []struct {
		name    string
		state   contracts.DashboardState
		key     tea.KeyPressMsg
		failure tea.Msg
		success tea.Msg
	}{
		{"preflight", contracts.DashboardActive, tea.KeyPressMsg{Code: tea.KeyDelete},
			messages.DashboardDeletionPreparedMsg{DashboardID: "a", Err: errors.New("cannot prepare\nreason \x1b]0;unsafe\x07failed")},
			messages.DashboardDeletionPreparedMsg{DashboardID: "a"}},
		{"status", contracts.DashboardDeleting, tea.KeyPressMsg{Code: tea.KeyEnter},
			messages.DashboardDeletionStatusMsg{DashboardID: "a", Err: errors.New("cannot inspect\nreason \x1b]0;unsafe\x07failed")},
			messages.DashboardDeletionStatusMsg{DashboardID: "a"}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			v := views.NewDashboardList(views.DashboardListCallbacks{
				PreflightDelete: func(string) tea.Cmd { return nil },
				InspectDelete:   func(string) tea.Cmd { return nil },
			})
			v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", tc.state)})
			for _, size := range []struct{ width, height int }{{80, 21}, {120, 37}, {160, 42}} {
				v.SetSize(size.width, size.height)
				v.Update(tc.key)
				v.Update(tc.failure)
				assertDashboardDeletionErrorVisible(t, v.View(), size.width, size.height)
				v.Update(tc.key)
				v.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
				if strings.Contains(v.View(), "reason failed") {
					t.Fatal("cancelled retry retained the old error")
				}
				v.Update(tc.key)
				v.Update(tc.success)
				v.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
				if strings.Contains(v.View(), "reason failed") {
					t.Fatal("successful retry retained the old error")
				}
			}
		})
	}
}

func assertDashboardDeletionErrorVisible(t *testing.T, view string, width, height int) {
	t.Helper()
	if !strings.Contains(view, "reason failed") || strings.Contains(view, "\x1b]0;unsafe") {
		t.Fatalf("error not visible or unsafe: %q", view)
	}
	if !strings.Contains(view, "q: quit") {
		t.Fatalf("footer missing after error: %q", view)
	}
	uitest.AssertWithin(t, view, width, height, "dashboard deletion error")
}

func TestDashboardListBoundsLongDeletionErrorWhenListBecomesEmpty(t *testing.T) {
	v := views.NewDashboardList(views.DashboardListCallbacks{PreflightDelete: func(string) tea.Cmd { return nil }})
	v.SetSize(80, 21)
	v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", contracts.DashboardActive)})
	v.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	v.Update(messages.DashboardDeletionPreparedMsg{DashboardID: "a", Err: errors.New("cleanup: " + strings.Repeat("界", 200))})
	v.SetDashboards(nil)
	view := v.View()
	if !strings.Contains(view, "cleanup:") || !strings.Contains(view, "No dashboards") {
		t.Fatalf("error or empty state missing: %q", view)
	}
	uitest.AssertWithin(t, view, 80, 21, "empty dashboard list with long error")
}

func TestDashboardListRequiresForeignDeletionConfirmation(t *testing.T) {
	var preflightID, confirmedID, confirmedToken string
	var confirmedForeign bool
	v := views.NewDashboardList(views.DashboardListCallbacks{
		PreflightDelete: func(id string) tea.Cmd { preflightID = id; return nil },
		ConfirmDelete: func(id, token string, foreign bool) tea.Cmd {
			confirmedID, confirmedToken, confirmedForeign = id, token, foreign
			return nil
		},
	})
	v.SetSize(80, 21)
	v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "Factory A", "", contracts.DashboardActive)})
	v.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	if preflightID != "a" {
		t.Fatalf("preflight ID = %q", preflightID)
	}
	prepared := messages.DashboardDeletionPreparedMsg{
		DashboardID:                 "a",
		Token:                       "token",
		Summary:                     []string{"Owned card: shared"},
		RequiresForeignConfirmation: true,
	}
	v.Update(prepared)
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if confirmedID != "" {
		t.Fatal("foreign impact was confirmed without second prompt")
	}
	v.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	if confirmedID != "" {
		t.Fatal("cancel performed deletion")
	}
	v.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
	v.Update(prepared)
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if confirmedID != "a" || confirmedToken != "token" || !confirmedForeign {
		t.Fatalf("confirmation = %q %q %v", confirmedID, confirmedToken, confirmedForeign)
	}
}

func TestDashboardListFitsAndSanitizesLongContent(t *testing.T) {
	v := views.NewDashboardList(views.DashboardListCallbacks{})
	for _, size := range []struct{ width, height int }{{80, 21}, {120, 37}, {160, 42}} {
		v.SetSize(size.width, size.height)
		row := dashboardSummaryFixture(
			strings.Repeat("id", 200), strings.Repeat("界", 120)+"\x1b[31m",
			strings.Repeat("description ", 80), contracts.DashboardActive,
		)
		v.SetDashboards([]contracts.DashboardSummary{row})
		uitest.AssertWithin(t, v.View(), size.width, size.height, "dashboard list")
		if strings.Contains(v.View(), "\x1b[31m") {
			t.Fatal("dashboard name retained unsafe escape")
		}
	}
}

func TestDashboardListOpensSelectedDashboard(t *testing.T) {
	var opened string
	v := views.NewDashboardList(views.DashboardListCallbacks{
		Open: func(d contracts.DashboardSummary) tea.Cmd { opened = d.ID; return nil },
	})
	v.SetSize(80, 21)
	v.SetDashboards(
		[]contracts.DashboardSummary{
			dashboardSummaryFixture("a", "A", "", contracts.DashboardActive),
			dashboardSummaryFixture("b", "B", "", contracts.DashboardActive),
		},
	)
	v.Update(tea.KeyPressMsg{Code: tea.KeyDown})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if opened != "b" {
		t.Fatalf("opened %q", opened)
	}
}

func TestDashboardListCreatesNamedDashboard(t *testing.T) {
	var savedName, savedDescription string
	v := views.NewDashboardList(views.DashboardListCallbacks{Save: func(_ string, name, description string) tea.Cmd {
		savedName, savedDescription = name, description
		return nil
	}})
	v.SetSize(80, 21)
	v.Update(tea.KeyPressMsg{Text: "n", Code: 'n'})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if savedName != "" || !strings.Contains(v.View(), "name is required") {
		t.Fatal("empty dashboard name was accepted")
	}
	v.Update(tea.KeyPressMsg{Text: "Factory", Code: 'F'})
	v.Update(tea.KeyPressMsg{Code: tea.KeyTab})
	v.Update(tea.KeyPressMsg{Text: "Production", Code: 'P'})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if savedName != "Factory" || savedDescription != "Production" {
		t.Fatalf("saved %q, %q", savedName, savedDescription)
	}
}

func TestDashboardListShowsRetryableDeletionStatus(t *testing.T) {
	for _, key := range []rune{tea.KeyDelete, tea.KeyBackspace} {
		var inspected, retried string
		v := views.NewDashboardList(views.DashboardListCallbacks{
			InspectDelete: func(id string) tea.Cmd { inspected = id; return nil },
			RetryDelete:   func(id string) tea.Cmd { retried = id; return nil },
		})
		v.SetSize(80, 21)
		v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", contracts.DashboardDeleting)})
		v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
		if inspected != "a" {
			t.Fatalf("inspected %q", inspected)
		}
		v.Update(messages.DashboardDeletionStatusMsg{DashboardID: "a", Summary: []string{"Session s: removed=false trust cleanup failed"}})
		if !strings.Contains(v.View(), "trust cleanup failed") {
			t.Fatal("per-item failure not shown")
		}
		v.Update(tea.KeyPressMsg{Code: key})
		if retried != "a" {
			t.Fatalf("retried %q", retried)
		}
	}
}

func TestDashboardListRetriesDeletionWithTheDeleteKey(t *testing.T) {
	for _, key := range []rune{tea.KeyDelete, tea.KeyBackspace} {
		var preflights, retries int
		callbacks := views.DashboardListCallbacks{
			PreflightDelete: func(id string) tea.Cmd {
				if id != "a" {
					t.Fatalf("preflight targeted %q", id)
				}
				preflights++
				return nil
			},
			RetryDelete: func(id string) tea.Cmd {
				if id != "a" {
					t.Fatalf("retry targeted %q", id)
				}
				retries++
				return nil
			},
		}
		v := views.NewDashboardList(callbacks)
		v.SetSize(80, 24)
		v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", contracts.DashboardActive)})
		v.Update(tea.KeyPressMsg{Code: key})
		v.Update(messages.DashboardDeletionPreparedMsg{DashboardID: "a", Err: errors.New("prepare failed")})
		v.Update(tea.KeyPressMsg{Code: key})
		if preflights != 2 {
			t.Fatalf("delete did not retry failed preparation: %d calls", preflights)
		}
		v.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
		v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", contracts.DashboardDeleting)})
		v.Update(tea.KeyPressMsg{Text: "r", Code: 'r'})
		if retries != 0 {
			t.Fatal("obsolete retry binding remains active")
		}
		v.Update(tea.KeyPressMsg{Code: key})
		if retries != 1 || preflights != 2 {
			t.Fatalf("delete did not resume deletion: retries=%d preflights=%d", retries, preflights)
		}
		if !strings.Contains(v.View(), "Delete: retry") || strings.Contains(v.View(), "r: retry") {
			t.Fatal("retry legend does not match the delete action")
		}
	}
}

func TestDashboardDeletionStatusFailureRetainsPreviousProgress(t *testing.T) {
	v := views.NewDashboardList(views.DashboardListCallbacks{InspectDelete: func(string) tea.Cmd { return nil }})
	v.SetSize(80, 21)
	v.SetDashboards([]contracts.DashboardSummary{dashboardSummaryFixture("a", "A", "", contracts.DashboardDeleting)})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	v.Update(messages.DashboardDeletionStatusMsg{DashboardID: "a", Summary: []string{"retained checkpoint"}})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	v.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	v.Update(messages.DashboardDeletionStatusMsg{DashboardID: "a", Err: errors.New("read failed")})
	if rendered := v.View(); !strings.Contains(rendered, "retained checkpoint") || !strings.Contains(rendered, "read failed") {
		t.Fatalf("status lost: %s", rendered)
	}
}

func TestDeletionResultRetryRequiresKnownPendingIntent(t *testing.T) {
	for _, allow := range []bool{false, true} {
		var retried bool
		v := views.NewDashboardList(views.DashboardListCallbacks{RetryDelete: func(string) tea.Cmd { retried = true; return nil }})
		v.SetSize(80, 21)
		v.ShowDeletionResult("d", []string{"outcome"}, allow)
		v.Update(tea.KeyPressMsg{Code: tea.KeyDelete})
		if retried != allow {
			t.Fatalf("allow=%t retried=%t", allow, retried)
		}
	}
}

internal/ui/views/dashboard_test.go.source:
package views_test

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api/contracts"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

var errTest = errors.New("test")

type dashboardFixture struct {
	Cards    []config.IDCard
	Sessions []session.Snapshot
	Skills   []config.Skill
	Personas []config.Persona
	Puppets  []config.Puppet
}

//nolint:gocognit // Test-only adapter converts existing backend fixtures to focused display contracts.
func setDashboardData(dashboard *views.Dashboard, msg dashboardFixture) {
	currentCards := dashboard.Cards()
	cards := make([]contracts.CardSummary, 0, len(currentCards))
	for _, card := range currentCards {
		cards = append(cards, contracts.CardSummary{
			ID: card.ID, OwnerDashboardID: card.OwnerDashboardID, Shared: card.Shared,
			Name: card.Name, Driver: card.Driver, Model: card.Model, SkillIDs: card.SkillIDs,
			PersonaIDs: card.PersonaIDs, Puppet: card.PuppetName, FaceStyle: card.FaceStyle,
			DeletionState: card.DeletionState, Launch: card.Launch, Edit: card.Edit, Delete: card.Delete,
			Retry: card.Retry, Inspect: card.Inspect,
		})
	}
	currentSessions := dashboard.SessionList().Sessions()
	sessions := make([]contracts.SessionSummary, 0, len(currentSessions))
	for _, row := range currentSessions {
		sessions = append(sessions, contracts.SessionSummary{
			ID: row.ID, DashboardID: row.DashboardID, CardID: row.CardID, Name: row.Name,
			Status: row.Status, StartedAt: row.StartedAt, PID: row.PID, WorkingDir: row.WorkingDir,
			OriginalDir: row.OriginalDir, TemporaryWorkspace: row.TemporaryWorkspace,
			CardDeleted: row.CardDeleted, CardUnavailable: row.CardUnavailable,
			Registration: row.Registration, RegistrationPersistence: row.RegistrationPersistence,
			RegistrationError: row.RegistrationError, ActiveConversationID: row.ActiveConversationID,
			ActiveConversationName: row.ActiveConversationName, FaceStyle: row.FaceStyle, Puppet: row.PuppetName,
			Attach: row.Attach, Relaunch: row.Relaunch, Stop: row.Stop, Remove: row.Remove,
			Switch: row.Switch, Rename: row.Rename, OpenIDE: row.OpenIDE, OpenTerminal: row.OpenTerminal,
		})
	}
	read := contracts.ReadResult[contracts.DashboardInventory]{}
	if msg.Cards != nil || msg.Sessions != nil {
		read.Attempted = true
		if msg.Cards != nil {
			cards = make([]contracts.CardSummary, 0, len(msg.Cards))
			for _, card := range msg.Cards {
				cards = append(cards, contracts.CardSummary{
					ID: card.ID, OwnerDashboardID: card.DashboardID, Shared: card.Shared,
					Name: card.Name, Driver: card.Driver, Model: card.Model, SkillIDs: card.SkillIDs,
					PersonaIDs: card.PersonaIDs, Puppet: card.Puppet, FaceStyle: card.FaceStyle,
					DeletionState: card.DeletionState, Launch: contracts.Availability{Enabled: card.DeletionState == ""},
					Inspect: contracts.Availability{Enabled: true}, Edit: contracts.Availability{Enabled: card.DeletionState == ""},
					Delete: contracts.Availability{Enabled: card.DeletionState == ""},
				})
			}
		}
		if msg.Sessions != nil {
			sessions = make([]contracts.SessionSummary, 0, len(msg.Sessions))
			for _, item := range msg.Sessions {
				status := item.Status
				if status == "" {
					status = session.StatusTerminated
				}
				row := contracts.SessionSummary{
					ID: item.ID, DashboardID: item.DashboardID, CardID: item.CardID, Name: item.Name,
					Status: string(status), StartedAt: item.StartedAt, PID: item.PID,
					WorkingDir: item.WorkingDir, OriginalDir: item.OriginalDir,
					TemporaryWorkspace: item.UseTmpWorkspace, CardDeleted: item.CardDeleted,
					Registration: string(item.Registration), RegistrationPersistence: string(item.RegistrationPersistence),
					RegistrationError: item.RegistrationErr, ActiveConversationID: item.ActiveConversationID,
				}
				enabled := contracts.Availability{Enabled: true}
				unavailable := contracts.Availability{Reason: "unavailable in fixture"}
				switch status {
				case session.StatusRunning, session.StatusWaiting:
					row.Attach, row.Stop, row.Rename, row.OpenIDE, row.OpenTerminal = enabled, enabled, enabled, enabled, enabled
					row.Remove, row.Relaunch, row.Switch = unavailable, unavailable, unavailable
				case session.StatusTerminated:
					row.Remove, row.Relaunch, row.Switch, row.Rename = enabled, enabled, enabled, enabled
					row.OpenIDE, row.OpenTerminal = enabled, enabled
					row.Attach, row.Stop = unavailable, unavailable
				}
				sessions = append(sessions, row)
			}
		}
		read.Value = contracts.DashboardInventory{Cards: cards, Sessions: sessions}
	}
	choices := contracts.DisplayChoicesResult{}
	if msg.Skills != nil {
		choices.Skills = contracts.ReadResult[[]contracts.NamedChoice]{
			Attempted: true,
			Value:     make([]contracts.NamedChoice, 0, len(msg.Skills)),
		}
		for _, item := range msg.Skills {
			choices.Skills.Value = append(choices.Skills.Value, contracts.NamedChoice{ID: item.ID, Name: item.Name})
		}
	}
	if msg.Personas != nil {
		choices.Personas = contracts.ReadResult[[]contracts.NamedChoice]{
			Attempted: true,
			Value:     make([]contracts.NamedChoice, 0, len(msg.Personas)),
		}
		for _, item := range msg.Personas {
			choices.Personas.Value = append(choices.Personas.Value, contracts.NamedChoice{ID: item.ID, Name: item.Name})
		}
	}
	if msg.Puppets != nil {
		choices.Puppets = contracts.ReadResult[[]contracts.PuppetChoice]{
			Attempted: true,
			Value:     make([]contracts.PuppetChoice, 0, len(msg.Puppets)),
		}
		for _, item := range msg.Puppets {
			choices.Puppets.Value = append(choices.Puppets.Value, contracts.PuppetChoice{
				ID: item.ID, Name: item.Name, Lines: item.Lines, Builtin: item.Builtin,
			})
		}
	}
	dashboard.SetInventory(read, choices)
}

