		t.Fatalf("rename submitted (%q, %q), want captured target and trimmed Unicode draft", gotID, gotName)
	}
	d.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if submissions != 1 {
		t.Fatalf("pending rename submitted %d times", submissions)
