//go:build e2e

package e2e_test

import (
	"io/fs"
	"os"
	"path/filepath"
	"testing"
)

// isolatedAgentEnvironment copies only configuration, credentials and model
// preferences, never historical conversations or a running server's state.
func isolatedAgentEnvironment(t *testing.T, sandbox, agent string) map[string]string {
	t.Helper()
	originalHome, err := os.UserHomeDir()
	must(t, err)
	home := filepath.Join(sandbox, "home")
	configHome := filepath.Join(home, ".config")
	dataHome := filepath.Join(home, ".local/share")
	stateHome := filepath.Join(home, ".local/state")
	for _, dir := range []string{home, configHome, dataHome, stateHome} {
		must(t, os.MkdirAll(dir, 0o700))
	}
	originalConfig := os.Getenv("XDG_CONFIG_HOME")
	if originalConfig == "" {
		originalConfig = filepath.Join(originalHome, ".config")
	}
	originalData := os.Getenv("XDG_DATA_HOME")
	if originalData == "" {
		originalData = filepath.Join(originalHome, ".local/share")
	}
	originalState := os.Getenv("XDG_STATE_HOME")
	if originalState == "" {
		originalState = filepath.Join(originalHome, ".local/state")
	}
	environment := map[string]string{
		"HOME": home, "XDG_CONFIG_HOME": configHome, "XDG_DATA_HOME": dataHome,
		"XDG_STATE_HOME": stateHome, "XDG_CACHE_HOME": filepath.Join(home, ".cache"),
		"TERM": "xterm-256color", "COLORTERM": "truecolor",
	}
	switch agent {
	case "opencode":
		copyOpenCodeConfiguration(t, filepath.Join(originalConfig, "opencode"), filepath.Join(configHome, "opencode"))
		copyConfiguration(t, filepath.Join(originalData, "opencode/auth.json"), filepath.Join(dataHome, "opencode/auth.json"))
		copyConfiguration(t, filepath.Join(originalState, "opencode/model.json"), filepath.Join(stateHome, "opencode/model.json"))
		copyConfiguration(t, filepath.Join(originalState, "opencode/kv.json"), filepath.Join(stateHome, "opencode/kv.json"))
		if _, statErr := os.Stat(filepath.Join(originalData, "opencode/opencode.db")); statErr == nil {
			copyOpenCodeCredentials(t, environment)
		} else if !os.IsNotExist(statErr) {
			t.Fatal(statErr)
		}
	case "codex":
		source := os.Getenv("CODEX_HOME")
		if source == "" {
			source = filepath.Join(originalHome, ".codex")
		}
		destination := filepath.Join(home, ".codex")
		for _, name := range []string{"config.toml", "auth.json", "instructions.md", "rules"} {
			copyConfiguration(t, filepath.Join(source, name), filepath.Join(destination, name))
		}
		environment["CODEX_HOME"] = destination
	case "claude":
		copyConfiguration(t, filepath.Join(originalHome, ".claude.json"), filepath.Join(home, ".claude.json"))
		for _, name := range []string{"settings.json", "settings.local.json", ".credentials.json"} {
			copyConfiguration(t, filepath.Join(originalHome, ".claude", name), filepath.Join(home, ".claude", name))
		}
		environment["CLAUDE_CONFIG_DIR"] = filepath.Join(home, ".claude")
	}
	return environment
}

func copyConfiguration(t *testing.T, source, destination string) {
	t.Helper()
	info, err := os.Stat(source)
	if os.IsNotExist(err) {
		return
	}
	must(t, err)
	if !info.IsDir() {
		copyConfigurationFile(t, source, destination)
		return
	}
	must(t, filepath.WalkDir(source, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		relative, relativeErr := filepath.Rel(source, path)
		if relativeErr != nil {
			return relativeErr
		}
		target := filepath.Join(destination, relative)
		if entry.IsDir() {
			return os.MkdirAll(target, 0o700)
		}
		if entry.Type().IsRegular() {
			copyConfigurationFile(t, path, target)
		}
		return nil
	}))
}

func copyConfigurationFile(t *testing.T, source, destination string) {
	t.Helper()
	bytes, err := os.ReadFile(source)
	must(t, err)
	must(t, os.MkdirAll(filepath.Dir(destination), 0o700))
	must(t, os.WriteFile(destination, bytes, 0o600))
}

tests/e2e/launch_focus_test.go.source:
//go:build e2e

package e2e_test

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	tuitest "github.com/microsoft/tui-test/bindings/go"
	"github.com/microsoft/tui-test/bindings/go/tuitesttest"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/session"
)

// TestNativeLaunchFocusReturn starts an interactive agent but never submits a
// prompt. Enter after detach must attach to the created session, not launch a
// second session from the card or relaunch the older session.
func TestNativeLaunchFocusReturn(t *testing.T) {
	j := newLaunchFocusJourney(t, "")
	runLaunchFocus(j)
	j.finish()
}

func runLaunchFocus(j *nativeJourney) session.Data {
	t := j.t
	j.run.Stage = "launch"
	j.expect("Dashboards")
	j.press("Enter")
	j.expect("Focus E2E")
	j.press("Enter")
	j.expect("Session launched successfully!")
	created := waitSession(t, j.configDir, 30*time.Second, func(data session.Data) bool {
		return data.ID != "older-session" && data.CardID == j.card.ID && data.PID > 0
	})
	// Type only into Kankuro's naming form, before the agent terminal is attached.
	must(t, j.terminal.Type("Created focus session"))
	j.press("Enter")
	expectIdleCodex(t, j.terminal)
	j.capture("attached", "The real Codex input screen is visible after card launch and name confirmation; no agent prompt was entered.")

	j.run.Stage = "detach"
	j.press("Ctrl+K")
	j.expect("Active Sessions")
	j.expect("[Session] Enter=Attach")
	j.expect("Created focus session")
	j.expect("Older session")
	j.expect("Started:")
	j.expect("Card: Focus E2E")
	state, err := j.terminal.State()
	must(t, err)
	if state.Cols != 120 || state.Rows != 40 {
		t.Fatalf("dashboard terminal size = %dx%d, want 120x40", state.Cols, state.Rows)
	}
	j.capture("dashboard", "Ctrl+K restores the dashboard with both sessions, action hints and the selected session header.")

	// Check keyboard restoration without changing the sessions selection.
	j.press("c")
	j.expect("Settings")
	j.press("Escape")
	j.expect("[Session] Enter=Attach")
	j.run.Stage = "reattach"
	j.press("Enter")
	expectIdleCodex(t, j.terminal)
	assertLaunchFocusSessions(t, j.configDir, created)
	j.capture(
		"reattached",
		"Enter without pane navigation reattaches to the same live process; exactly two persisted sessions remain and the older session stays terminated.",
	)
	return created
}

func newLaunchFocusJourney(t *testing.T, workspaceMode string) *nativeJourney {
	t.Helper()
	if _, err := exec.LookPath("codex"); err != nil {
		t.Skip("startup-only launch-focus test requires Codex on PATH")
	}
	if os.Getenv("TUI_TEST_RECORDING_FONT_FAMILIES") == "" {
		t.Setenv("TUI_TEST_RECORDING_FONT_FAMILIES", "DejaVu Sans Mono,DejaVu Sans")
	}
	verifyNativeCapture(t)
	root, err := filepath.Abs("../..")
	must(t, err)
	artifacts := filepath.Join(root, "tests/e2e/artifacts/launch-focus")
	if override := os.Getenv("KANKURO_E2E_ARTIFACT_DIR"); override != "" {
		artifacts, err = filepath.Abs(override)
		must(t, err)
	}
	if workspaceMode != "" {
		artifacts = filepath.Join(artifacts, workspaceMode)
	}
	must(t, os.MkdirAll(artifacts, 0o700))
	for _, name := range []string{"attached.png", "dashboard.png", "reattached.png", "failure.png", "result.json", "workspace-initial.png", "workspace-updated.png", "supported-minimum.png", "minimum-size.png", "stopped.png", "relaunched.png", "report-after-relaunch.png", "restart-report.png"} {
		if removeErr := os.Remove(filepath.Join(artifacts, name)); removeErr != nil && !os.IsNotExist(removeErr) {
			t.Fatal(removeErr)
		}
	}
	run := &journeyRun{
		Agent: "codex", Revision: "WORKTREE", Fingerprint: sourceFingerprint(t, root),
		Command:   "go test -tags=e2e ./tests/e2e -run '^TestNativeLaunchFocusReturn$' -count=1 -timeout=3m -v",
		StartedAt: time.Now().UTC(), Size: [2]int{120, 40}, Stage: "setup",
	}
	if workspaceMode != "" {
		run.Command = "go test -tags=e2e ./tests/e2e -run '^TestCodexOfflineWorkspaceAndReports$/" + workspaceMode + "$' -count=1 -timeout=3m -v"
	}
	t.Cleanup(func() {
		if sourceFingerprint(t, root) != run.Fingerprint {
			t.Error("source changed during launch-focus E2E run")
		}
		writeJourneyRun(t, run, artifacts)
	})

	sandbox := t.TempDir()
	environment := startupOnlyCodexEnvironment(t, sandbox)
	// Recent Codex versions start a daemon outside the CLI's process group.
	// Stop only the daemon in this disposable home before removing its files.
	t.Cleanup(func() {
		defer stopCodexUpdater(t, environment["CODEX_HOME"])
		ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer cancel()
		stop := exec.CommandContext(ctx, "codex", "app-server", "daemon", "stop")
		stop.Env = os.Environ()
		for key, value := range environment {
			stop.Env = append(stop.Env, key+"="+value)
		}
		if output, stopErr := stop.CombinedOutput(); stopErr != nil {
			t.Errorf("stop isolated Codex daemon: %v\n%s", stopErr, output)
		}
	})
	workspace := filepath.Join(sandbox, "workspace")
	must(t, os.MkdirAll(workspace, 0o700))
	if workspaceMode == "git" {
		git := exec.Command("git", "init", "-q")
		git.Dir = workspace
		must(t, git.Run())
		must(t, os.WriteFile(filepath.Join(workspace, ".git/info/exclude"), []byte(".kankuro/\n.agents/\nAGENTS.md\n"), 0600))
	}
	configDir := filepath.Join(sandbox, "config")
	must(t, os.MkdirAll(configDir, 0o700))
	must(t, configstartup.PrepareStartup(configDir))
	repo, err := config.NewFileRepository(configDir)
	must(t, err)
	must(t, repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}))
	workspaces, err := repo.ListWorkspaces()
	must(t, err)
	if len(workspaces) != 1 {
		t.Fatalf("workspace registry = %+v", workspaces)
	}
	card, err := repo.CreateIDCard(config.IDCard{
		DashboardID: "default", Name: "Focus E2E", Driver: "codex", WorkspaceID: workspaces[0].ID, Puppet: "kankuro",
	})
	must(t, err)
	older := session.Data{
		SchemaVersion: 2, ID: "older-session", DashboardID: "default", CardID: card.ID,
		Name: "Older session", WorkingDir: workspace, OriginalDir: workspace,
		Status: session.StatusTerminated, StartedAt: time.Unix(1, 0),
	}
	data, err := json.Marshal(older)
	must(t, err)
	must(t, os.MkdirAll(filepath.Join(configDir, "sessions"), 0o700))
	must(t, os.WriteFile(filepath.Join(configDir, "sessions/older-session.json"), data, 0o600))
	if workspaceMode != "" {
		seedOfflineReport(t, configDir, older.ID)
	}
	binary := filepath.Join(sandbox, "kankuro")
	buildCtx, cancel := context.WithTimeout(t.Context(), 2*time.Minute)
	defer cancel()
	build := exec.CommandContext(buildCtx, "go", "build", "-o", binary, ".")
	build.Dir = root
	if output, buildErr := build.CombinedOutput(); buildErr != nil {
		t.Fatalf("build Kankuro: %v\n%s", buildErr, output)
	}
	environment["KANKURO_CONFIG_DIR"] = configDir
	environment["KANKURO_TMP_DIR"] = filepath.Join(sandbox, "tmp")
	terminal := tuitesttest.New(t, tuitesttest.Options{
		Program: binary, Prefix: "kankuro-launch-focus",
		Client: tuitest.ClientOptions{Recording: &tuitest.AutomaticRecording{Mode: tuitest.RecordingDisabled}},
		Spawn: tuitest.SpawnOptions{
			Cols: new(uint16(120)), Rows: new(uint16(40)), Cwd: workspace,
			Env: environment, WaitReady: new(false),
		},
	})
	registerTerminalCleanup(t, terminal, run, artifacts)
	return &nativeJourney{t: t, root: root, agent: nativeAgent{name: "codex"},
		artifacts: artifacts, configDir: configDir, card: card, terminal: terminal, run: run}
}

// The daemon stop command leaves its updater running in some Codex versions.
// Match both the private executable path and exact subcommand; never stop an
// updater belonging to the user's real home or another test.
func stopCodexUpdater(t *testing.T, codexHome string) {
	t.Helper()
	output, err := exec.Command("ps", "-eo", "pid=,args=").Output()
	must(t, err)
	for line := range strings.SplitSeq(string(output), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 5 || !strings.HasPrefix(fields[1], codexHome+string(os.PathSeparator)) ||
			fields[2] != "app-server" || fields[3] != "daemon" || fields[4] != "pid-update-loop" {
			continue
		}
		pid, parseErr := strconv.Atoi(fields[0])
		must(t, parseErr)
		process, findErr := os.FindProcess(pid)
		must(t, findErr)
		if killErr := process.Kill(); killErr != nil && !errors.Is(killErr, os.ErrProcessDone) && !os.IsNotExist(killErr) {
			t.Errorf("stop isolated Codex updater: %v", killErr)
		}
	}
}

// Use a synthetic key and an unreachable loopback provider for idle Codex tests.
func startupOnlyCodexEnvironment(t *testing.T, sandbox string) map[string]string {
	t.Helper()
	home := filepath.Join(sandbox, "home")
	codexHome := filepath.Join(home, ".codex")
	must(t, os.MkdirAll(codexHome, 0o700))
	const endpoint = "http://127.0.0.1:1"
	const fixtureKey = "appediff-offline-fixture"
	must(t, os.WriteFile(filepath.Join(codexHome, "auth.json"), []byte(`{"OPENAI_API_KEY":"`+fixtureKey+`"}`), 0600))
	settings := "check_for_update_on_startup = false\nmodel = \"gpt-6-sol\"\nopenai_base_url = \"" + endpoint + "/v1\"\n"
	must(t, os.WriteFile(filepath.Join(codexHome, "config.toml"), []byte(settings), 0600))
	return map[string]string{
		"HOME": home, "CODEX_HOME": codexHome, "XDG_CONFIG_HOME": filepath.Join(home, ".config"),
		"XDG_DATA_HOME": filepath.Join(home, ".local/share"), "XDG_STATE_HOME": filepath.Join(home, ".local/state"),
		"XDG_CACHE_HOME": filepath.Join(home, ".cache"), "TERM": "xterm-256color", "COLORTERM": "truecolor",
		"NO_COLOR": "", "CLICOLOR_FORCE": "1",
		"OPENAI_API_KEY": fixtureKey, "OPENAI_BASE_URL": endpoint + "/v1",
		"HTTP_PROXY": endpoint, "HTTPS_PROXY": endpoint, "ALL_PROXY": endpoint, "NO_PROXY": "localhost,127.0.0.1",
	}
}

func expectIdleCodex(t *testing.T, terminal *tuitest.Client) {
	t.Helper()
	timeout := 45 * time.Second
	for _, text := range []string{"Active Sessions", "Session launched successfully!"} {
		must(t, terminal.GetByText(text, tuitest.TextSelectorOptions{}).
			Wait(tuitest.LocatorWaitOptions{State: tuitest.Hidden, Timeout: &timeout}))
	}
	expectWithTimeout(t, terminal, "OpenAI Codex", 45*time.Second)
	expectWithTimeout(t, terminal, "Ask Codex to do anything", 45*time.Second)
	// The empty input exists during the splash too; wait for model metadata so
	// captures show the ready native UI rather than its transient loading frame.
	must(t, terminal.GetByText("(?i)GPT-|model:", tuitest.TextSelectorOptions{Regex: true}).
		First().Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}))
	checkAgentFailure(t, terminal)
}

func assertLaunchFocusSessions(t *testing.T, configDir string, created session.Data) {
	t.Helper()
	paths, err := filepath.Glob(filepath.Join(configDir, "sessions/*.json"))
	must(t, err)
	if len(paths) != 2 {
		t.Fatalf("session count = %d, want older session and exactly one created session", len(paths))
	}
	for _, path := range paths {
		data, readErr := os.ReadFile(path)
		must(t, readErr)
		var current session.Data
		must(t, json.Unmarshal(data, &current))
		if current.ID == created.ID {
			if current.PID != created.PID || current.Name != "Created focus session" || current.Status == session.StatusTerminated {
				t.Fatalf("created session identity or activation changed: %+v", current)
			}
		} else if current.ID != "older-session" || current.PID != 0 || current.Status != session.StatusTerminated {
			t.Fatalf("Enter selected or relaunched the wrong session: %+v", current)
		}
	}
}

tests/e2e/mcp_manager_test.go.source:
//go:build e2e

package e2e_test

import (
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	tuitest "github.com/microsoft/tui-test/bindings/go"
	"github.com/microsoft/tui-test/bindings/go/tuitesttest"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
)

const mcpJourneyCommand = "go test -tags=e2e ./tests/e2e -run '^TestMCPManagerJourney$' -count=1 -timeout=3m -v"

// TestMCPManagerJourney drives the real configuration screens without launching
// an agent or connecting to a model provider. Captures are checkpoints, not
// pixel-baseline comparisons.
func TestMCPManagerJourney(t *testing.T) {
	j := newMCPJourney(t)
	j.expect("Dashboards")
	j.press("Enter")
	j.expect("Active Sessions")
	j.press("m")
	j.expect("MCP Servers")
	j.expect("kankuro (built-in, read-only)")
	j.expect("[ New MCP ]")
	j.capture("list", "Only the protected built-in and New are initially available.")

	j.press("Down")
	j.expect("> [ New MCP ]")
	j.press("Enter")
	j.expect("MCP Server Configuration")
	j.absent("Alpha MCP")
	j.capture("new", "New opens a blank MCP form with save/back instructions.")
	must(t, j.terminal.Type("Alpha MCP"))
	j.press("Tab")
	must(t, j.terminal.Type("mcp-placeholder"))
	j.press("Enter")
	j.expect("MCP Servers")
	j.expect("Alpha MCP")
	created := j.customServer()
	if created.Name != "Alpha MCP" || created.Command != "mcp-placeholder" || created.ID == "" {
		t.Fatalf("create did not persist form values: %+v", created)
	}

	// The New row stays selected after the registry refresh; return to Alpha.
	j.press("Up")
	j.press("Up")
	j.press("Enter")
	j.expect("MCP Server Configuration")
	j.expect("Alpha MCP")
	j.expect("mcp-placeholder")
	j.capture("edit", "Existing entry loads its name and command in the editor.")
	j.press("Ctrl+A")
	j.press("Ctrl+K")
	must(t, j.terminal.Type("Beta MCP"))
	j.press("Enter")
	j.expect("MCP Servers")
	j.expect("Beta MCP")
	j.absent("Alpha MCP")
	updated := j.customServer()
	if updated.ID != created.ID || updated.Name != "Beta MCP" || updated.Command != created.Command {
		t.Fatalf("edit changed identity or lost unedited command: %+v", updated)
	}
	j.resize(80, 24)
	j.expect("MCP Servers")
	j.capture("edited-list", "At 80×24 the renamed server, protected built-in, New and help are visible.")

	j.press("Delete")
	j.expect("Delete MCP?")
	j.expect("Delete Beta MCP?")
	j.capture("confirm", "Delete opens a named confirmation with confirm/cancel instructions at 80×24.")
	if got := j.customServer(); got.ID != created.ID {
		t.Fatal("opening confirmation mutated the registry")
	}
	j.press("Escape")
	j.expect("MCP Servers")
	j.expect("Beta MCP")
	if got := j.customServer(); got.ID != created.ID {
		t.Fatal("canceling confirmation removed the server")
	}
	j.press("Delete")
	j.expect("Delete Beta MCP?")
	j.press("Enter")
	j.expect("MCP Servers")
	j.absent("Beta MCP")
	servers, err := j.repo.ListMCPs()
	must(t, err)
	if len(servers) != 1 || servers[0].ID != config.BuiltinMCPKankuro {
		t.Fatalf("confirmed deletion did not preserve exactly the built-in: %+v", servers)
	}
	j.capture("deleted", "Confirmed deletion removes the custom definition and retains built-in/New at 80×24.")
	j.press("Escape")
	j.expect("Active Sessions")
	j.press("m")
	j.expect("MCP Servers")
	j.absent("Beta MCP")
	j.press("Escape")
	j.expect("Active Sessions")
	j.press("q")
	timeout := 10 * time.Second
	must(t, j.terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}))
	assertNativeExit(t, j.terminal)
}

type mcpJourney struct {
	t         *testing.T
	terminal  *tuitest.Client
	repo      *config.FileRepository
	artifacts string
	run       *mcpJourneyRun
	size      [2]int
}

type mcpJourneyRun struct {
	Command     string       `json:"command"`
	Revision    string       `json:"revision"`
	Fingerprint string       `json:"fingerprint"`
	StartedAt   time.Time    `json:"startedAt"`
	FinishedAt  time.Time    `json:"finishedAt"`
	Status      string       `json:"status"`
	Captures    []mcpCapture `json:"captures"`
}

type mcpCapture struct {
	File      string    `json:"file"`
	Size      [2]int    `json:"size"`
	Assertion string    `json:"assertion"`
	At        time.Time `json:"at"`
}

func newMCPJourney(t *testing.T) *mcpJourney {
	t.Helper()
	root, err := filepath.Abs("../..")
	must(t, err)
	sandbox := t.TempDir()
	configDir := filepath.Join(sandbox, "config")
	must(t, os.MkdirAll(configDir, 0o700))
	must(t, configstartup.PrepareStartup(configDir))
	repo, err := config.NewFileRepository(configDir)
	must(t, err)
	artifacts := filepath.Join(root, "tests/e2e/artifacts/mcp-manager")
	if override := os.Getenv("KANKURO_MCP_E2E_ARTIFACT_DIR"); override != "" {
		artifacts, err = filepath.Abs(override)
		must(t, err)
	}
	must(t, os.MkdirAll(artifacts, 0o700))
	for _, name := range []string{"list.png", "new.png", "edit.png", "edited-list.png", "confirm.png", "deleted.png", "failure.png", "result.json"} {
		if removeErr := os.Remove(filepath.Join(artifacts, name)); removeErr != nil && !os.IsNotExist(removeErr) {
			t.Fatal(removeErr)
		}
	}
	run := &mcpJourneyRun{
		Command:     mcpJourneyCommand,
		Revision:    "WORKTREE",
		Fingerprint: sourceFingerprint(t, root),
		StartedAt:   time.Now().UTC(),
	}
	t.Cleanup(func() { finishMCPJourney(t, root, artifacts, run) })
	binary := filepath.Join(sandbox, "kankuro")
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	build := exec.CommandContext(ctx, "go", "build", "-o", binary, ".")
	build.Dir = root
	if output, buildErr := build.CombinedOutput(); buildErr != nil {
		t.Fatalf("build Kankuro: %v\n%s", buildErr, output)
	}
	// No native-agent config, conversations, credentials or user files are copied.
	env := map[string]string{
		"HOME": sandbox, "XDG_CONFIG_HOME": filepath.Join(sandbox, "xdg-config"),
		"XDG_DATA_HOME": filepath.Join(sandbox, "xdg-data"), "XDG_STATE_HOME": filepath.Join(sandbox, "xdg-state"),
		"XDG_CACHE_HOME": filepath.Join(sandbox, "xdg-cache"), "KANKURO_CONFIG_DIR": configDir,
		"KANKURO_TMP_DIR": filepath.Join(sandbox, "tmp"), "TERM": "xterm-256color", "COLORTERM": "truecolor",
	}
	terminal := tuitesttest.New(t, tuitesttest.Options{
		Prefix: "kankuro-mcp-manager", Program: binary,
		Client: tuitest.ClientOptions{Recording: &tuitest.AutomaticRecording{Mode: tuitest.RecordingDisabled}},
		Spawn:  tuitest.SpawnOptions{Cols: new(uint16(120)), Rows: new(uint16(40)), Cwd: sandbox, Env: env, WaitReady: new(false)},
	})
	j := &mcpJourney{t: t, terminal: terminal, repo: repo, artifacts: artifacts, run: run, size: [2]int{120, 40}}
	t.Cleanup(func() {
		if !t.Failed() {
			return
		}
		if _, captureErr := terminal.Screenshot(filepath.Join(artifacts, "failure.png"), tuitest.ScreenshotOptions{}); captureErr != nil {
			t.Logf("failure screenshot: %v", captureErr)
		}
		if text, textErr := terminal.Text(tuitest.TextOptions{}); textErr == nil {
			t.Logf("MCP journey terminal:\n%s", text)
		}
		if signalErr := terminal.Signal("SIGTERM"); signalErr != nil {
			t.Logf("shutdown signal: %v", signalErr)
		}
	})
	return j
}

func (j *mcpJourney) press(key string) {
	j.t.Helper()
	must(j.t, j.terminal.Press(key))
}

func (j *mcpJourney) expect(text string) {
	j.t.Helper()
	expectWithTimeout(j.t, j.terminal, text, 10*time.Second)
}

func (j *mcpJourney) absent(text string) {
	j.t.Helper()
	timeout := 10 * time.Second
	must(j.t, j.terminal.GetByText(text, tuitest.TextSelectorOptions{}).Expect(tuitest.LocatorExpectOptions{Not: true, Timeout: &timeout}))
}

func (j *mcpJourney) resize(cols, rows uint16) {
	j.t.Helper()
	must(j.t, j.terminal.Resize(cols, rows))
	j.size = [2]int{int(cols), int(rows)}
}

func (j *mcpJourney) capture(name, assertion string) {
	j.t.Helper()
	// Assert instructions as well as the main state before capturing the frame.
	switch name {
	case "confirm":
		j.expect("Enter/y=confirm")
	case "new", "edit":
		j.expect("Enter: Save")
	default:
		j.expect("Del=delete")
		j.expect("[ New MCP ]")
	}
	_, err := j.terminal.Screenshot(filepath.Join(j.artifacts, name+".png"), tuitest.ScreenshotOptions{})
	must(j.t, err)
	j.run.Captures = append(j.run.Captures, mcpCapture{File: name + ".png", Size: j.size, Assertion: assertion, At: time.Now().UTC()})
}

func (j *mcpJourney) customServer() config.MCPServer {
	j.t.Helper()
	servers, err := j.repo.ListMCPs()
	must(j.t, err)
	for _, server := range servers {
		if server.ID != config.BuiltinMCPKankuro && strings.HasSuffix(server.Name, "MCP") {
			return server
		}
	}
	j.t.Fatal("custom MCP definition not persisted")
	return config.MCPServer{}
}

func finishMCPJourney(t *testing.T, root, artifacts string, run *mcpJourneyRun) {
	t.Helper()
	if sourceFingerprint(t, root) != run.Fingerprint {
		t.Error("source changed during MCP journey")
	}
	run.FinishedAt, run.Status = time.Now().UTC(), "passed"
	if t.Failed() {
		run.Status = "failed"
	}
	data, marshalErr := json.MarshalIndent(run, "", "  ")
	if marshalErr != nil {
		t.Error(marshalErr)
		return
	}
	if writeErr := os.WriteFile(filepath.Join(artifacts, "result.json"), append(data, '\n'), 0o600); writeErr != nil {
		t.Error(writeErr)
	}
}

tests/e2e/native_agent_test.go.source:
//go:build e2e

package e2e_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	tuitest "github.com/microsoft/tui-test/bindings/go"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
)

type nativeJourney struct {
	t         *testing.T
	root      string
	agent     nativeAgent
	artifacts string
	configDir string
	card      config.IDCard
	terminal  *tuitest.Client
	run       *journeyRun
}

func newJourneyRun(t *testing.T, root string, agent nativeAgent) (*journeyRun, string) {
	t.Helper()
	artifacts := filepath.Join(root, "tests/e2e/artifacts/native-agent")
	if override := os.Getenv("KANKURO_E2E_ARTIFACT_DIR"); override != "" {
		resolved, pathErr := filepath.Abs(override)
		must(t, pathErr)
		artifacts = resolved
	}
	// Only remove this test's known artifacts; never clear an arbitrary supplied directory.
	must(t, os.MkdirAll(artifacts, 0o700))
	for _, name := range []string{"launched.png", "dashboard.png", "workspace-before-report.png", "live-report.png", "conversation-choice.png", "resume-ready.png", "resumed.png", "failure.png", "result.json"} {
		if removeErr := os.Remove(filepath.Join(artifacts, name)); removeErr != nil && !os.IsNotExist(removeErr) {
			t.Fatal(removeErr)
		}
	}
	run := &journeyRun{
		Agent: agent.name, Command: "./tests/e2e/run token-usage",
		Fingerprint: sourceFingerprint(t, root), Revision: "WORKTREE",
		StartedAt: time.Now().UTC(), Size: [2]int{120, 40}, Stage: "setup",
	}
	t.Cleanup(func() {
		if after := sourceFingerprint(t, root); after != run.Fingerprint {
			t.Error("source changed during native E2E run")
		}
		writeJourneyRun(t, run, artifacts)
	})
	return run, artifacts
}

func writeJourneyRun(t *testing.T, run *journeyRun, artifacts string) {
	t.Helper()
	run.FinishedAt = time.Now().UTC()
	if t.Failed() {
		run.Status = "failed"
	} else if run.Status == "" {
		run.Status = "passed"
	}
	data, err := json.MarshalIndent(run, "", "  ")
	if err != nil {
		t.Errorf("encode run: %v", err)
		return
	}
	if writeErr := os.WriteFile(filepath.Join(artifacts, "result.json"), append(data, '\n'), 0o600); writeErr != nil {
		t.Errorf("record run: %v", writeErr)
	}
}

func registerTerminalCleanup(t *testing.T, terminal *tuitest.Client, run *journeyRun, artifacts string) {
	t.Helper()
	// Give Kankuro time to stop its managed process before the terminal closes.
	t.Cleanup(func() {
		if t.Failed() {
			if signalErr := terminal.Signal("SIGTERM"); signalErr != nil {
				t.Logf("signal Kankuro: %v", signalErr)
				return
			}
			timeout := 15 * time.Second
			if exitErr := terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}); exitErr != nil {
				t.Errorf("Kankuro shutdown: %v", exitErr)
			}
		}
	})
	// Registered after terminal cleanup, so failure capture happens before closure.
	t.Cleanup(func() {
		if t.Failed() {
			if _, captureErr := terminal.Screenshot(
				filepath.Join(artifacts, "failure.png"),
				tuitest.ScreenshotOptions{},
			); captureErr != nil {
				t.Logf("failure screenshot: %v", captureErr)
			} else {
				run.Captures = append(run.Captures, "failure.png")
			}
			if text, textErr := terminal.Text(tuitest.TextOptions{}); textErr == nil {
				t.Logf("terminal at %s:\n%s", run.Stage, text)
			}
		}
	})
}

func (j *nativeJourney) launch() session.Data {
	t := j.t
	j.run.Stage = "launch"
	j.expect("Dashboards")
	j.press("Enter")
	j.expect("Native E2E")
	j.press("Enter")
	j.expect("Session launched successfully!")
	first := waitSession(t, j.configDir, 30*time.Second, func(data session.Data) bool { return data.CardID == j.card.ID && data.PID > 0 })
	j.press("Enter")
	// Wait for native UI, not the launcher or an assumed attachment banner.
	waitAgent(t, j.terminal, j.agent.name)
	handleTrust(t, j.terminal, j.agent.name)
	if j.agent.name == "opencode" {
		j.expect(openCodeTestModelName)
	}
	j.capture("launched", "Dashboard Enter launched a persisted native-agent process and Enter attached to the native UI.")

	return first
}

func (j *nativeJourney) detach() {
	j.run.Stage = "detach"
	j.press("Ctrl+K")
	j.expect("Active Sessions")
	// Navigate away and back to establish that ordinary dashboard input works after detach.
	j.press("c")
	j.expect("Settings")
	j.press("Escape")
	j.expect("Active Sessions")
	j.capture("dashboard", "Ctrl+K restored the dashboard; c opened settings and Escape returned using ordinary keyboard input.")
}

func (j *nativeJourney) finish() {
	t := j.t
	j.press("Ctrl+K")
	j.expect("Active Sessions")
	j.press("q")
	timeout := 15 * time.Second
	must(t, j.terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}))
	assertNativeExit(t, j.terminal)
	j.run.Stage = "complete"
}

func (j *nativeJourney) expect(text string) {
	j.t.Helper()
	expectWithTimeout(j.t, j.terminal, text, 45*time.Second)
}

func (j *nativeJourney) press(key string) {
	j.t.Helper()
	must(j.t, j.terminal.Press(key))
}

func (j *nativeJourney) capture(name, assertion string) {
	j.t.Helper()
	_, err := j.terminal.Screenshot(filepath.Join(j.artifacts, name+".png"), tuitest.ScreenshotOptions{})
	must(j.t, err)
	j.run.Assertions = append(j.run.Assertions, assertion)
	j.run.Captures = append(j.run.Captures, name+".png")
}

type nativeAgent struct{ name string }

type tokenUsage struct {
	Input  int `json:"input_tokens"`
	Cached int `json:"cached_input_tokens"`
	Output int `json:"output_tokens"`
}

type journeyRun struct {
	TokenUsage     *tokenUsage `json:"tokenUsage,omitempty"`
	Fingerprint    string      `json:"fingerprint"`
	Revision       string      `json:"revision"`
	Model          string      `json:"model,omitempty"`
	Agent          string      `json:"agent"`
	Command        string      `json:"command"`
	ConversationID string      `json:"conversationId,omitempty"`
	StartedAt      time.Time   `json:"startedAt"`
	FinishedAt     time.Time   `json:"finishedAt"`
	Status         string      `json:"status"`
	Stage          string      `json:"stage"`
	SkipReason     string      `json:"skipReason,omitempty"`
	Size           [2]int      `json:"size"`
	Assertions     []string    `json:"assertions"`
	Captures       []string    `json:"captures"`
}

func expectWithTimeout(t *testing.T, terminal *tuitest.Client, text string, timeout time.Duration) {
	t.Helper()
	must(t, terminal.GetByText(text, tuitest.TextSelectorOptions{}).First().Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}))
}

func must(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

// waitSession polls atomic application records, never treats terminal silence as completion.
func waitSession(t *testing.T, configDir string, timeout time.Duration, ready func(session.Data) bool) session.Data {
	t.Helper()
	deadline := time.NewTimer(timeout)
	defer deadline.Stop()
	tick := time.NewTicker(100 * time.Millisecond)
	defer tick.Stop()
	var latest session.Data
	for {
		paths, err := filepath.Glob(filepath.Join(configDir, "sessions", "*.json"))
		must(t, err)
		for _, path := range paths {
			bytes, readErr := os.ReadFile(path)
			if readErr != nil {
				continue
			}
			var data session.Data
			if json.Unmarshal(bytes, &data) != nil {
				continue
			}
			latest = data
			if ready(data) {
				return data
			}
		}
		select {
		case <-deadline.C:
			t.Fatalf("session state timed out: id=%s status=%s conversations=%v", latest.ID, latest.Status, latest.Conversations)
		case <-tick.C:
		}
	}
}

func handleTrust(t *testing.T, terminal *tuitest.Client, agent string) {
	t.Helper()
	// Trust prompts differ by CLI. Auto-confirm only known workspace prompts,
	// leaving login/model errors to fail the journey rather than skipping it.
	text, err := terminal.Text(tuitest.TextOptions{})
	must(t, err)
	if agent == "codex" && strings.Contains(text, "trust") {
		must(t, terminal.Press("Enter"))
	}
	if agent == "claude" && strings.Contains(text, "trust") {
		must(t, terminal.Press("Enter"))
	}
}

func waitAgent(t *testing.T, terminal *tuitest.Client, agent string) {
	t.Helper()
	pattern := "ctrl\\+p commands"
	switch agent {
	case "codex":
		pattern = "(?i)codex|trust this"
	case "claude":
		pattern = "(?i)claude|trust this"
	}
	timeout := 45 * time.Second
	must(
		t,
		terminal.GetByText("Session launched successfully!", tuitest.TextSelectorOptions{}).
			Wait(tuitest.LocatorWaitOptions{State: tuitest.Hidden, Timeout: &timeout}),
	)
	must(
		t,
		terminal.GetByText(pattern, tuitest.TextSelectorOptions{Regex: true}).
			First().
			Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}),
	)
	checkAgentFailure(t, terminal)
}

func checkAgentFailure(t *testing.T, terminal *tuitest.Client) {
	t.Helper()
	text, err := terminal.Text(tuitest.TextOptions{})
	must(t, err)
	for _, failure := range []string{"Free limit reached", "Authentication required", "Invalid API key", "Server process exited", "Failed to start server"} {
		if strings.Contains(text, failure) {
			t.Fatalf("native agent reported %q", failure)
		}
	}
}

tests/e2e/opencode_test.go.source:
//go:build e2e

package e2e_test

import (
	"bytes"
	"context"
	"encoding/json"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strconv"
	"testing"
	"time"
)

const (
	openCodeTestModel     = "openrouter/openrouter/free"
	openCodeTestModelName = "Free Models Router"
)

type openCodeCredential struct {
	Active        bool   `json:"active"`
	IntegrationID string `json:"integrationID"`
	Value         any    `json:"value"`
}

// Use the installed CLI's supported transfer format, keeping secrets in memory.
// Copying auth.json alone misses credentials migrated into OpenCode's v2 database.
func copyOpenCodeCredentials(t *testing.T, environment map[string]string) {
	t.Helper()
	exported := openCodeCommand(t, nil, nil, "auth", "export")
	var original []openCodeCredential
	must(t, json.Unmarshal(exported, &original))
	// A standalone invocation closes its private server after import/export.
	openCodeCommand(t, environment, exported, "auth", "import", "--standalone")
	imported := openCodeCommand(t, environment, nil, "auth", "export", "--standalone")
	var copied []openCodeCredential
	must(t, json.Unmarshal(imported, &copied))
	configureOpenCodeService(t, environment)
	if !sameOpenCodeCredentials(original, copied) {
		t.Fatal("isolated OpenCode credential import differs from the configured integrations")
	}
}

// Compare by integration/value rather than IDs or ordering chosen by import.
// Never include credential material in assertion errors.
func sameOpenCodeCredentials(original, copied []openCodeCredential) bool {
	if len(original) != len(copied) {
		return false
	}
	remaining := append([]openCodeCredential(nil), copied...)
	for _, credential := range original {
		found := -1
		for i, candidate := range remaining {
			if reflect.DeepEqual(credential, candidate) {
				found = i
				break
			}
		}
		if found < 0 {
			return false
		}
		remaining = append(remaining[:found], remaining[found+1:]...)
	}
	return true
}

func openCodeCommand(t *testing.T, environment map[string]string, input []byte, arguments ...string) []byte {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	command := exec.CommandContext(ctx, "opencode", arguments...)
	command.Env = os.Environ()
	for key, value := range environment {
		command.Env = append(command.Env, key+"="+value)
	}
	if home := environment["HOME"]; home != "" {
		command.Dir = home
	}
	command.Stdin = bytes.NewReader(input)
	// Do not capture stderr or print stdout: either can include exported secrets.
	output, err := command.Output()
	if err != nil {
		t.Fatalf("OpenCode %v failed: %v", arguments, err)
	}
	return output
}

func configureOpenCodeWorkspace(t *testing.T, workspace string) string {
	t.Helper()
	model := openCodeTestModel
	settings := map[string]any{"permission": "allow"}
	if model != "" {
		settings["model"] = model
	}
	encoded, err := json.Marshal(settings)
	must(t, err)
	must(t, os.WriteFile(filepath.Join(workspace, "opencode.json"), encoded, 0o600))
	return model
}

// Service endpoints are runtime state: a copied port can target the user's live server.
func copyOpenCodeConfiguration(t *testing.T, source, destination string) {
	t.Helper()
	entries, err := os.ReadDir(source)
	if os.IsNotExist(err) {
		return
	}
	must(t, err)
	for _, entry := range entries {
		if entry.Name() == "service.json" {
			continue
		}
		copyConfiguration(t, filepath.Join(source, entry.Name()), filepath.Join(destination, entry.Name()))
	}
}

func configureOpenCodeService(t *testing.T, environment map[string]string) {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	must(t, err)
	address, ok := listener.Addr().(*net.TCPAddr)
	if !ok {
		t.Fatal("test listener did not have a TCP address")
	}
	port := strconv.Itoa(address.Port)
	must(t, listener.Close())
	openCodeCommand(t, environment, nil, "service", "set", "port", port)
	t.Cleanup(func() { openCodeCommand(t, environment, nil, "service", "stop") })
}

tests/e2e/provenance_test.go.source:
//go:build e2e

package e2e_test

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// sourceFingerprint uses the Appedia collector's canonical source inventory.
// Images/results are not source inputs; documentation does not affect this hash.
func sourceFingerprint(t *testing.T, root string) string {
	t.Helper()
	exclude := []string{".agents", ".kankuro", "appedia", "kankuro_skills/create-appedia", "kankuro_skills/create-appediff", "tmp"}
	skip := []string{
		".git",
		".hg",
		".svn",
		".maintenance",
		"node_modules",
		"vendor",
		"__pycache__",
		".venv",
		"venv",
		"appedia",
		"appediff",
		".next",
	}
	command := exec.Command("git", "ls-files", "-co", "--exclude-standard", "-z")
	command.Dir = root
	output, err := command.Output()
	must(t, err)
	sources := make(map[string]string)
	for path := range strings.SplitSeq(string(output), "\x00") {
		if !isSource(path) || excludedSource(path, append(skip, exclude...)) {
			continue
		}
		info, statErr := os.Lstat(filepath.Join(root, path))
		if os.IsNotExist(statErr) {
			continue
		}
		must(t, statErr)
		if !info.Mode().IsRegular() {
			continue
		}
		bytes, readErr := os.ReadFile(filepath.Join(root, path))
		must(t, readErr)
		sum := sha256.Sum256(bytes)
		sources[path] = hex.EncodeToString(sum[:])
	}
	slices.Sort(exclude)
	// Map keys are sorted by encoding/json, matching Python's sort_keys=True.
	canonical, err := json.Marshal(map[string]any{"sources": sources, "exclude": exclude})
	must(t, err)
	sum := sha256.Sum256(canonical)
	return hex.EncodeToString(sum[:])
}

func excludedSource(path string, excluded []string) bool {
	directory := filepath.ToSlash(filepath.Dir(path))
	for part := range strings.SplitSeq(directory, "/") {
		if slices.Contains(excluded, part) {
			return true
		}
	}
	return false
}

func isSource(path string) bool {
	extensions := []string{".go", ".py", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".mts", ".cts", ".tf"}
	manifests := []string{
		"go.mod",
		"go.sum",
		"package.json",
		"package-lock.json",
		"pnpm-lock.yaml",
		"yarn.lock",
		"pyproject.toml",
		"uv.lock",
		"requirements.txt",
	}
	return slices.Contains(extensions, filepath.Ext(path)) || slices.Contains(manifests, filepath.Base(path))
}

